/// Everything a `prop_ragdoll` needs from its model: solids per bone, the joints between them
/// (`.phy` `ragdollconstraint`), which solid pairs collide, and the skeleton for the bind pose.
#[derive(Clone, Debug)]
pub struct RagdollInfo {
    pub solids: Vec<RagdollSolid>,
    pub joints: Vec<gm_formats::phy::RagdollConstraint>,
    pub collision_pairs: Vec<(u32, u32)>,
    pub total_mass: f32,
    pub bones: Vec<BoneInfo>,
    pub anim_friction: Option<gm_formats::phy::AnimatedFriction>,
    /// Collision bounds of the spawned entity (the hull box widened by the root solid's convex
    /// extents), unrotated about the root bone: what the sandbox spawn flush measures against.
    pub bounds: gm_sandbox::ModelBounds,
    /// Model attachments (`LookupAttachment` / `GetAttachment`): the eyeposer's `eyes`.
    pub attachments: Vec<AttachmentInfo>,
    /// Flex controllers (`GetFlexNum` / `GetFlexBounds`): the faceposer's sliders.
    pub flex_controllers: Vec<gm_formats::mdl::FlexController>,
    /// Movement sequences a player's death ragdoll can start from, frames sampled per bone.
    pub death_poses: Vec<DeathPose>,
}

/// One sequence's frames as local bone poses (in `RagdollInfo::bones` order), played at `fps`.
#[derive(Clone, Debug, Default)]
pub struct DeathPose {
    pub sequence: String,
    pub fps: f32,
    pub frames: Vec<Vec<(Vec3, Quat)>>,
}

