impl ToolSettingKind {
    pub fn from_u8(v: u8) -> Self {
        match v {
            1 => Self::Bool,
            2 => Self::Text,
            3 => Self::Help,
            4 => Self::Key,
            5 => Self::Color,
            6 => Self::Choice,
            7 => Self::Presets,
            8 => Self::Button,
            _ => Self::Number,
        }
    }

    pub fn as_u8(self) -> u8 {
        match self {
            Self::Number => 0,
            Self::Bool => 1,
            Self::Text => 2,
            Self::Help => 3,
            Self::Key => 4,
            Self::Color => 5,
            Self::Choice => 6,
            Self::Presets => 7,
            Self::Button => 8,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub enum Verdict {
    Allow,
    Cancel,
    /// `PlayerDamage` / `NpcDamage`: deal this amount instead; `EmitSound`: this volume.
    Amount(f32),
    /// `SetModel`: use this model path instead; `EmitSound`: this sound name.
    Text(String),
}

/// Answers `Request`s; the server lets go of the hook while it runs, so the hook may use the
/// server (its own writes are not asked again).
/// The move of one player command as the `CMoveData` hooks see it.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct MoveData {
    pub origin: Vec3,
    pub velocity: Vec3,
    /// View angles the move steers by.
    pub angles: Vec3,
    pub buttons: u32,
    /// Buttons of the previous command (`GetOldButtons`).
    pub old_buttons: u32,
    /// Forward / side / up move.
    pub moves: Vec3,
    /// Ground speed cap of this command (walk or run speed).
    pub max_speed: f32,
    /// Step height, jump impulse and ground wish-speed cap the mover will use for this command
    /// (`SetFinalStepHeight` / `SetFinalJumpVelocity` / `SetFinalIdealVelocity`).
    pub step_height: f32,
    pub jump_power: f32,
    pub ideal_velocity: f32,
}

impl MoveData {
    /// The write-back text: origin, velocity, buttons, moves, angles, max speed.
    pub fn to_text(&self) -> String {
        let (o, v, m, a) = (self.origin, self.velocity, self.moves, self.angles);
        format!(
            "{} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {} {}",
            o.x,
            o.y,
            o.z,
            v.x,
            v.y,
            v.z,
            self.buttons,
            m.x,
            m.y,
            m.z,
            a.x,
            a.y,
            a.z,
            self.max_speed,
            self.step_height,
            self.jump_power,
            self.ideal_velocity
        )
    }

    /// `self` with the fields of a write-back text applied (`None` for a malformed text).
    pub fn parse(&self, text: &str) -> Option<MoveData> {
        let f: Vec<f32> = text
            .split_whitespace()
            .map(|t| t.parse::<f32>().ok())
            .collect::<Option<Vec<f32>>>()?;
        if !(f.len() == 14 || f.len() == 17) || f.iter().any(|v| !v.is_finite()) {
            return None;
        }
        Some(MoveData {
            origin: Vec3::new(f[0], f[1], f[2]),
            velocity: Vec3::new(f[3], f[4], f[5]),
            buttons: f[6].max(0.0) as u32,
            moves: Vec3::new(f[7], f[8], f[9]),
            angles: Vec3::new(f[10], f[11], f[12]),
            max_speed: f[13].max(0.0),
            old_buttons: self.old_buttons,
            step_height: f.get(14).map_or(self.step_height, |v| v.max(0.0)),
            jump_power: f.get(15).map_or(self.jump_power, |v| v.max(0.0)),
            ideal_velocity: f.get(16).map_or(self.ideal_velocity, |v| v.max(0.0)),
        })
    }
}

pub type RequestHook = Box<dyn FnMut(&mut Server<'_>, &Request) -> Verdict>;

/// The volume of a hull's touch on a prop from its approach speed: the game's walking player
/// plays plastic_box_impact_soft2 at 0.061 (100 u/s) and 0.267 (296 u/s, `move_prop_step_*`)
/// - `0.061 * (speed / 100)^1.36` through both; the wood crate at a sprint reads 0.6, its
///   script's own cap.
pub fn touch_volume(speed: f32) -> f32 {
    (0.061 * (speed / 100.0).powf(1.36)).min(1.0)
}

/// Whether a hull's touch on a prop is heard: stepping onto it always is (`move_prop_step_*`,
/// the tile plate at 100 and ~300 u/s), running into its side only at speed (the wood crate
/// is silent at a 100 u/s walk and plays at a 400 u/s sprint, `move_prop_block_*`; the
/// threshold between is not measured).
pub fn touch_sounds(normal: Vec3, speed: f32) -> bool {
    normal.z > 0.7 || speed >= IMPACT_SOUND_FULL_SPEED
}

/// `(speed / IMPACT_SOUND_FULL_SPEED)^2` capped at 1; `None` under the audible threshold.
pub fn impact_volume(speed: f32) -> Option<f32> {
    (speed >= IMPACT_SOUND_MIN_SPEED).then(|| (speed / IMPACT_SOUND_FULL_SPEED).powi(2).min(1.0))
}

/// A sliding contact scrapes from this slip speed (units/s) up; under it the loop fades out
/// (`phys_sound_slide_crate*`: the game's loop starts the tick after the push at every push
/// speed tried, 66 u/s and up, and fades from ~40 u/s down).
pub const SCRAPE_SOUND_MIN_SPEED: f32 = 40.0;
/// The scrape loop's volume factor: `slip / 300` capped at `SCRAPE_SOUND_MAX` (the game's
/// factor is its friction energy, capped at 0.5: 0.5 from 135 u/s up, 0.15..0.16 at 66 and
/// 114 u/s in two recordings - contact-point noise, not a law; the cap is exact).
pub const SCRAPE_SOUND_MAX: f32 = 0.5;
/// The fade of a scrape loop that stops (the game's envelope: 0.025 per tick from 0.25).
pub const SCRAPE_SOUND_FADE: f32 = 0.15;

/// Volume factor of the scrape loop at a slip speed; `None` under the threshold.
pub fn scrape_volume(slip: f32) -> Option<f32> {
    (slip >= SCRAPE_SOUND_MIN_SPEED).then(|| (slip / 300.0).min(SCRAPE_SOUND_MAX))
}

/// Result of a tool gun click on the server.
#[derive(Clone, Debug, PartialEq)]
pub enum ToolClick {
    /// A Rust stool handled it (its return value).
    Done(bool),
    /// No hit at all.
    Miss,
    /// The sandbox has no such stool: scripts may (hit passed on).
    Unknown(ToolHit),
}

/// A `.gmr` package with client-realm actors, ready to be handed to clients.
pub struct PublishedPackage {
    pub id: String,
    pub version: String,
    pub sha: [u8; 32],
    pub bytes: Vec<u8>,
}

/// Game-logic hooks around server commands (the addon runtime implements them).
pub trait ServerHooks {
    /// `prop.spawn_request`: false refuses the spawn.
    fn prop_spawn_request(&mut self, server: &mut Server<'_>, player: u32, model: &str) -> bool;
    /// `entity.spawned` after a prop was created.
    fn entity_spawned(&mut self, server: &mut Server<'_>, player: u32, ent: u32);
    /// `AcceptInput` on a map input (an output firing, `ent_fire`, `+use`): false drops it.
    fn accept_input(
        &mut self,
        _server: &mut Server<'_>,
        _ent: u32,
        _input: &str,
        _activator: u32,
        _caller: u32,
        _value: &str,
    ) -> bool {
        true
    }
    /// `entity.removed` after an entity left the table through a player's command.
    fn entity_removed(&mut self, _server: &mut Server<'_>, _player: u32, _ent: u32) {}
    /// `GetGameDescription`: what the server advertises as its game (None keeps the last).
    fn game_description(&mut self, _server: &mut Server<'_>) -> Option<String> {
        None
    }
    /// A click of a stool the sandbox does not know: a scripted tool may handle it.
    fn tool_click(
        &mut self,
        _server: &mut Server<'_>,
        _player: u32,
        _tool: &str,
        _hit: &ToolHit,
        _right: bool,
        _settings: &[(String, String)],
    ) -> bool {
        false
    }
    /// A gmod_tool reload on a mode no Rust stool owns (`TOOL:Reload`); true when a script did
    /// something.
    fn tool_reload(
        &mut self,
        _server: &mut Server<'_>,
        _player: u32,
        _tool: &str,
        _hit: &ToolHit,
        _settings: &[(String, String)],
    ) -> bool {
        false
    }
    /// Admin command: hot reload of a loaded addon by id.
    fn reload_addon(&mut self, _addon: &str) -> Result<String, String> {
        Err("no addon runtime".into())
    }
    /// `player.disconnected` after the player left the table (its props stay).
    fn player_disconnected(&mut self, _server: &mut Server<'_>, _player: u32) {}
    /// This tick's `GameEvent`s, after the tick and before `post_tick`.
    fn game_events(&mut self, _server: &mut Server<'_>, _events: Vec<GameEvent>) {}
    /// A tool gun click that hit something, before the stool runs: `false` cancels it.
    fn tool_before(
        &mut self,
        _server: &mut Server<'_>,
        _player: u32,
        _tool: &str,
        _right: bool,
        _hit: &ToolHit,
    ) -> bool {
        true
    }
    /// After a tool gun click that hit something: `done` is the stool's return value.
    fn tool_after(
        &mut self,
        _server: &mut Server<'_>,
        _player: u32,
        _tool: &str,
        _right: bool,
        _done: bool,
    ) {
    }
    /// A player's chat line before it is sent: `None` drops it, `Some` is what every client
    /// gets (possibly rewritten).
    fn player_chat(
        &mut self,
        _server: &mut Server<'_>,
        _player: u32,
        text: &str,
    ) -> Option<String> {
        Some(text.to_owned())
    }
    /// Whether `listener` sees `speaker`'s chat line (`GM:PlayerCanSeePlayersChat`).
    fn player_can_see_chat(
        &mut self,
        _server: &mut Server<'_>,
        _listener: u32,
        _speaker: u32,
        _text: &str,
    ) -> bool {
        true
    }
    /// Whether `listener` hears `talker`'s voice (`GM:PlayerCanHearPlayersVoice`).
    fn player_can_hear_voice(
        &mut self,
        _server: &mut Server<'_>,
        _listener: u32,
        _talker: u32,
    ) -> bool {
        true
    }
    /// `save <name>`: the runtime's data for the file - global blobs (`saverestore` save hooks
    /// by name) and one blob per scripted entity (by id); empty by default.
    fn save_data(
        &mut self,
        _server: &mut Server<'_>,
        _ents: &[u32],
    ) -> (BTreeMap<String, String>, BTreeMap<u32, String>) {
        Default::default()
    }
    /// `load <name>`: the blobs back, entities by their new ids.
    fn restore_data(
        &mut self,
        _server: &mut Server<'_>,
        _globals: &BTreeMap<String, String>,
        _ents: &[(u32, String)],
        _map: &str,
        _timestamp: i64,
    ) {
    }
    /// `load <name>` could not be read or parsed (`GM:LoadGModSaveFailed`).
    fn restore_failed(&mut self, _server: &mut Server<'_>, _error: &str) {}
    /// A console line a client typed that the client did not know (`concommand.Add` commands):
    /// true when a script command took it.
    fn player_command(
        &mut self,
        _server: &mut Server<'_>,
        _player: u32,
        _cmd: &str,
        _args: &[String],
    ) -> bool {
        false
    }
    /// An addon message from a client's actor (`net.send` on the client).
    fn net_message(&mut self, _server: &mut Server<'_>, _player: u32, _name: &str, _data: &[u8]) {}
    /// Addon messages queued by server actors: (player or 0 for everyone, name, payload).
    fn drain_net(&mut self) -> Vec<(u32, String, Vec<u8>)> {
        Vec::new()
    }
    /// Around every tick.
    fn pre_tick(&mut self, server: &mut Server<'_>);
    fn post_tick(&mut self, server: &mut Server<'_>);
    /// After the tick's player commands were applied (the game runs console commands at the end
    /// of the frame, after `Tick`): `cvar.changed` for what they changed.
    fn after_commands(&mut self, _server: &mut Server<'_>) {}
    /// Packages (re)built since the last call: addons with client-realm actors as they were
    /// loaded or hot-reloaded, for the network to publish to clients.
    fn drain_published(&mut self) -> Vec<PublishedPackage> {
        Vec::new()
    }
}

/// A prop convex in the world for the use sweeps: outward planes and the AABB.
type WorldConvex = (Vec<(Vec3, f32)>, (Vec3, Vec3));

/// Loads a model by name on first use.
pub type ModelLoader = Box<dyn FnMut(&str) -> Option<ModelInfo>>;

/// A weapon class an addon registered (`weapon.register`, the game's `weapons.Register` of a
/// SWEP): what the server needs to run it and the clients to draw it. Behaviour measured on
/// `weapon_base` (`lua_swep`): deploy blocks fire for 0.2 s, a semi-automatic primary fires on
/// a press edge only (a press while blocked is lost), an automatic one every `primary_delay`
/// while held, the secondary once per press, a reload takes `reload_time` and refills the clip
/// from the reserve at its end, an empty clip plus a press starts the reload.
/// `ENT:SetUseType`: how `Use` follows the E key (measured `lua_sent`).
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum UseType {
    /// `CONTINUOUS_USE`: every tick E is held (exactly one per tick, no lag tick).
    Continuous,
    /// `SIMPLE_USE`: once per press.
    Simple,
    /// `ONOFF_USE`: `use` on the press, `use_off` on the release.
    OnOff,
}

