/// What the network layer knows about a player's connection (`Player:Ping` / `PacketLoss` /
/// `GetTimeoutSeconds` / `IPAddress`), refreshed every tick.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct ConnInfo {
    pub ping_ms: f32,
    pub loss_pct: f32,
    /// Seconds since the last packet from the player.
    pub timeout_secs: f32,
    pub addr: String,
}

/// Per-player movement tunables set by scripts (`Player:SetWalkSpeed` and friends); `None`
/// keeps the server's `MoveConfig` value. Swapped into the mover around that player's move.
#[derive(Clone, Copy, Debug, Default, PartialEq)]
pub struct MoveOverride {
    pub walk_speed: Option<f32>,
    pub run_speed: Option<f32>,
    pub slow_walk_speed: Option<f32>,
    pub jump_power: Option<f32>,
    pub step_size: Option<f32>,
    pub crouched_walk_speed: Option<f32>,
    pub duck_time: Option<f32>,
    pub unduck_time: Option<f32>,
    pub max_velocity: Option<f32>,
    pub stand_eye: Option<f32>,
    pub duck_eye: Option<f32>,
    pub hull_half: Option<f32>,
    pub stand_height: Option<f32>,
    pub duck_height: Option<f32>,
    pub ladder_speed: Option<f32>,
    pub time_scale: Option<f32>,
    pub sprint_enabled: Option<bool>,
    pub force_sprint: Option<bool>,
}

impl MoveOverride {
    pub fn apply(&self, cfg: &mut gm_move::MoveConfig) {
        if let Some(v) = self.walk_speed {
            cfg.walk_speed = v;
        }
        if let Some(v) = self.run_speed {
            cfg.run_speed = v;
        }
        if let Some(v) = self.jump_power {
            cfg.jump_power = v;
        }
        if let Some(v) = self.step_size {
            cfg.step_size = v;
        }
        if let Some(v) = self.crouched_walk_speed {
            cfg.crouched_walk_speed = v;
        }
        if let Some(v) = self.duck_time {
            cfg.duck_time = v;
        }
        if let Some(v) = self.unduck_time {
            cfg.unduck_time = v;
        }
        if let Some(v) = self.max_velocity {
            cfg.max_velocity = v;
        }
        if let Some(v) = self.stand_eye {
            cfg.stand_eye = v;
        }
        if let Some(v) = self.duck_eye {
            cfg.duck_eye = v;
        }
        if let Some(v) = self.hull_half {
            cfg.hull_half = v;
        }
        if let Some(v) = self.stand_height {
            cfg.stand_height = v;
        }
        if let Some(v) = self.duck_height {
            cfg.duck_height = v;
        }
        if let Some(v) = self.ladder_speed {
            cfg.ladder_speed = v;
        }
        if let Some(v) = self.time_scale {
            cfg.time_scale = v;
        }
        if let Some(v) = self.sprint_enabled {
            cfg.sprint_enabled = v;
        }
        if let Some(v) = self.force_sprint {
            cfg.force_sprint = v;
        }
        if let Some(v) = self.slow_walk_speed {
            cfg.slow_walk_speed = v;
        }
    }

    /// This player's hull (`Player:SetHull` / `SetHullDuck` over the server config).
    pub fn hull(&self, cfg: &gm_move::MoveConfig, ducked: bool) -> (Vec3, Vec3) {
        gm_move::hull_of(&self.effective(cfg), ducked)
    }

    /// This player's eye height (`Player:SetViewOffset` / `SetViewOffsetDucked`).
    pub fn eye(&self, cfg: &gm_move::MoveConfig, ducked: bool) -> f32 {
        gm_move::eye_height_of(&self.effective(cfg), ducked)
    }

    pub fn effective(&self, cfg: &gm_move::MoveConfig) -> gm_move::MoveConfig {
        let mut c = *cfg;
        self.apply(&mut c);
        c
    }

    /// Field `which` (0 walk, 1 run, 2 jump, 3 step, 4 crouched walk, 5 duck time, 6 unduck
    /// time, 7 max velocity, 8 standing eye, 9 ducked eye, 10 hull half width, 11 standing
    /// height, 12 ducked height, 13 ladder climb speed, 14 lagged movement scale, 15 sprint
    /// enabled as 0 / 1, 16 forced sprint as 0 / 1, 17 slow walk speed); `None` clears it.
    pub fn set(&mut self, which: u8, value: Option<f32>) -> bool {
        let v = value.filter(|v| v.is_finite()).map(|v| v.max(0.0));
        match which {
            0 => self.walk_speed = v,
            1 => self.run_speed = v,
            2 => self.jump_power = v,
            3 => self.step_size = v,
            4 => self.crouched_walk_speed = v,
            5 => self.duck_time = v,
            6 => self.unduck_time = v,
            7 => self.max_velocity = v,
            8 => self.stand_eye = v,
            9 => self.duck_eye = v,
            10 => self.hull_half = v,
            11 => self.stand_height = v,
            12 => self.duck_height = v,
            13 => self.ladder_speed = v,
            14 => self.time_scale = v,
            15 => self.sprint_enabled = value.map(|v| v > 0.5),
            16 => self.force_sprint = value.map(|v| v > 0.5),
            17 => self.slow_walk_speed = v,
            _ => return false,
        }
        true
    }
}
