/// Classes that engage players on sight.
/// Sandbox NPC entries that are not AI NPCs in the game (CBaseAnimating): they report no
/// NPC state and no schedule (server_npc_spawn 261107: the grub reads -1 / -1).
pub fn npc_non_ai(class: &str) -> bool {
    matches!(class, "npc_antlion_grub" | "npc_helicoptersensor")
}

/// AI NPCs without schedules: the game's helicopter reads schedule -1 for good while IDLE
/// (server_npc_spawn 261107; the gunship and dropship read 1 there).
pub fn npc_schedule_less(class: &str) -> bool {
    matches!(class, "npc_helicopter")
}

/// Attacking classes that never walk at their enemy (the strider stands where it spawned
/// through server_npc_tick_strider 261107).
pub fn npc_stands_in_combat(class: &str) -> bool {
    matches!(class, "npc_strider")
}

/// Ticks after the sighting think an idle NPC of `class` keeps IDLE before COMBAT
/// (NPC_REACTION_TICKS); zero for the classes with their own measured wake-up: zombies wake
/// angry on the sighting think, the antlion, guard and strider three thinks after it
/// (through `wake_until`), headcrabs act on the first, birds have their own sit time.
pub fn npc_reaction_ticks(class: &str) -> u64 {
    if ai::class_sched_family(class) == Some("zombie")
        || class.starts_with("npc_headcrab")
        || matches!(
            class,
            "npc_antlion"
                | "npc_antlionguard"
                | "npc_strider"
                | "npc_crow"
                | "npc_pigeon"
                | "npc_seagull"
        )
    {
        0
    } else {
        NPC_REACTION_TICKS
    }
}

