/// The HL2 weapons' activity tables (`acttable_t` of weapon_smg1 / ar2 / shotgun / pistol /
/// 357): the activity an armed NPC's base activity becomes, which is what its model carries
/// (combine_soldier_anims has ACT_IDLE_SMG1 / ACT_RUN_RIFLE, no plain ACT_IDLE / ACT_RUN).
pub fn npc_weapon_activity(weapon: &str, act: &str) -> Option<&'static str> {
    let rifle = |smg: &'static str, ar2: &'static str, sg: &'static str| match weapon {
        "weapon_smg1" => Some(smg),
        "weapon_ar2" => Some(ar2),
        "weapon_shotgun" => Some(sg),
        // the monk's annabelle: SMG1 poses, shotgun firing (monk Idle_Angry_SMG1 at spawn)
        "weapon_annabelle" => Some(if sg.starts_with("ACT_RANGE_ATTACK") {
            sg
        } else {
            smg
        }),
        _ => None,
    };
    let pistol = |p: &'static str| matches!(weapon, "weapon_pistol" | "weapon_357").then_some(p);
    match act {
        "ACT_IDLE" => rifle("ACT_IDLE_SMG1", "ACT_IDLE_SMG1", "ACT_IDLE_SMG1")
            .or_else(|| pistol("ACT_IDLE_PISTOL")),
        // a companion's relaxed idle (golden 261031 server_npc_spawn: barney Idle_Relaxed_SMG1_3,
        // the citizen's pistol Pistol_idle)
        "ACT_IDLE_RELAXED" => rifle(
            "ACT_IDLE_SMG1_RELAXED",
            "ACT_IDLE_SMG1_RELAXED",
            "ACT_IDLE_SHOTGUN_RELAXED",
        )
        .or_else(|| pistol("ACT_IDLE_PISTOL")),
        "ACT_IDLE_ANGRY" => rifle(
            "ACT_IDLE_ANGRY_SMG1",
            "ACT_IDLE_ANGRY_SMG1",
            "ACT_IDLE_ANGRY_SHOTGUN",
        )
        .or_else(|| pistol("ACT_IDLE_ANGRY_PISTOL")),
        "ACT_RANGE_ATTACK1" => rifle(
            "ACT_RANGE_ATTACK_SMG1",
            "ACT_RANGE_ATTACK_AR2",
            "ACT_RANGE_ATTACK_SHOTGUN",
        )
        .or_else(|| pistol("ACT_RANGE_ATTACK_PISTOL")),
        "ACT_RANGE_ATTACK1_LOW" => rifle(
            "ACT_RANGE_ATTACK_SMG1_LOW",
            "ACT_RANGE_ATTACK_AR2_LOW",
            "ACT_RANGE_ATTACK_SHOTGUN_LOW",
        )
        .or_else(|| pistol("ACT_RANGE_ATTACK_PISTOL_LOW")),
        "ACT_RUN" => rifle("ACT_RUN_RIFLE", "ACT_RUN_RIFLE", "ACT_RUN_RIFLE")
            .or_else(|| pistol("ACT_RUN_PISTOL")),
        "ACT_WALK" => rifle("ACT_WALK_RIFLE", "ACT_WALK_RIFLE", "ACT_WALK_RIFLE")
            .or_else(|| pistol("ACT_WALK_PISTOL")),
        "ACT_RUN_AIM" => rifle(
            "ACT_RUN_AIM_RIFLE",
            "ACT_RUN_AIM_RIFLE",
            "ACT_RUN_AIM_SHOTGUN",
        )
        .or_else(|| pistol("ACT_RUN_AIM_PISTOL")),
        "ACT_WALK_AIM" => rifle(
            "ACT_WALK_AIM_RIFLE",
            "ACT_WALK_AIM_RIFLE",
            "ACT_WALK_AIM_SHOTGUN",
        )
        .or_else(|| pistol("ACT_WALK_AIM_PISTOL")),
        "ACT_RELOAD" => rifle("ACT_RELOAD_SMG1", "ACT_RELOAD_SMG1", "ACT_RELOAD_SHOTGUN")
            .or_else(|| pistol("ACT_RELOAD_PISTOL")),
        "ACT_COVER_LOW" => rifle(
            "ACT_COVER_SMG1_LOW",
            "ACT_COVER_SMG1_LOW",
            "ACT_COVER_SMG1_LOW",
        )
        .or_else(|| pistol("ACT_COVER_PISTOL_LOW")),
        _ => None,
    }
}

/// Hitscan weapon an NPC fires: (ammo, pellets per shot). Melee and projectile weapons give None.
pub fn npc_weapon_shot(weapon: &str) -> Option<(&'static str, u8)> {
    match weapon {
        "weapon_pistol" => Some(("Pistol", 1)),
        "weapon_smg1" => Some(("SMG1", 1)),
        "weapon_ar2" => Some(("AR2", 1)),
        "weapon_shotgun" => Some(("Buckshot", 7)),
        "weapon_357" => Some(("357", 1)),
        _ => None,
    }
}

/// The shot an NPC fires with `weapon`: the HL2 table above, else a scripted SWEP's ammo type
/// (one pellet) so `NPC:Give("my_swep")` arms the NPC with the addon's ammo.
pub fn npc_weapon_shot_in(weapon: &str, scripted: &[ScriptedWeapon]) -> Option<(String, u8)> {
    if let Some((ammo, pellets)) = npc_weapon_shot(weapon) {
        return Some((ammo.to_string(), pellets));
    }
    scripted
        .iter()
        .find(|w| w.class == weapon && !w.ammo.is_empty())
        .map(|w| (w.ammo.clone(), 1))
}

/// Whether an NPC hunts players: a scripted relationship toward players (`D_HT` hates, any
/// other disposition does not) overrides the class table.
/// NPC classes that are VPhysics objects in the game (measured `server_npc_spawn`: the floor
/// turret sinks and tilts after its spawn, the rollermine rolls off its spawn height).
pub fn npc_physics_class(class: &str) -> bool {
    matches!(class, "npc_turret_floor" | "npc_rollermine")
}

pub fn npc_hostile_to_players(n: &Npc) -> bool {
    match n.relation {
        Some(d) => d == 1,
        None => npc_hostile(&n.class),
    }
}

/// A melee attack: damage per hit, 2D reach (u), swing length and the tick inside the swing
/// the damage lands, and the speed the hit launches the player at (u/s, away from the NPC).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NpcMelee {
    pub damage: f32,
    pub reach: f32,
    pub swing_ticks: u64,
    pub hit_tick: u64,
    /// A second hit this many ticks after the first (the fast zombie's double claw).
    pub hit_gap: Option<u64>,
    /// Hits the move lands `hit_gap` apart (the hunter's flechette volley is 8).
    pub hits: u8,
    pub punch: f32,
    /// A sideways shove on the hit (u/s), alternating left / right per hit: the fast
    /// zombie's scratches move the bot ~4 u aside and 1..2 u back (server_npc_melee_fastzombie).
    pub side: f32,
    /// Upward speed the hit adds, lifting the player off the floor for its rise (no friction
    /// meanwhile): the zombie claw (server_npc_melee_zombie 261105: ~320 u/s for ~6 ticks
    /// before friction, 63 u of slide).
    pub lift: f32,
    /// Closes in at the run gait.
    pub run: bool,
    /// The move begins once the player is within this 2D distance (the reach by default).
    pub start_range: f32,
    /// A ground dash toward the player over the first NPC_LUNGE_TICKS of the swing (u).
    pub lunge: f32,
    /// A back-step after the hit over NPC_LUNGE_TICKS (u).
    pub recoil: f32,
    /// The hit is a poison bite: after the damage the player is left with at least 1 hp.
    pub poison: bool,
    /// After the last hit the body slides back from the player at this pace (u/tick), decaying
    /// `NPC_ROAR_SLIDE_DECAY` a tick while the swing lasts: the fast zombie's roar
    /// (server_npc_melee_fastzombie rows 116..193: 3.3, 3.0, 2.7 .. 1.0 u a think; 19.4..19.7 u
    /// a cycle: 869.3 -> 889, 866.4 -> 886, 863.6 -> 883).
    pub roar_slide: f32,
    /// Ticks into the swing when the roar (its sequence and the slide) begins: the fast zombie
    /// scratches at 0 and 14 and roars from 35 (server_npc_melee_fastzombie rows 88/102/123).
    pub roar_at: u64,
    /// Ticks into the swing when the lunge leaves the ground (the antlion's pounce stands 13
    /// ticks first, server_npc_melee_antlion rows 207..220) and how many ticks it flies
    /// (0 = `NPC_LUNGE_TICKS`).
    pub lunge_at: u64,
    pub lunge_ticks: u64,
    /// Ticks after the hit before the recoil step back begins (the antlion stands 21 ticks at
    /// 832 before stepping back to 853).
    pub recoil_delay: u64,
}

const NPC_ROAR_SLIDE_DECAY: f32 = 0.982;

/// Half width of the player hull a lunge's root motion stops against.
const NPC_LUNGE_TARGET_HALF: f32 = 16.0;

const NPC_LUNGE_TICKS: u64 = 21;
/// The recoil's step back takes this long (the antlion's 832 -> 844 -> 853 within 12 ticks).
const NPC_RECOIL_TICKS: u64 = 12;
/// TASK_WANDER 480384 of SCHED_ZOMBIE_WANDER_MEDIUM: 48..384 u.
const ZOMBIE_WANDER_MIN: u32 = 48;
const ZOMBIE_WANDER_MAX: u32 = 384;
/// Poison on top of the bite (the game's poison headcrab leaves the player at 1 hp).
const NPC_POISON_DAMAGE: f32 = 94.0;
/// A poison zombie's crab throw: released NPC_CRAB_THROW_HEIGHT above the zombie's origin at
/// NPC_CRAB_THROW_SPEED u/s horizontal and NPC_CRAB_THROW_VZ up (golden 261105: 4.7 u/tick,
/// apex +24 u after 17 ticks under NPC_GRAVITY).
const NPC_CRAB_THROW_HEIGHT: f32 = 65.0;
const NPC_CRAB_THROW_SPEED: f32 = 315.0;
const NPC_CRAB_THROW_VZ: f32 = 170.5;
/// A crab hopping off the NPC it stands on (TASK_HEADCRAB_HOP_OFF_NPC): a random horizontal
/// direction at this speed and the same speed up (golden 261105: 21 u in xy per 0.105 s
/// think, z +17.7 on the first).
const NPC_CRAB_HOP_OFF_SPEED: f32 = 200.0;
const NPC_POISON_WARNING_TICKS: u64 = 77;
/// SCHED_COMBINE_SUPPRESS lasts the first volley: the game read 88 through the 40-tick wait
/// after the spawn (t363) and 100 from the think at t365, 35 after the sighting think at
/// t330 (server_npc_grenade_soldier).
const NPC_SUPPRESS_TICKS: u64 = 35;
/// An armed body running with its enemy in sight faces it (RunAIMALL1, the all-directions
/// blend) for 13 thinks of the run and then turns to its path: the lone soldier of
/// server_npc_grenade_soldier and the squad leader both leave (992,-499) for the reload cover
/// facing the bot and turn at (975,-332), rows 341 -> 432 and 388 -> 479; the squad mate
/// 300 -> 398. Nothing blocks a sight line there (eye, chest and feet lines stay clear).
/// An enemy sighted again on the way restarts the window (server_npc_grenade_soldier_wall: the
/// bot teleports back into view at row 138 of the line-of-fire run, RunAIMALL1 and a burst on
/// the move follow until the spot is reached at 201).
const NPC_AIM_RUN_TICKS: u64 = 91;
/// Thinks of COMBAT_FACE a zombie spends on its respawned enemy before chasing again.
const NPC_REACQUIRE_FACE_TICKS: u64 = 21;

const MELEE_PLAIN: NpcMelee = NpcMelee {
    damage: 0.0,
    reach: 0.0,
    swing_ticks: 0,
    hit_tick: 0,
    hit_gap: None,
    hits: 1,
    punch: 0.0,
    side: 0.0,
    lift: 0.0,
    run: false,
    start_range: 0.0,
    lunge: 0.0,
    recoil: 0.0,
    poison: false,
    roar_slide: 0.0,
    roar_at: 0,
    lunge_at: 0,
    lunge_ticks: 0,
    recoil_delay: 0,
};

/// A leap attack: the NPC throws itself at the player on a ballistic arc (`speed` u/s
/// horizontal, aimed `aim_height` above the player's origin under NPC_GRAVITY), damages on
/// touching the player's hull, hangs there `hang_ticks`, drops, runs `retreat` u away and
/// leaps again after `rest_ticks`.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NpcLeap {
    pub speed: f32,
    pub aim_height: f32,
    pub damage: f32,
    pub punch: f32,
    pub hang_ticks: u64,
    pub retreat: f32,
    pub rest_ticks: u64,
    /// The touch is a poison bite (NPC_POISON_DAMAGE on top, never below 1 hp).
    pub poison: bool,
    /// Ticks the NPC stands where it landed before its next decision (the antlion jump).
    pub stand_ticks: u64,
    /// Thinks between the sighting think and the leap's pre-think (classic crab: 1).
    pub sight_thinks: u64,
    /// The pre-think already shows the leap's label (classic); the fast crab keeps its label.
    pub pre_label: bool,
    /// The label of a turn in place (None: TurnLeft / TurnRight by direction).
    pub turn_sequence: Option<&'static str>,
    /// Sequences played in flight, on the hull / the floor, and on the run-away.
    pub leap_sequence: Option<&'static str>,
    pub land_sequence: Option<&'static str>,
    pub run_sequence: Option<&'static str>,
}

/// A long jump that closes distance (the antlion's `fly_in`): wound up for `windup_ticks`
/// standing still, then the `leap` arc to where the target stands.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct NpcJump {
    pub leap: NpcLeap,
    pub min_range: f32,
    pub max_range: f32,
    pub windup_ticks: u64,
}

/// Headcrabs a class carries to throw.
pub fn npc_crabs(class: &str) -> u8 {
    match class {
        "npc_poisonzombie" => NPC_POISON_CRABS,
        _ => 0,
    }
}

/// Measured in server_npc_run_antlion (bot 1100 u away): the antlion ran to ~600 u, stood 42
/// ticks, then flew 51.23 u per think (483 u/s) for 13 thinks, landing ~120 u PAST the
/// player, then `jump_stop` 35 ticks + `turn_left` 35 ticks before its melee cycle. Ours
/// lands on the player's position (the overshoot is left as a residual) and jumps again
/// no sooner than NPC_JUMP_COOLDOWN (own value: one jump per approach in the recording).
pub fn npc_jump(class: &str) -> Option<NpcJump> {
    match class {
        "npc_antlion" => Some(NpcJump {
            leap: NpcLeap {
                speed: 483.0,
                aim_height: 0.0,
                damage: 0.0,
                punch: 0.0,
                hang_ticks: 0,
                retreat: 0.0,
                rest_ticks: NPC_JUMP_COOLDOWN,
                poison: false,
                stand_ticks: 70,
                sight_thinks: 0,
                pre_label: false,
                turn_sequence: None,
                leap_sequence: None,
                land_sequence: None,
                run_sequence: None,
            },
            min_range: 300.0,
            max_range: 600.0,
            windup_ticks: 42,
        }),
        _ => None,
    }
}

pub const NPC_JUMP_COOLDOWN: u64 = 660;
/// Poison zombie: three crabs on its back, thrown no closer together than this (one throw
/// per 859 ticks seen in server_npc_melee_poisonzombie_long, the zombie busy in between).
pub const NPC_POISON_CRABS: u8 = 3;
pub const NPC_CRAB_THROW_COOLDOWN: u64 = 860;
/// The throw starts once the enemy is this close: the game's zombie walks in from 179 u and
/// throws at 141 u (server_npc_melee_poisonzombie).
pub const NPC_CRAB_THROW_RANGE: f32 = 145.0;

pub const NPC_LEAP_RANGE: f32 = 256.0;
/// Cover and squads (our rules): a cover point lies within this of the NPC, is a navmesh
/// vertex the target's eye cannot see, and is not within NPC_COVER_SPACING of a squadmate's;
/// the NPC stays NPC_COVER_TICKS once there and waits NPC_COVER_COOLDOWN before the next run.
/// Squadmates are NPCs of the same spawn key within NPC_SQUAD_RANGE.
pub const NPC_COVER_RANGE: f32 = 512.0;
/// CAI_BaseNPC::CoverRadius: how far from the threat the node graph is searched for cover.
pub const NPC_COVER_RADIUS: f32 = 1024.0;
/// Within this of the cover point the body counts as arrived (the reload starts there).
pub const NPC_COVER_ARRIVE: f32 = 24.0;
/// A squadmate's cover is avoided only this long after it chose it (the engine's node lock;
/// the leader took the mate's node 84 ticks later in server_npc_squad_soldier 261104).
pub const NPC_COVER_LOCK_TICKS: u64 = 66;
pub const NPC_COVER_SPACING: f32 = 32.0;
pub const NPC_COVER_TICKS: u64 = 200;
pub const NPC_COVER_COOLDOWN: u64 = 660;
/// Suppressing fire (own rule): a player's bullet passing within this of an armed NPC's chest
/// without hitting it is a near miss; NPC_SUPPRESS_SHOTS of them inside NPC_SUPPRESS_WINDOW
/// ticks send the NPC to cover like a wounding hit does.
pub const NPC_SUPPRESS_RADIUS: f32 = 48.0;
pub const NPC_SUPPRESS_SHOTS: u8 = 3;
pub const NPC_SUPPRESS_WINDOW: u64 = 66;
/// A live grenade / rocket (any exploding projectile) inside this of an armed NPC sends it to
/// cover from the thrower (own rule).
pub const NPC_GRENADE_RANGE: f32 = 256.0;
/// Squadmates chasing one target fan out: slot k (by entity id) aims
/// ceil(k/2) * this to the left / right of the target, perpendicular to its own approach.
pub const NPC_FORMATION_SPACING: f32 = 96.0;
pub const NPC_SQUAD_RANGE: f32 = 512.0;
const NPC_GRAVITY: f32 = 600.0;

/// Measured on the game's headcrab (server_npc_melee_headcrab): 379.5 u/s horizontal, 272 u/s
/// up from 178 u (an aim point ~62 u above the player's origin), 5 DMG_SLASH on touch, ~12
/// ticks hanging on the hull, then a 120 u run-away (Run1), a turn and the next leap 252 ticks
/// after the landing (328 after the previous leap; run14 goldens).
pub fn npc_leap(class: &str) -> Option<NpcLeap> {
    match class {
        // the fast crab (golden 261106): the same arc and fall, the leap launched on its
        // label think two thinks after the sighting, Idle02 on the floor, a 187 u/s run-away,
        // 126 deg turn steps under Idle01, the next leap 77 ticks after the floor think
        "npc_headcrab_fast" => Some(NpcLeap {
            speed: 383.5,
            aim_height: 66.0,
            damage: 5.0,
            punch: 25.0,
            hang_ticks: 0,
            retreat: 120.0,
            rest_ticks: 0,
            poison: false,
            stand_ticks: 7,
            sight_thinks: 0,
            pre_label: false,
            turn_sequence: Some("Idle01"),
            leap_sequence: Some("attack"),
            land_sequence: Some("Idle02"),
            run_sequence: Some("Run1"),
        }),
        "npc_headcrab" | "npc_headcrab_black" => Some(NpcLeap {
            // golden 261104/261106 (classic and fast crab alike): 5.753 u/tick over rows
            // 26..45, the bite on the hull-contact tick 34 ticks after the leap's first row
            speed: 383.5,
            // 289 u/s up at the launch (golden 261104 row 26: z +4.2 in the first tick)
            aim_height: 66.0,
            damage: 5.0,
            punch: 25.0,
            hang_ticks: 0,
            retreat: 120.0,
            // no rest timer: the next leap follows the run-away and the turn (golden 261104:
            // floor 94, Run1 108, run end 269, turn to 339, label 346, launch 353)
            rest_ticks: 0,
            poison: class == "npc_headcrab_black",
            // a think on the floor, then the decision think: the run-away (first step a think
            // later, 108 = 94 + 14) or, with the enemy beyond NPC_CRAB_RUN_AWAY_DIST, the leap's
            // pre-think (fast crab 261106: floor 224, launch 238)
            stand_ticks: 7,
            sight_thinks: 1,
            pre_label: true,
            turn_sequence: None,
            leap_sequence: Some("jumpattack_broadcast"),
            land_sequence: Some("IdleB"),
            run_sequence: Some("Run1"),
        }),
        _ => None,
    }
}

/// The melee moves of a class, cycled in order; after the last the cycle restarts at
/// `repeat_from`. Measured on the game: zombie (server_npc_melee_zombie: attackE inside 55 u,
/// 84 ticks, 25 DMG_SLASH at tick 48, ~325 u/s launch), fast zombie (double claw), antlion
/// (a ~100 u swipe alternating with an 84 u pounce, 168-tick period), poison zombie (a
/// headcrab throw whose bite lands 187 ticks later, then a 25-damage claw from ~66 u).
pub fn npc_melee_moves(class: &str) -> Option<(&'static [NpcMelee], usize)> {
    // the guard's shove (`sk_antlionguard_dmg_shove` 10) with its launch; the charge is npc_special::tick_guard
    // the strider has no melee: the entry only makes it an attacking class that wakes to its
    // enemy and then stands in COMBAT (server_npc_tick_strider 261107: sched 4 at spawn+30,
    // its own 210 from +37, no move through +60)
    const STRIDER: [NpcMelee; 1] = [NpcMelee {
        damage: 0.0,
        reach: 0.0,
        swing_ticks: 1,
        hit_tick: 0,
        run: false,
        ..MELEE_PLAIN
    }];
    const GUARD: [NpcMelee; 1] = [NpcMelee {
        damage: 10.0,
        reach: 80.0,
        swing_ticks: 60,
        hit_tick: 30,
        punch: 400.0,
        lift: 200.0,
        run: true,
        ..MELEE_PLAIN
    }];
    const ZOMBIE: [NpcMelee; 1] = [NpcMelee {
        damage: 25.0,
        reach: 55.0,
        swing_ticks: 84,
        hit_tick: 48,
        punch: 320.0,
        lift: 36.0,
        start_range: 55.0,
        ..MELEE_PLAIN
    }];
    const FAST: [NpcMelee; 1] = [NpcMelee {
        damage: 3.0,
        reach: 52.0,
        swing_ticks: 133,
        hit_tick: 0,
        hit_gap: Some(14),
        hits: 2,
        punch: 15.0,
        side: 60.0,
        run: true,
        start_range: 52.0,
        roar_slide: 0.42,
        roar_at: 35,
        ..MELEE_PLAIN
    }];
    // server_npc_melee_antlion: a `pounce2` jump-in from 133 u (49 ticks, 28 u of ground, no
    // hit) opens the fight, then `attack3` (98 ticks, 5 hp at tick 35, no push) alternates
    // with `pounce` (63 ticks, 5 hp at tick 35, the player knocked back 30 u) forever
    const ANTLION: [NpcMelee; 3] = [
        NpcMelee {
            damage: 0.0,
            reach: 170.0,
            swing_ticks: 49,
            hit_tick: 49,
            run: true,
            // the game jumps in right after the run starts, ~170 u out, 66 u of flight
            // (server_npc_melee_antlion rows 39..95: 998 → 956 → 932)
            start_range: 170.0,
            lunge: 66.0,
            // 998 -> 956 in the first 7 ticks: the jump-in flies ~6 u a tick
            lunge_ticks: 11,
            ..MELEE_PLAIN
        },
        NpcMelee {
            damage: 5.0,
            reach: 100.0,
            swing_ticks: 98,
            hit_tick: 34,
            // the game knocks the player 30 u on every hit after the first (attack3 as much
            // as pounce: server_npc_melee_antlion dx -30 / -59 / -89 / -118)
            punch: 280.0,
            run: true,
            start_range: 100.0,
            ..MELEE_PLAIN
        },
        NpcMelee {
            damage: 5.0,
            reach: 130.0,
            swing_ticks: 63,
            hit_tick: 34,
            punch: 280.0,
            run: true,
            // the game pounces from 115..122 u (916 → 832 at the bot 794, 853 → 769 at 734,
            // 790 → 738 at 675): 84 u of flight
            start_range: 130.0,
            lunge: 84.0,
            // stands 13 ticks, flies to the hit tick (916 -> 904 -> 863 -> 832 over rows
            // 220..235), stands at 832 and from the first think 15 after the hit steps back
            // 21 u in two thinks (844, 853: 12.5 + 8.7, ~1.77 u a tick over 12)
            lunge_at: 13,
            recoil: 21.0,
            recoil_delay: 15,
            ..MELEE_PLAIN
        },
    ];
    // the throw: `hit_tick` releases a real headcrab (throw_crab); `reach`/`start_range`
    // are the throw range, gated by crabs left and NPC_CRAB_THROW_COOLDOWN
    const POISON: [NpcMelee; 2] = [
        NpcMelee {
            damage: 5.0,
            reach: NPC_CRAB_THROW_RANGE,
            swing_ticks: 168,
            hit_tick: 147,
            start_range: NPC_CRAB_THROW_RANGE,
            poison: true,
            ..MELEE_PLAIN
        },
        NpcMelee {
            damage: 25.0,
            reach: 70.0,
            swing_ticks: 98,
            hit_tick: 62,
            punch: 325.0,
            start_range: 70.0,
            ..MELEE_PLAIN
        },
    ];
    // the hunter (server_npc_melee_hunter 261106): the flechette volley `plant` from the
    // prowl - 8 flechettes of 4 at 0.1 s from +39 (plant 0..56, shoot_minigun 56..84,
    // idle_planted 84..119), the bot nudged ~2 u a hit; the slash `meleeleft` within 70 u,
    // 20 at +42 with a knockback that slides the bot 11 u/tick decaying (790 -> 702 over
    // 80 ticks), the prowl resumes 84 ticks in. The move is picked by range each think
    // (`npc_hunter_move`), not in turn.
    const HUNTER: [NpcMelee; 2] = [
        NpcMelee {
            damage: NPC_HUNTER_FLECHETTE_DAMAGE,
            reach: 1024.0,
            swing_ticks: NPC_HUNTER_VOLLEY_TICKS,
            hit_tick: 39,
            hit_gap: Some(7),
            hits: 8,
            punch: NPC_HUNTER_FLECHETTE_PUNCH,
            start_range: 1024.0,
            ..MELEE_PLAIN
        },
        NpcMelee {
            damage: 20.0,
            reach: 70.0,
            swing_ticks: 84,
            hit_tick: 42,
            punch: NPC_HUNTER_SLASH_PUNCH,
            start_range: 70.0,
            ..MELEE_PLAIN
        },
    ];
    match class {
        // the classic torso claws like its walker (and only an attacking class wakes to
        // its enemy: server_npc_spawn 261107 reads it in COMBAT / WAKE_ANGRY after its spawn)
        "npc_zombie" | "npc_zombine" | "npc_zombie_torso" => Some((&ZOMBIE, 0)),
        "npc_fastzombie" | "npc_fastzombie_torso" => Some((&FAST, 0)),
        "npc_antlion" => Some((&ANTLION, 1)),
        "npc_poisonzombie" => Some((&POISON, 1)),
        "npc_hunter" => Some((&HUNTER, 1)),
        "npc_antlionguard" => Some((&GUARD, 0)),
        "npc_strider" => Some((&STRIDER, 0)),
        _ => None,
    }
}

const NPC_HUNTER_FLECHETTE_DAMAGE: f32 = 4.0;
/// `hunter_flechette_min_range`: no volley at an enemy closer than this.
const NPC_HUNTER_FLECHETTE_MIN_RANGE: f32 = 100.0;
const NPC_HUNTER_FLECHETTE_PUNCH: f32 = 20.0;
const NPC_HUNTER_SLASH_PUNCH: f32 = 800.0;
/// The volley from `plant` to the end of idle_planted (t462 -> 581, t623 -> 742).
const NPC_HUNTER_VOLLEY_TICKS: u64 = 119;
/// The found-enemy intro: 4 thinks of walk_all side-stepping right of the facing (2.8 /
/// 3.9 / 4.9 u, yaw +15.5 a think), a think of idle_3, then hunter_respond_1; the prowl is
/// issued at +112 so its first step lands on the think the game's does (t441 = +121).
const NPC_HUNTER_INTRO_WALK_TICKS: u64 = 28;
const NPC_HUNTER_INTRO_IDLE_TICKS: u64 = 35;
const NPC_HUNTER_INTRO_TICKS: u64 = 112;
/// hunter_respond_1 shows until the first prowl step (t441).
const NPC_HUNTER_INTRO_LABEL_TICKS: u64 = 119;
const NPC_HUNTER_INTRO_STEPS: [f32; 4] = [1.1, 2.8, 3.9, 4.9];
const NPC_HUNTER_INTRO_YAW: f32 = 15.5;
/// Prowl before the first volley after the intro (t441 -> 462, from the +112 issue) and
/// after a volley (t581 -> 623); a volley follows a slash at once (t882).
const NPC_HUNTER_PROWL_AFTER_INTRO: u64 = 28;
const NPC_HUNTER_PROWL_AFTER_VOLLEY: u64 = 42;
