/// Weapons any NPC may be handed (`list.Get("NPCUsableWeapons")`), next to a class's own list.
pub const NPC_USABLE_WEAPONS: [&str; 11] = [
    "weapon_pistol",
    "weapon_357",
    "weapon_smg1",
    "weapon_shotgun",
    "weapon_ar2",
    "weapon_rpg",
    "weapon_alyxgun",
    "weapon_annabelle",
    "weapon_crossbow",
    "weapon_stunstick",
    "weapon_crowbar",
];

pub fn npc_def(key: &str) -> Option<&'static NpcDef> {
    NPC_LIST.iter().find(|d| d.key == key)
}

/// A sandbox vehicle: a physics prop of the sandbox with a seat (`Spawn_Vehicle`).
/// Script tuning of a vehicle (`Vehicle:SetMaxThrottle` / `SetSteeringDegrees` / `SetWheelFriction` /
/// `SetSpringLength` / `SetVehicleParams`): overrides over the measured drive spec, `None` = the spec.
#[derive(Clone, Debug, PartialEq)]
pub struct VehicleTuning {
    pub max_throttle: f32,
    pub max_rev_throttle: f32,
    pub deg_slow: Option<f32>,
    pub deg_fast: Option<f32>,
    pub tyre_mu: Option<f32>,
    pub max_fwd: Option<f32>,
    pub max_rev: Option<f32>,
    /// Suspension rest length (u) for every wheel.
    pub rest: Option<f32>,
}

impl Default for VehicleTuning {
    fn default() -> Self {
        Self {
            max_throttle: 1.0,
            max_rev_throttle: 1.0,
            deg_slow: None,
            deg_fast: None,
            tyre_mu: None,
            max_fwd: None,
            max_rev: None,
            rest: None,
        }
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Vehicle {
    /// Spawnmenu list key (`VehicleName`), e.g. `Chair_Wood`.
    pub key: String,
    pub class: String,
    pub model: String,
    pub health: i32,
    pub max_health: i32,
    pub driver: Option<u32>,
    /// Raycast wheels of a car (`wheel_fl` .. `wheel_rr` hubs in body space); empty for seats.
    pub wheels: Vec<Wheel>,
    /// The vehicle script's `addgravity` (extra gravity in g).
    pub add_gravity: f32,
    /// The vehicle script's `massoverride` (kg) the springs scale with.
    pub mass: f32,
    /// Driver inputs and the driving state they produced last tick.
    pub controls: VehicleControls,
    pub tuning: VehicleTuning,
}

impl Vehicle {
    /// The drive spec of this car with the script tuning applied.
    pub fn spec(&self) -> Option<DriveSpec> {
        let mut s = drive_spec(&self.key)?;
        let t = &self.tuning;
        if let Some(d) = t.deg_slow {
            s.deg_slow = d;
        }
        if let Some(d) = t.deg_fast {
            s.deg_fast = d;
        }
        if let Some(m) = t.tyre_mu {
            s.tyre_mu = m;
        }
        if let Some(m) = t.max_fwd {
            s.max_fwd = m;
        }
        if let Some(m) = t.max_rev {
            s.max_rev = m;
        }
        Some(s)
    }
}

/// One raycast wheel: the hub in body space, the tyre radius, the axle's spring constant
/// (`springConstant`, per kg of body) and `springDamping`.
#[derive(Clone, Debug, PartialEq)]
pub struct Wheel {
    pub hub: Vec3,
    pub radius: f32,
    pub spring: f32,
    /// `springDamping` (rebound) and `springDampingCompression`, per kg of body.
    pub damping: f32,
    pub damping_compression: f32,
}

/// The numbers of a car's vehicle script that the suspension needs (`scripts/vehicles/*.txt`
/// of the game: body mass, extra gravity, per-axle wheel radius / spring / damping).
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct VehicleScript {
    pub mass: f32,
    pub add_gravity: f32,
    /// (radius, springConstant, springDamping, springDampingCompression) of the front and the
    /// rear axle.
    pub front: (f32, f32, f32, f32),
    pub rear: (f32, f32, f32, f32),
    /// Measured hub extension below its spawn point at rest (`server_vehicle_settle`): the cars
    /// rise 3.7 u on their springs, the airboat 3.4 u before its hull takes the floor.
    pub rest: f32,
}

/// `vehiclescript` of the spawnmenu's cars (`base_vehicles.lua`): jeep_test, airboat, jalopy,
/// apc_gmod.
/// `ENT:PhysicsInit*` of a scripted entity: what its body is made of instead of the model's PHY.
