/// Distance along `dir` (unit) from `start` to the box `lo..hi`, 0 when `start` is inside,
/// None when the ray misses or the box is behind `start`.
fn ray_box_entry(start: Vec3, dir: Vec3, lo: Vec3, hi: Vec3) -> Option<f32> {
    let (mut t0, mut t1) = (0.0f32, f32::MAX);
    for a in 0..3 {
        if dir[a].abs() < 1e-9 {
            if start[a] < lo[a] || start[a] > hi[a] {
                return None;
            }
            continue;
        }
        let (mut ta, mut tb) = ((lo[a] - start[a]) / dir[a], (hi[a] - start[a]) / dir[a]);
        if ta > tb {
            std::mem::swap(&mut ta, &mut tb);
        }
        t0 = t0.max(ta);
        t1 = t1.min(tb);
        if t0 > t1 {
            return None;
        }
    }
    Some(t0)
}

/// What an HL2 item gives on touch.
#[derive(Clone, Copy, Debug, PartialEq)]
pub enum Pickup {
    Health(i32),
    Armor(i32),
    Ammo(&'static str, i32),
}

/// `sk_healthkit` 25, `sk_healthvial` 10, `sk_battery` 15 and the `SIZE_AMMO_*` box values.
/// `item_healthcharger` / `item_suitcharger` (CNewWallHealth / CNewRecharge): a wall unit with
/// `sk_healthcharger` 50 / `sk_suitcharger` 30 points, one point per 0.1 s while +use is held.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Charger {
    pub suit: bool,
    pub juice: i32,
    /// Tick of the next point while on.
    pub next: u64,
    pub on: bool,
}

pub fn hl2_charger(class: &str) -> Option<Charger> {
    let (suit, juice) = match class {
        "item_healthcharger" => (false, 50),
        "item_suitcharger" => (true, 30),
        _ => return None,
    };
    Some(Charger {
        suit,
        juice,
        next: 0,
        on: false,
    })
}

pub fn hl2_item_pickup(class: &str) -> Option<Pickup> {
    Some(match class {
        "item_healthkit" => Pickup::Health(25),
        "item_healthvial" => Pickup::Health(10),
        "item_battery" => Pickup::Armor(15),
        "item_ammo_pistol" => Pickup::Ammo("Pistol", 20),
        "item_ammo_pistol_large" => Pickup::Ammo("Pistol", 100),
        "item_ammo_smg1" => Pickup::Ammo("SMG1", 45),
        "item_ammo_smg1_large" => Pickup::Ammo("SMG1", 225),
        "item_ammo_smg1_grenade" => Pickup::Ammo("SMG1_Grenade", 1),
        "item_ammo_ar2" => Pickup::Ammo("AR2", 20),
        "item_ammo_ar2_large" => Pickup::Ammo("AR2", 100),
        "item_ammo_ar2_altfire" => Pickup::Ammo("AR2AltFire", 1),
        "item_ammo_357" => Pickup::Ammo("357", 6),
        "item_ammo_357_large" => Pickup::Ammo("357", 20),
        "item_ammo_crossbow" => Pickup::Ammo("XBowBolt", 6),
        "item_box_buckshot" => Pickup::Ammo("Buckshot", 20),
        "item_rpg_round" => Pickup::Ammo("RPG_Round", 1),
        _ => return None,
    })
}

fn class_sound(class: &str, pickup: Pickup) -> &'static str {
    match pickup {
        Pickup::Health(_) if class == "item_healthvial" => "HealthVial.Touch",
        Pickup::Health(_) => "HealthKit.Touch",
        Pickup::Armor(_) => "ItemBattery.Touch",
        Pickup::Ammo(..) => "BaseCombatCharacter.AmmoPickup",
    }
}

pub struct Server<'w> {
    /// `scripts/surfaceproperties.txt`, for the physprop stool's `PhysObj:SetMaterial`.
    pub surface_table: Option<gm_physics::surface::SurfaceTable>,
    /// Gravity and physics material applied to each body (physprop), to push changes to Jolt.
    applied_physprops: std::collections::BTreeMap<u32, (bool, String)>,
    /// Duplicator clipboards: the copied group with poses relative to the copied prop.
    pub clipboards: BTreeMap<u32, save::Save>,
    pub hits: Vec<Hit>,
    /// Hit boxes of the player model; without one, bullets use the hull and height bands.
    pub hit_model: Option<weapons::HitModel>,
    pub collision: &'w gm_collision::World,
    pub physics: World,
    /// The static world body constraints to the world attach to.
    world_body: BodyHandle,
    pub sandbox: Sandbox,
    pub players: BTreeMap<u32, Player>,
    mover: gm_move::Mover<'w>,
    bodies: BTreeMap<u32, BodyHandle>,
    /// First id of each class family's private schedules, handed out in spawn order like the
    /// game's schedule namespace.
    class_sched_bases: BTreeMap<String, u16>,
    /// The map's compiled node graph (`set_ai_graph`), when it has one.
    ai_graph: Option<AiGraph>,
    /// The map's `info_node` / `info_node_hint` entities (the game's nodegraph positions).
    ai_nodes: Vec<AiNode>,
    /// The map's `func_tank` mounted guns (`func_tanks_from_bsp`).
    func_tanks: Vec<FuncTank>,
    /// Live sound-entity sounds / scents: position, radius, SOUND_* bits, the tick they end,
    /// the NPC that made them (never hears its own).
    ai_sounds: Vec<(Vec3, f32, u16, u64, Option<u32>)>,
    next_class_sched: u16,
    /// prop_ragdoll: every bone body (the root is also in `bodies`) and the joints between them.
    ragdoll_bodies: BTreeMap<u32, RagdollRuntime>,
    /// Local bone poses a ragdoll entity about to get its bodies spawns in (death ragdolls).
    ragdoll_spawn_pose: BTreeMap<u32, Vec<(Vec3, Quat)>>,
    /// `Entity:ManipulateBoneScale` per model bone (inflator stool), absent = all 1.
    bone_scales: BTreeMap<u32, Vec<Vec3>>,
    /// `Entity:ManipulateBoneAngles` per model bone (finger poser), absent = all zero.
    bone_angles: BTreeMap<u32, Vec<Vec3>>,
    /// `Entity:ManipulateBonePosition` per model bone, absent = all zero.
    bone_positions: BTreeMap<u32, Vec<Vec3>>,
    /// `Entity:SetSubMaterial`: (material index, override path) per prop.
    sub_materials: BTreeMap<u32, Vec<(u8, String)>>,
    /// `Entity:SetEyeTarget` (eyeposer, local to the `eyes` attachment); the duplicator's
    /// `eyetarget` modifier, cleared by `vector_origin`.
    eye_targets: BTreeMap<u32, Vec3>,
    /// `SetFlexWeight` per controller and `SetFlexScale` (faceposer).
    flexes: BTreeMap<u32, (Vec<f32>, f32)>,
    /// Per-player poser stool state (the game keeps it on the tool object / weapon NW vars).
    posers: BTreeMap<u32, PoserState>,
    /// Paint stool decals per entity: the duplicator's `decal<i>` modifiers (none on the world).
    decals: BTreeMap<u32, Vec<DecalMod>>,
    constraints: BTreeMap<u32, ConstraintHandle>,
    /// NoCollide pairs by sandbox constraint id.
    nocollides: BTreeMap<u32, (BodyHandle, BodyHandle)>,
    pub models: BTreeMap<String, ModelInfo>,
    /// `Player:Say` lines waiting for the net layer to run them through chat like typed ones.
    pub pending_chat: Vec<(u32, String)>,
    /// Script-facing model data per model name (the snapshot points at this map).
    pub model_scripts: BTreeMap<String, ModelScriptData>,
    /// Some addon listens to `SetupMove` / `Move` / `FinishMove`: ask them around every move.
    pub move_hooks: bool,
    /// Labels of the mounted content providers (`IsMounted`).
    pub mounted: Vec<String>,
    /// `Entity:SetFriction / SetElasticity` overrides of the model surface, per prop.
    pub surface_overrides: BTreeMap<u32, (f32, f32)>,
    /// Physics shapes scripted entities asked for (`ENT:PhysicsInit*`), consulted when their
    /// body is built instead of the model's PHY hulls.
    pub script_shapes: BTreeMap<u32, PhysShape>,
    /// Animators of NPCs (always) and of props a script gave a sequence, by entity id.
    pub anims: BTreeMap<u32, EntAnim>,
    /// Pose parameter values scripts set (`Entity:SetPoseParameter`), by entity then name.
    pub poses: BTreeMap<u32, BTreeMap<String, f32>>,
    /// `Entity:SetCollisionBounds` on a prop: readback only, its body stays the PHY (an NPC's
    /// call changes its hull in `npcs` instead).
    pub bounds_override: BTreeMap<u32, (Vec3, Vec3)>,
    /// World sounds of this tick (prop impacts), drained by the network layer.
    sounds: Vec<WorldSound>,
    /// Hold the map inputs that come due for `flush_due_inputs` (the `AcceptInput` hook)
    /// instead of applying them in the tick.
    pub defer_inputs: bool,
    /// Visual effects of this tick (`take_effects`).
    effects: Vec<WorldEffect>,
    /// Projectile entity ids live in their own range above every sandbox id.
    next_projectile_id: u32,
    /// Thrusters whose loop is playing (`StartThrustSound` happened, no stop since).
    thruster_loops: BTreeSet<u32>,
    /// Props whose scrape loop is playing (the volume factor it started with).
    scrapes: BTreeMap<u32, f32>,
    hull_planes: BTreeMap<String, Vec<Vec<(Vec3, f32)>>>,
    pub events: Vec<Event>,
    pub game_events: Vec<GameEvent>,
    /// HL2 items spawned from the Entities tab (entity id -> class), picked up on touch.
    pub hl2_items: BTreeMap<u32, String>,
    /// The `SANDBOX_SPAWNABLE_ENTITIES` spawned (`sent_ball`, the editors) by prop id.
    pub sandbox_sents: BTreeMap<u32, String>,
    /// The editor entities' `Edit` vars (`editor_schema`) by prop id, key -> value.
    pub editor_vars: BTreeMap<u32, BTreeMap<String, String>>,
    /// `item_healthcharger` / `item_suitcharger` units by entity id.
    pub chargers: BTreeMap<u32, Charger>,
    pub request_hook: Option<RequestHook>,
    pub physgun_params: PhysgunParams,
    pub projectiles: Vec<projectile::Projectile>,
    /// Loads a model the first time something spawns it (the dedicated server reads the MDL/PHY
    /// from the mounted content on demand).
    pub model_loader: Option<ModelLoader>,
    /// Solid static props of the map (`LoadedWorld::static_convexes`), always in the player
    /// and NPC sweeps.
    pub static_convexes: Vec<gm_collision::Convex>,
    /// The map's brush / logic entities (`mapio`).
    pub map_io: mapio::MapIo,
    pub step_loader: Option<StepLoader>,
    /// Host hook: the `$surfaceprop` of a brush material (impact decals); cached below.
    pub surfaceprop_loader: Option<SurfacepropLoader>,
    brush_surfaceprops: BTreeMap<String, String>,
    /// Step sounds by material, `""` for no material; filled through `step_loader`.
    step_sounds: BTreeMap<String, Option<StepSounds>>,
    /// `sbox_playershurtplayers`: with it off hits are still resolved and recorded but neither
    /// hurt nor push (`hit_pistol_nohurt`, `hit_rpg_nohurt`).
    pub players_hurt_players: bool,
    /// `gm_phys_paused`: the physics step is skipped.
    pub physics_paused: bool,
    /// `phys_timescale`: the physics step runs at this fraction of the tick.
    pub physics_time_scale: f32,
    pub prop_hits: Vec<PropHit>,

    pub spawn_points: Vec<SpawnPoint>,
    /// `game.GetMapVersion` / `game.GetSunInfo`: from the loaded BSP, set by the host.
    pub map_revision: i32,
    pub sun_direction: Option<Vec3>,
    /// Script requests for the network layer: per-player client notices (`Player:LimitHit`)
    /// and players to drop with their identity banned (`Player:Ban`); drained every tick.
    pub notices: Vec<(u32, String)>,
    pub pending_bans: Vec<u32>,
    /// Players' gesture layers (`Player:AnimRestartGesture`): the base sequence is the
    /// client's, only the gesture runs here. Keyed by player id (separate from entity ids).
    pub player_anims: BTreeMap<u32, EntAnim>,
    /// Scripted NextBots (`CLuaLocomotion`): a ground mover per scripted entity, keyed by entity.
    pub nextbots: BTreeMap<u32, NextBot>,
    /// `Entity:SetModelScale` per prop (render only, like the game: physics untouched).
    pub model_scales: BTreeMap<u32, f32>,
    /// `Entity:SetPreventTransmit`: (entity, player) pairs the network layer must not send.
    pub prevent_transmit: BTreeSet<(u32, u32)>,
    /// `ENTITY:UpdateTransmitState` per entity: `TRANSMIT_ALWAYS` (0) / `TRANSMIT_NEVER` (1);
    /// absent = PVS.
    pub transmit_mode: BTreeMap<u32, u8>,
    /// `Entity:SetTransmitWithParent`: parented children whose network interest follows the parent.
    pub transmit_with_parent: BTreeSet<u32>,
    spawn_rng: u64,
    tick_count: u64,
    /// `mp_falldamage`: progressive fall damage instead of the flat 10.
    pub fall_damage_progressive: bool,
    /// Console variables: the sandbox `sbox_*` set plus what addons create.
    pub cvars: BTreeMap<String, Cvar>,
    /// (name, old, new) since the last `take_cvar_changes` (the net layer takes them after the
    /// script hooks read them).
    pub cvar_changes: Vec<(String, String, String)>,
    /// Spawn menu categories registered by addons (`spawnmenu.add`), in registration order;
    /// `spawn_lists_version` grows with every change so the net layer resends them.
    pub spawn_lists: Vec<(String, Vec<String>)>,
    pub spawn_lists_version: u32,
    /// Bumped whenever the Weapons / Entities content lists change (`content_lists`).
    pub content_version: u32,
    /// Bumped whenever a scripted entity's overlay text changes or such an entity goes away.
    pub overlay_version: u32,
    /// Buttons with a description (their world tips ride on the overlay list).
    pub button_tips: BTreeSet<u32>,
    /// Setting schemas of scripted stools (`tool.register` with `settings`), by tool name;
    /// `tool_schemas_version` grows with every change so the net layer resends them.
    pub tool_schemas: Vec<(String, Vec<ToolSetting>)>,
    pub tool_schemas_version: u32,
    /// Weapon classes addons registered, in registration order (indices after `LOADOUT` on
    /// the wire); `scripted_weapons_version` grows with every change.
    pub scripted_weapons: Vec<ScriptedWeapon>,
    pub scripted_entities: Vec<ScriptedEntity>,
    /// The props that are scripted entities, by prop id.
    pub sents: HashMap<u32, SentState>,
    /// Weapon entities lying in the world (`Spawn_Weapon`): prop id -> weapon class.
    pub world_weapons: HashMap<u32, String>,
    /// Dropped NPC weapons still held in the air: prop id, the tick they start flying, their
    /// linear and angular velocity then.
    pending_drops: Vec<(u32, u64, Vec3, Vec3)>,
    /// `ai_disabled 1`: no NPC thinks at all (no movement, no combat), as in the game.
    pub ai_disabled: bool,
    /// NPCs spawned from the NPCs tab (`Spawn_NPC`), by sandbox id (foreign to the prop list).
    pub npcs: BTreeMap<u32, Npc>,
    pub squads: ai::Squads,
    nav: Option<std::sync::Arc<gm_nav::NavMesh>>,
    /// `Entity:SetParent` links: child prop id -> parent and the child pose in parent space.
    parents: HashMap<u32, ParentLink>,
    /// Vehicles (`Spawn_Vehicle`): sandbox prop id -> seat state.
    pub vehicles: BTreeMap<u32, Vehicle>,
    /// Ticks that removed an entity since undo.lua last purged dead undo lists (every 16).
    undo_purge_ticks: u32,
    /// (player, scripted entity) pairs whose hulls overlapped last tick, for the touch edges.
    pub sent_player_touch: std::collections::HashSet<(u32, u32)>,
    /// `(player, prop)` pairs whose hull the player's move is resting against: the soft
    /// impact plays once, when the pair appears.
    pub prop_touch: std::collections::HashSet<(u32, u32)>,
    /// Last tick each prop hurt a player (one hit per PROP_HIT_COOLDOWN).
    pub prop_hit_at: BTreeMap<u32, u64>,
    pub scripted_weapons_version: u32,
    /// Names created since the last `take_cvar_new` (replicated to connected clients).
    pub cvar_new: Vec<String>,
}

/// A console variable: a string value with the sandbox's flags that matter here.
#[derive(Clone, Debug, Default, PartialEq)]
pub struct Cvar {
    pub value: String,
    pub default: String,
    /// Sent to every client and kept in step (`FCVAR_REPLICATED`).
    pub replicated: bool,
    /// Saved with the server config (`FCVAR_ARCHIVE`).
    pub archive: bool,
    pub min: Option<f32>,
    pub max: Option<f32>,
    pub help: String,
}

impl Cvar {
    pub fn replicated(default: &str) -> Self {
        Cvar {
            value: default.to_string(),
            default: default.to_string(),
            replicated: true,
            ..Default::default()
        }
    }
}

