    /// `Player:SetPos` with the velocity cleared (how the probe drops a bot).
    pub fn teleport_player(&mut self, id: u32, pos: Vec3) {
        if let Some(p) = self.players.get_mut(&id) {
            p.state.origin = pos;
            p.state.game_moved = true;
            p.state.velocity = Vec3::ZERO;
            p.state.on_ground = false;
            p.prev_vz = 0.0;
            p.prev_on_ground = false;
        }
    }

    pub fn set_player_health(&mut self, id: u32, health: i32) {
        // measured: the fractional damage carried over survives `SetHealth` (and respawns)
        if let Some(p) = self.players.get_mut(&id) {
            p.health = health;
        }
    }

    pub fn set_player_armor(&mut self, id: u32, armor: i32) {
        if let Some(p) = self.players.get_mut(&id) {
            p.armor = armor;
        }
    }

    /// `Entity:TakeDamage` on a player: armour share, whole-point health with the fraction
    /// carried over, death at zero. Returns the health damage applied.
    pub fn damage_player(&mut self, id: u32, amount: f32, dmg_type: u32) -> f32 {
        self.hurt(id, amount, dmg_type, RESPAWN_TICKS)
    }

    /// `damage_player` with the respawn delay of the phase the death happens in.
    fn hurt(&mut self, id: u32, amount: f32, dmg_type: u32, respawn_ticks: u64) -> f32 {
        let tick = self.tick_count;
        if !self.players.get(&id).is_some_and(|p| p.alive) || amount <= 0.0 {
            return 0.0;
        }
        let (attacker, hitgroup, pos) = match self.hits.last() {
            Some(h) if h.tick == tick && h.target == id => {
                (h.attacker, h.hitgroup.unwrap_or(0), h.pos)
            }
            _ => (0, 0, Vec3::ZERO),
        };
        let amount = match self.ask(Request::PlayerDamage {
            player: id,
            amount,
            dmg_type,
            attacker,
            hitgroup,
            pos,
        }) {
            Verdict::Cancel => return 0.0,
            Verdict::Amount(a) => a,
            Verdict::Allow => amount,
            Verdict::Text(_) => amount,
        };
        let armor_now = self
            .players
            .get(&id)
            .filter(|p| p.alive)
            .map_or(0, |p| p.armor);
        let armored = amount > 0.0 && armor_now > 0 && dmg_type & (DMG_FALL | DMG_DROWN) == 0;
        let scripted_split = if armored {
            match self.ask(Request::PlayerArmor {
                player: id,
                amount,
                dmg_type,
                armor: armor_now,
            }) {
                Verdict::Text(t) => parse_armor_split(&t),
                _ => None,
            }
        } else {
            None
        };
        let Some(p) = self.players.get_mut(&id) else {
            return 0.0;
        };
        if !p.alive || amount <= 0.0 {
            return 0.0;
        }
        let mut to_health = amount;
        if let Some((health, armor)) = scripted_split {
            to_health = health;
            p.armor = armor.min(p.max_armor);
        } else if armored {
            let mut to_armor = amount * ARMOR_SHARE;
            if to_armor > p.armor as f32 {
                to_armor = p.armor as f32;
            }
            // the armour value is kept as a float by the game and read truncated: 50 - 19.2 -> 30
            p.armor = (p.armor as f32 - to_armor).floor() as i32;
            to_health = amount - to_armor;
        }
        // blast damage is whole to the nearest (111.9 -> 112, 86.48 -> 86, 3.87 -> 4 measured on
        // rockets); bullets carry their fraction over in the accumulator (24 -> 4.8 -> 4, 5, 14)
        let whole = if dmg_type & weapons::DMG_BLAST != 0 {
            to_health.round()
        } else {
            p.damage_acc += to_health;
            let whole = p.damage_acc.floor();
            p.damage_acc -= whole;
            whole
        };
        p.health -= whole as i32;
        if p.health <= 0 {
            p.alive = false;
            p.deaths += 1;
            p.ragdoll = Some(Ragdoll {
                class: RAGDOLL_CLASS,
                model: p.model.clone(),
                origin: p.state.origin,
                angles: Vec3::ZERO,
                velocity: p.state.velocity,
                tick,
                ducked: p.state.ducked,
            });
            p.active_weapon.clear();
            p.held = None;
            p.driving = None;
            p.driving = None;
            p.state.velocity = Vec3::ZERO;
            if dmg_type & DMG_FALL != 0 {
                // measured: a bot killed by a fall keeps the negative health and does not
                // respawn by itself within the recording
                p.death_tick = None;
            } else {
                p.health = 0;
                p.death_tick = Some(tick);
                p.respawn_ticks = respawn_ticks;
            }
        }
        let died = !p.alive;
        if to_health > 0.0 {
            self.game_events.push(GameEvent::PlayerDamaged {
                player: id,
                amount: to_health,
                dmg_type,
                pos,
            });
        }
        if died {
            let (attacker, inflictor) = p.last_damage;
            self.game_events.push(GameEvent::PlayerDied {
                player: id,
                dmg_type,
                attacker,
                inflictor: inflictor.to_string(),
            });
        }
        to_health
    }

    /// `CreateConVar`: a new variable gets its default; an existing one keeps its value and
    /// flags (false).
    pub fn create_cvar(&mut self, name: &str, cvar: Cvar) -> bool {
        if name.is_empty() || self.cvars.contains_key(name) {
            return false;
        }
        let mut c = cvar;
        if c.value.is_empty() {
            c.value = c.default.clone();
        }
        self.cvars.insert(name.to_string(), c);
        self.cvar_new.push(name.to_string());
        true
    }

    /// Sets a known variable (numbers clamped to min/max), applies what the server reads from it
    /// and logs the change; false for an unknown name or an unchanged value.
    pub fn set_cvar(&mut self, name: &str, value: &str) -> bool {
        let Some(c) = self.cvars.get_mut(name) else {
            return false;
        };
        let mut v = value.to_string();
        if let Ok(n) = value.trim().parse::<f32>() {
            let mut n2 = n;
            if let Some(lo) = c.min {
                n2 = n2.max(lo);
            }
            if let Some(hi) = c.max {
                n2 = n2.min(hi);
            }
            if n2 != n {
                v = if n2.fract() == 0.0 {
                    format!("{}", n2 as i64)
                } else {
                    format!("{n2}")
                };
            }
        }
        if c.value == v {
            return false;
        }
        let old = std::mem::replace(&mut c.value, v.clone());
        let num = v.trim().parse::<f32>().unwrap_or(0.0);
        match name {
            "sbox_maxprops" => self.sandbox.limits.max_props = num as i32,
            "sbox_maxragdolls" => self.sandbox.limits.max_ragdolls = num as i32,
            "sbox_maxnpcs" => self.sandbox.limits.max_npcs = num as i32,
            "sbox_maxvehicles" => self.sandbox.limits.max_vehicles = num as i32,
            "sbox_maxconstraints" => self.sandbox.limits.max_constraints = num as i32,
            "sbox_maxropeconstraints" => self.sandbox.limits.max_ropeconstraints = num as i32,
            "sbox_playershurtplayers" => self.players_hurt_players = num != 0.0,
            "sv_gravity" => {
                self.mover.cfg.gravity = num;
                self.physics.set_world_gravity(num);
            }
            "phys_timescale" => {
                self.physics_time_scale = if num.is_finite() && num > 0.0 {
                    num
                } else {
                    1.0
                }
            }
            "gm_phys_paused" => self.physics_paused = num != 0.0,
            _ => {}
        }
        self.cvar_changes.push((name.to_string(), old, v));
        true
    }

    pub fn cvar(&self, name: &str) -> Option<&str> {
        self.cvars.get(name).map(|c| c.value.as_str())
    }

    pub fn take_cvar_new(&mut self) -> Vec<String> {
        std::mem::take(&mut self.cvar_new)
    }

    pub fn take_cvar_changes(&mut self) -> Vec<(String, String, String)> {
        std::mem::take(&mut self.cvar_changes)
    }

    pub fn tick_count(&self) -> u64 {
        self.tick_count
    }

    /// Spawn points from the map's entities.
    pub fn set_spawn_points_from_bsp(&mut self, bsp: &gm_formats::bsp::Bsp) {
        self.spawn_points = spawn_points_from_bsp(bsp);
    }

    /// xorshift64*: deterministic for the harnesses, uniform like the game's random picks.
    fn next_random(&mut self) -> f32 {
        let mut x = self.spawn_rng;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.spawn_rng = x;
        let r = x.wrapping_mul(0x2545_F491_4F6C_DD1D);
        (r >> 40) as f32 / (1u64 << 24) as f32
    }

    fn pick_spawn(&mut self) -> Option<SpawnPoint> {
        if self.spawn_points.is_empty() {
            return None;
        }
        let mut x = self.spawn_rng;
        x ^= x >> 12;
        x ^= x << 25;
        x ^= x >> 27;
        self.spawn_rng = x;
        let r = x.wrapping_mul(0x2545_F491_4F6C_DD1D);
        let i = (r >> 33) as usize % self.spawn_points.len();
        Some(self.spawn_points[i].clone())
    }

    /// `Player:Spawn`: full health, the loadout, a spawn point 1 u above its origin; the addon
    /// runtime may pick the point (`PlayerSelectSpawn`).
    pub fn spawn_player(&mut self, id: u32) {
        let spawn = self.pick_spawn();
        if !self.players.contains_key(&id) {
            return;
        }
        let picked = spawn.clone().unwrap_or(SpawnPoint {
            pos: Vec3::ZERO,
            angles: Vec3::ZERO,
        });
        let spawn = match self.ask(Request::SelectSpawn {
            player: id,
            pos: picked.pos,
            angles: picked.angles,
        }) {
            Verdict::Text(t) => parse_spawn_override(&t).or(spawn),
            _ => spawn,
        };
        self.game_events
            .push(GameEvent::PlayerSpawned { player: id });
        let Some(p) = self.players.get_mut(&id) else {
            return;
        };
        if let Some(sp) = spawn {
            p.state = gm_move::PlayerState {
                origin: sp.pos + Vec3::new(0.0, 0.0, SPAWN_Z_OFFSET),
                ..Default::default()
            };
            p.view_angles = sp.angles;
        } else {
            p.state.velocity = Vec3::ZERO;
        }
        p.alive = true;
        p.health = p.max_health;
        p.armor = 0;
        p.suit = false;
        p.eye_override = None;
        p.ragdoll = None;
        p.death_tick = None;
        p.held = None;
        p.driving = None;
        // `PlayerSetModel`: the choice through the game's table, a hook may replace it
        let model = player_models::translate(&p.wanted_model).to_string();
        let model = match self.ask(Request::SetModel {
            player: id,
            model: model.clone(),
        }) {
            Verdict::Text(t) => t,
            _ => model,
        };
        if let Some(p) = self.players.get_mut(&id) {
            p.model = model;
            p.skin = p.wanted_skin;
            p.body = p.wanted_body.clone();
        }
        self.give_loadout(id);
    }

    /// `Entity:Ignite(seconds)`: a flame on the prop; false when there is no such prop or it
    /// already burns. The fire sound (`General.BurningObject`) plays at the prop.
    pub fn ignite(&mut self, ent: u32, seconds: f32) -> bool {
        let Some(prop) = self.sandbox.props().iter().find(|p| p.id == ent).cloned() else {
            return false;
        };
        if prop.fire.is_some() {
            return false;
        }
        let now = self.tick_count;
        let ticks = (seconds / gm_core::tick::DEFAULT_TICK_INTERVAL).round() as u64;
        self.sandbox.set_fire(
            ent,
            Some(gm_sandbox::Fire {
                until: now + ticks,
                next_think: now + FIRE_FIRST_DAMAGE_TICKS,
                out_at: None,
            }),
        );
        let pos = self.prop_state(ent).map_or(prop.pos, |s| s.position);
        self.sounds.push(WorldSound {
            name: "General.BurningObject".to_string(),
            pos,
            volume: 1.0,
            ..Default::default()
        });
        true
    }

    /// `Entity:Extinguish`: the flame is gone at once, the health stays.
    pub fn extinguish(&mut self, ent: u32) -> bool {
        let burning = self
            .sandbox
            .props()
            .iter()
            .any(|p| p.id == ent && p.fire.is_some());
        if burning {
            self.sandbox.set_fire(ent, None);
        }
        burning
    }

    /// Damage on a prop (`CBreakableProp::OnTakeDamage`): the amount times the `prop_data`
    /// modifier of its type, truncated to whole points, off the health; zero breaks the prop
    /// (the surface's `break` sound, `PropBreak`, gone). A prop without health (metal) takes
    /// none. Returns whether it broke.
    pub fn damage_prop(&mut self, ent: u32, amount: f32, dmg_type: u32) -> bool {
        let Some(prop) = self.sandbox.props().iter().find(|p| p.id == ent).cloned() else {
            return false;
        };
        if prop.health <= 0 {
            return false;
        }
        self.sent_event(ent, "damage", 0, 0, amount);
        let now = self.cur_time();
        self.sandbox.thruster_damaged(ent, now);
        let data = self
            .models
            .get(&prop.model)
            .map_or(PropData::default(), |m| m.prop_data);
        let left = prop.health - (amount * data.modifier(dmg_type)) as i32;
        if left > 0 {
            self.sandbox.set_health(ent, left);
            return false;
        }
        self.sandbox.set_health(ent, 0);
        let pos = self.prop_state(ent).map_or(prop.pos, |s| s.position);
        if let Some(name) = self
            .models
            .get(&prop.model)
            .and_then(|m| m.break_sound.clone())
        {
            self.sounds.push(WorldSound {
                name,
                pos,
                volume: 1.0,
                ..Default::default()
            });
        }
        self.game_events.push(GameEvent::PropBreak { ent });
        self.remove_prop(ent);
        true
    }

    fn fire_tick(&mut self) {
        let now = self.tick_count;
        let burning: Vec<(u32, gm_sandbox::Fire)> = self
            .sandbox
            .props()
            .iter()
            .filter_map(|p| Some((p.id, p.fire.clone()?)))
            .collect();
        for (id, mut fire) in burning {
            if let Some(out) = fire.out_at {
                if now >= out {
                    self.sandbox.set_fire(id, None);
                }
                continue;
            }
            if now < fire.next_think {
                continue;
            }
            if now >= fire.until {
                fire.out_at = Some(now + FIRE_LINGER_TICKS);
                self.sandbox.set_fire(id, Some(fire));
                continue;
            }
            fire.next_think = now + FIRE_DAMAGE_INTERVAL_TICKS;
            self.sandbox.set_fire(id, Some(fire));
            self.damage_prop(id, FIRE_DAMAGE as f32, DMG_BURN | DMG_DIRECT);
        }
    }

    /// `cl_playermodel`: remembered now, worn from the next spawn on (as in the game).
    /// `cl_playerskin` / `cl_playerbodygroups`: worn from the next spawn, the body string cut
    /// to its digits (one per body part, at most 32).
    pub fn set_wanted_skin_body(&mut self, id: u32, skin: u8, body: &str) {
        if let Some(p) = self.players.get_mut(&id) {
            p.wanted_skin = skin;
            p.wanted_body = body.chars().filter(char::is_ascii_digit).take(32).collect();
        }
    }

    pub fn set_wanted_model(&mut self, id: u32, name: &str) {
        if let Some(p) = self.players.get_mut(&id) {
            p.wanted_model = name.chars().take(64).collect();
        }
    }

    /// `PlayerLoadout`: the inventory is emptied, `Request::Loadout` asked (a hook may give
    /// its own weapons there and cancel), then the default 13 weapons with the crowbar out.
    fn give_loadout(&mut self, id: u32) {
        let Some(p) = self.players.get_mut(&id) else {
            return;
        };
        p.weapons.clear();
        p.active_weapon.clear();
        p.inventory.clear();
        if self.ask(Request::Loadout { player: id }) == Verdict::Cancel {
            return;
        }
        let Some(p) = self.players.get_mut(&id) else {
            return;
        };
        p.weapons = LOADOUT.iter().map(|w| w.to_string()).collect();
        p.active_weapon = SPAWN_WEAPON.to_string();
        p.inventory.give_loadout();
        p.inventory.select(SPAWN_WEAPON);
    }

    /// `Player:Kill`: dead where they stood, ragdoll there, weapons gone next tick, respawn in
    /// `RESPAWN_TICKS`.
    /// `SelectWeapon`: a carried weapon becomes active in the same tick, its deploy time arms the
    /// fire timers (measured `weapon_switch`). Dead players and unknown classes are ignored.
    /// The sandbox limit for `kind`; under it the addon runtime may still deny
    /// (`PlayerCheckLimit`).
    pub fn check_limit(
        &mut self,
        player: u32,
        kind: &str,
        events: &mut Vec<gm_sandbox::Event>,
    ) -> bool {
        if !self.sandbox.check_limit(player, kind, events) {
            return false;
        }
        self.ask(Request::CheckLimit {
            player,
            kind: kind.to_string(),
            current: self.sandbox.count_of(player, kind) as u32,
            max: self.sandbox.limits.get(kind),
        }) != Verdict::Cancel
    }

    /// An undo entry, unless the addon runtime refuses it (`CanCreateUndo`).
    pub fn push_undo(
        &mut self,
        player: u32,
        name: &str,
        text: String,
        custom: Option<String>,
        entities: Vec<u32>,
    ) {
        if self.ask(Request::CreateUndo {
            player,
            name: name.to_string(),
            text: text.clone(),
        }) == Verdict::Cancel
        {
            return;
        }
        self.sandbox.push_undo(player, name, text, custom, entities);
    }

    /// The `kill` console command: the addon runtime may refuse (`CanPlayerSuicide`).
    pub fn player_kill_command(&mut self, id: u32) -> bool {
        if !self.players.get(&id).is_some_and(|p| p.alive) {
            return false;
        }
        if self.ask(Request::Suicide { player: id }) == Verdict::Cancel {
            return false;
        }
        self.kill_player(id);
        true
    }

    /// The player's own weapon selection: the addon runtime may refuse (`PlayerSwitchWeapon`);
    /// scripted `Player:SelectWeapon` goes through [`Self::select_weapon`] unasked.
    pub fn player_select_weapon(&mut self, id: u32, class: &str) -> bool {
        let Some(from) = self.players.get(&id).map(|p| p.active_weapon.clone()) else {
            return false;
        };
        if from == class || !self.players[&id].weapons.iter().any(|w| w == class) {
            return false;
        }
        if self.ask(Request::SwitchWeapon {
            player: id,
            from,
            to: class.to_string(),
        }) == Verdict::Cancel
        {
            return false;
        }
        self.select_weapon(id, class)
    }

    pub fn select_weapon(&mut self, id: u32, class: &str) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        if !p.alive || !p.weapons.iter().any(|w| w == class) || p.active_weapon == class {
            return false;
        }
        if p.swep.contains_key(class) || p.swep.contains_key(&p.active_weapon) {
            let prev = std::mem::replace(&mut p.active_weapon, class.to_string());
            self.swep_switch(id, &prev, class);
            return true;
        }
        p.active_weapon = class.to_string();
        p.inventory.select(class);
        true
    }

    /// A fresh `Give` of a weapon the player already carries right after a spawn (the probe's
    /// `fire_*`/`hit_*` setup): selected with the give timers and reserve (`Inventory::give`).
    pub fn give_weapon(&mut self, id: u32, class: &str) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        if !p.alive {
            return false;
        }
        let scripted = self
            .scripted_weapons
            .iter()
            .find(|w| w.class == class)
            .cloned();
        if weapons::def(class).is_none() && scripted.is_none() {
            return false;
        }
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        if !p.weapons.iter().any(|w| w == class) {
            p.weapons.push(class.to_string());
        }
        if let Some(sw) = scripted {
            // measured: `Give` with `DefaultClip` fills the clip and adds no reserve
            p.inventory
                .clips
                .insert(class.to_string(), [sw.default_clip.max(-1), -1]);
            p.swep.entry(class.to_string()).or_default();
        } else {
            p.inventory.give(class);
        }
        let prev = std::mem::replace(&mut p.active_weapon, class.to_string());
        if prev != class {
            self.swep_switch(id, &prev, class);
        }
        true
    }

    /// Holster / deploy callbacks of scripted weapons on a switch (measured: the holster, with
    /// the class switched to, comes before the deploy in the same tick; the deploy blocks the
    /// primary for 0.2 s).
    /// Script `StripWeapon` / `StripWeapons`: drop the class (all classes with `None`) from the
    /// inventory; stripping the active weapon selects the first remaining one.
    pub fn strip_weapon(&mut self, id: u32, class: Option<&str>) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        let before = p.weapons.len();
        let had = p.weapons.clone();
        match class {
            Some(c) => {
                p.weapons.retain(|w| w != c);
                p.inventory.clips.remove(c);
            }
            None => {
                p.weapons.clear();
                p.inventory.clips.clear();
            }
        }
        if p.weapons.len() == before {
            return false;
        }
        if !p.weapons.contains(&p.active_weapon) {
            let next = p.weapons.first().cloned().unwrap_or_default();
            p.active_weapon = next.clone();
            if !next.is_empty() {
                p.inventory.select(&next);
            }
        }
        let removed: Vec<String> = had.into_iter().filter(|w| !p.weapons.contains(w)).collect();
        for class in removed {
            self.game_events
                .push(GameEvent::WeaponRemoved { player: id, class });
        }
        true
    }

    /// Script `SetAmmo` / `GiveAmmo` / `RemoveAmmo`: reserve ammo of one type, clamped at zero.
    /// Returns the new count.
    pub fn set_ammo(&mut self, id: u32, ammo: &str, count: i32, add: bool) -> i32 {
        let Some(p) = self.players.get_mut(&id) else {
            return 0;
        };
        let slot = p.inventory.ammo.entry(ammo.to_string()).or_insert(0);
        *slot = if add { *slot + count } else { count }.max(0);
        *slot
    }

    /// Script `Weapon:SetClip1/2`: the clip of a carried weapon, clamped at zero.
    pub fn set_clip(&mut self, id: u32, class: &str, slot: usize, count: i32) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        if !p.weapons.iter().any(|w| w == class) || slot > 1 {
            return false;
        }
        p.inventory.clips.entry(class.to_string()).or_insert([0, 0])[slot] = count.max(0);
        true
    }

    fn swep_switch(&mut self, id: u32, from: &str, to: &str) {
        let Some(p) = self.players.get_mut(&id) else {
            return;
        };
        let mut events = Vec::new();
        if p.swep.contains_key(from) {
            events.push((from.to_string(), "holster", to.to_string()));
        }
        if let Some(st) = p.swep.get_mut(to) {
            st.next_primary = SWEP_DEPLOY_DELAY;
            st.deploy_left = SWEP_DEPLOY_DELAY;
            st.reloading = None;
            events.push((to.to_string(), "deploy", String::new()));
        }
        for (class, kind, other) in events {
            self.swep_event(id, &class, kind, other, None);
        }
    }

    fn swep_event(
        &mut self,
        player: u32,
        class: &str,
        kind: &'static str,
        other: String,
        trace: Option<(Vec3, Vec3, Option<ToolHit>)>,
    ) {
        let Some(p) = self.players.get(&player) else {
            return;
        };
        let clip = p.inventory.clip(class)[0];
        let reserve = self
            .scripted_weapons
            .iter()
            .find(|w| w.class == class)
            .and_then(|w| p.inventory.ammo.get(&w.ammo))
            .copied()
            .unwrap_or(0);
        let (eye, forward, hit) = trace
            .map(|(e, f, h)| (e, f, h.map(|h| (h.ent.unwrap_or(0), h.pos, h.normal))))
            .unwrap_or_default();
        self.game_events.push(GameEvent::Weapon {
            player,
            class: class.to_string(),
            kind,
            clip,
            reserve,
            eye,
            forward,
            hit,
            other,
        });
    }

    /// `weapons.Register`: a new class or a changed definition of a known one.
    pub fn register_entity(&mut self, def: ScriptedEntity) {
        match self
            .scripted_entities
            .iter_mut()
            .find(|e| e.class == def.class)
        {
            Some(cur) => *cur = def,
            None => self.scripted_entities.push(def),
        }
        self.content_version += 1;
    }

    /// Spawns an instance of a scripted entity class: a prop with the class's model plus the
    /// think schedule; `init` fires in the spawn tick (the game's `Initialize` runs inside `Spawn`).
    pub fn script_spawn_entity(
        &mut self,
        owner: u32,
        class: &str,
        pos: Vec3,
        angles: Vec3,
        frozen: bool,
        shape: Option<PhysShape>,
    ) -> Option<u32> {
        let def = self
            .scripted_entities
            .iter()
            .find(|e| e.class == class)?
            .clone();
        let ent = self.spawn_counted(owner, &def.model, pos, angles, frozen, "sents")?;
        if let Some(shape) = shape {
            self.set_script_shape(ent, shape);
        }
        self.sents.insert(
            ent,
            SentState {
                class: def.class.clone(),
                next_think: self.tick_count + SENT_FIRST_THINK_TICKS,
                last_think: None,
                overlay: String::new(),
                trigger: true,
                trigger_pad: None,
            },
        );
        self.sent_event(ent, "init", 0, 0, 0.0);
        Some(ent)
    }

    fn sent_event(&mut self, ent: u32, kind: &'static str, player: u32, other: u32, amount: f32) {
        if matches!(kind, "start_touch" | "touch" | "end_touch")
            && self.sents.get(&ent).is_some_and(|s| !s.trigger)
        {
            return;
        }
        if let Some(s) = self.sents.get(&ent) {
            self.game_events.push(GameEvent::Sent {
                ent,
                class: s.class.clone(),
                kind,
                player,
                other,
                amount,
            });
        }
    }

    /// `ENT:NextThink(CurTime() + seconds)` for an instance: its next think moves to that time
    /// (at least the next tick); false when `ent` is not a scripted entity.
    pub fn set_next_think(&mut self, ent: u32, seconds: f32) -> bool {
        let ticks = ((seconds / gm_core::tick::DEFAULT_TICK_INTERVAL).round() as u64).max(1);
        let now = self.tick_count;
        match self.sents.get_mut(&ent) {
            Some(s) => {
                // from the think's own callback (the events of the tick just run) the time is
                // that tick's, as the game's CurTime() is there
                let base = match s.last_think {
                    Some(t) if t + 1 == now => t,
                    _ => now,
                };
                s.next_think = (base + ticks).max(now + 1);
                true
            }
            None => false,
        }
    }

    fn sent_think_ticks(&self, class: &str) -> u64 {
        match self.scripted_entities.iter().find(|e| e.class == class) {
            Some(ScriptedEntity { think: Some(s), .. }) => {
                ((*s / gm_core::tick::DEFAULT_TICK_INTERVAL).round() as u64).max(1)
            }
            _ => SENT_DEFAULT_THINK_TICKS,
        }
    }

    /// The scripted entities' thinks that are due this tick.
    fn sent_tick(&mut self) {
        let now = self.tick_count;
        let mut due: Vec<u32> = self
            .sents
            .iter()
            .filter(|(_, s)| s.next_think <= now)
            .map(|(id, _)| *id)
            .collect();
        due.sort_unstable();
        for ent in due {
            let class = self.sents[&ent].class.clone();
            let next = now + self.sent_think_ticks(&class);
            let s = self.sents.get_mut(&ent).unwrap();
            s.next_think = next;
            s.last_think = Some(now);
            self.sent_event(ent, "think", 0, 0, 0.0);
        }
    }

    fn sent_use_type(&self, ent: u32) -> Option<UseType> {
        let s = self.sents.get(&ent)?;
        self.scripted_entities
            .iter()
            .find(|e| e.class == s.class)
            .map(|e| e.use_type)
    }

    pub fn register_weapon(&mut self, def: ScriptedWeapon) {
        match self
            .scripted_weapons
            .iter_mut()
            .find(|w| w.class == def.class)
        {
            Some(cur) if *cur == def => return,
            Some(cur) => *cur = def,
            None => self.scripted_weapons.push(def),
        }
        self.scripted_weapons_version += 1;
        self.content_version += 1;
    }

    /// Every weapon class the wire can name: `LOADOUT`, then the scripted ones in order.
    pub fn weapon_classes(&self) -> Vec<String> {
        LOADOUT
            .iter()
            .map(|w| w.to_string())
            .chain(self.scripted_weapons.iter().map(|w| w.class.clone()))
            .collect()
    }

    /// Bullets a scripted weapon's `primary` asks for (`fire_bullet`): `damage` per bullet on a
    /// player, the same hit path as the stock weapons (hit groups, prop damage, impulse).
    pub fn script_bullets(&mut self, player: u32, damage: f32, pellets: u8, spread: f32) -> bool {
        let Some((eye, angles)) = self.eye(player) else {
            return false;
        };
        if !self.players.get(&player).is_some_and(|p| p.alive) {
            return false;
        }
        let forward = gm_sandbox::forward(angles.x, angles.y);
        let shot = weapons::Shot {
            pellets: pellets.max(1),
            spread,
            ammo: "Pistol",
        };
        self.resolve_shot_with(player, eye, forward, shot, "player", 0, Some(damage));
        true
    }

    /// One tick of the active scripted weapon of a player with a command (law in
    /// [`ScriptedWeapon`]).
    fn swep_tick(&mut self, player: u32, buttons: u32) {
        let Some(p) = self.players.get(&player) else {
            return;
        };
        let class = p.active_weapon.clone();
        let Some(def) = self
            .scripted_weapons
            .iter()
            .find(|w| w.class == class)
            .cloned()
        else {
            return;
        };
        let Some(p) = self.players.get_mut(&player) else {
            return;
        };
        let st = p.swep.entry(class.clone()).or_default();
        let attack = buttons & IN_ATTACK != 0;
        let attack2 = buttons & IN_ATTACK2 != 0;
        let reload = buttons & weapons::IN_RELOAD != 0;
        let (edge, edge2, edge_r) = (
            attack && !st.prev_attack,
            attack2 && !st.prev_attack2,
            reload && !st.prev_reload,
        );
        st.prev_attack = attack;
        st.prev_attack2 = attack2;
        st.prev_reload = reload;
        st.next_primary -= weapons::TICK_DT;
        st.next_secondary -= weapons::TICK_DT;
        st.deploy_left -= weapons::TICK_DT;
        let think = st.deploy_left < 0.0;
        let clip = p.inventory.clips.entry(class.clone()).or_insert([-1, -1]);
        let reserve = p.inventory.ammo.entry(def.ammo.clone()).or_insert(0);
        if let Some(left) = st.reloading.as_mut() {
            *left -= weapons::TICK_DT;
            if *left <= 0.0 {
                st.reloading = None;
                if def.clip_size > 0 {
                    let take = (def.clip_size - clip[0]).clamp(0, *reserve);
                    clip[0] += take;
                    *reserve -= take;
                }
            }
        }
        let mut events: Vec<(&'static str, bool)> = Vec::new();
        let busy = st.reloading.is_some();
        let wants_fire = edge || (def.automatic && attack);
        if !busy && wants_fire && st.next_primary <= 0.0 {
            if def.clip_size > 0 && clip[0] == 0 {
                // measured: an empty clip plus a press starts the reload instead
                if *reserve > 0 {
                    st.reloading = Some(def.reload_time);
                    st.next_primary = def.reload_time;
                    events.push(("reload", false));
                }
            } else {
                if def.clip_size > 0 {
                    clip[0] -= 1;
                } else if def.clip_size < 0 && *reserve > 0 {
                    *reserve -= 1;
                }
                st.next_primary = def.primary_delay;
                events.push(("primary", true));
            }
        }
        if !busy && edge2 && st.next_secondary <= 0.0 {
            st.next_secondary = def.secondary_delay;
            events.push(("secondary", true));
        }
        if !busy && edge_r && def.clip_size > 0 && clip[0] < def.clip_size && *reserve > 0 {
            st.reloading = Some(def.reload_time);
            st.next_primary = def.reload_time;
            events.push(("reload", false));
        }
        for (kind, traced) in events {
            let trace = traced.then(|| {
                let (eye, angles) = self.eye(player).unwrap_or_default();
                (
                    eye,
                    gm_sandbox::forward(angles.x, angles.y),
                    self.tool_hit(player),
                )
            });
            self.swep_event(player, &class, kind, String::new(), trace);
        }
        if think {
            self.swep_event(player, &class, "think", String::new(), None);
        }
    }

    /// Where a player stood (origin, ducked) at server tick `seen`, interpolated between the two
    /// recorded ticks around it; the current pose when `seen` is 0 or outside the history.
    fn pose_at(&self, p: &Player, seen: u32) -> (Vec3, bool) {
        let now = (p.state.origin, p.state.ducked);
        if seen == 0 {
            return now;
        }
        let (Some(first), Some(last)) = (p.history.front(), p.history.back()) else {
            return now;
        };
        if seen >= last.0 || seen < first.0 {
            return now;
        }
        let i = p.history.partition_point(|h| h.0 <= seen);
        let (a, b) = (&p.history[i - 1], &p.history[i]);
        let f = (seen - a.0) as f32 / (b.0 - a.0).max(1) as f32;
        (a.1.lerp(b.1, f), a.2)
    }

    /// A trigger pull: the bullet (all pellets along the aim, no spread yet) against the other
    /// live players' hulls and the world; the hit group from the height on the target
    /// (`weapons::hitgroup_at`), the ammo's multiplayer damage scaled by it, applied as
    /// DMG_BULLET the same tick (recordings `hit_*`).
    fn resolve_shot(
        &mut self,
        attacker: u32,
        eye: Vec3,
        forward: Vec3,
        shot: weapons::Shot,
        class: &'static str,
        seen_tick: u32,
    ) {
        self.resolve_shot_with(attacker, eye, forward, shot, class, seen_tick, None);
    }

    #[allow(clippy::too_many_arguments)]
    fn resolve_shot_with(
        &mut self,
        attacker: u32,
        eye: Vec3,
        forward: Vec3,
        shot: weapons::Shot,
        class: &'static str,
        seen_tick: u32,
        damage: Option<f32>,
    ) {
        // the player-vs-player table may lack the ammo (AR2 is NPC-only); NPCs have their own
        let base = damage.or_else(|| weapons::bullet_damage(shot.ammo));
        if self.ask(Request::FireBullets {
            attacker,
            src: eye,
            dir: forward,
            pellets: shot.pellets,
            ammo: shot.ammo,
            damage: base.unwrap_or(0.0),
        }) == Verdict::Cancel
        {
            return;
        }
        self.game_events.push(GameEvent::FiredBullets {
            attacker,
            src: eye,
            dir: forward,
            pellets: shot.pellets,
            ammo: shot.ammo,
        });
        const MAX_TRACE: f32 = 56755.84;
        let end = eye + forward * MAX_TRACE;
        let world = self
            .collision
            .trace_ray(eye, end, gm_collision::MASK_PLAYERSOLID);
        self.effects.push(WorldEffect::Tracer {
            player: attacker,
            end: world.end,
        });
        let d = end - eye;
        let prop = gm_sandbox::trace_line(self.collision, &self.prop_bodies(), eye, end)
            .filter(|h| h.ent.is_some());
        let mut best: Option<(u32, f32)> = None;
        for (id, p) in &self.players {
            if *id == attacker || !p.alive {
                continue;
            }
            let (origin, ducked) = self.pose_at(p, seen_tick);
            let (mins, maxs) = p.move_override.hull(&self.mover.cfg, ducked);
            let (lo, hi) = (origin + mins, origin + maxs);
            let (mut t0, mut t1) = (0.0f32, 1.0f32);
            let mut inside = true;
            for a in 0..3 {
                if d[a].abs() < 1e-6 {
                    if eye[a] < lo[a] || eye[a] > hi[a] {
                        inside = false;
                        break;
                    }
                    continue;
                }
                let (mut ta, mut tb) = ((lo[a] - eye[a]) / d[a], (hi[a] - eye[a]) / d[a]);
                if ta > tb {
                    std::mem::swap(&mut ta, &mut tb);
                }
                t0 = t0.max(ta);
                t1 = t1.min(tb);
                if t0 > t1 {
                    inside = false;
                    break;
                }
            }
            if inside && best.is_none_or(|b| t0 < b.1) {
                best = Some((*id, t0));
            }
        }
        // NPC hulls: the nearest live body on the ray takes the bullet before players behind it
        let mut npc_hit: Option<(u32, f32)> = None;
        for (id, n) in &self.npcs {
            if n.dead_at.is_some() || n.solid == 0 || n.child_of.is_some() {
                continue;
            }
            if let Some(t) = ray_box(eye, d, n.pos + n.mins, n.pos + n.maxs) {
                if npc_hit.is_none_or(|b| t < b.1) {
                    npc_hit = Some((*id, t));
                }
            }
        }
        {
            let mut t_end = world.fraction;
            if let Some(h) = prop.as_ref() {
                t_end = t_end.min(h.fraction);
            }
            if let Some((_, t)) = best {
                t_end = t_end.min(t);
            }
            if let Some((_, t)) = npc_hit {
                t_end = t_end.min(t);
            }
            let seg = d * t_end;
            let near: Vec<u32> = self
                .npcs
                .iter()
                .filter(|(id, n)| {
                    n.dead_at.is_none()
                        && npc_hit.is_none_or(|h| h.0 != **id)
                        && npc_weapon_shot_in(&n.weapon, &self.scripted_weapons).is_some()
                        && segment_distance(eye, seg, n.pos + Vec3::new(0.0, 0.0, NPC_CHEST_HEIGHT))
                            <= NPC_SUPPRESS_RADIUS
                })
                .map(|(id, _)| *id)
                .collect();
            for id in near {
                let tick = self.tick_count;
                let Some(n) = self.npcs.get_mut(&id) else {
                    continue;
                };
                if tick > n.suppress_since + NPC_SUPPRESS_WINDOW {
                    n.suppress_hits = 0;
                    n.suppress_since = tick;
                }
                n.suppress_hits += 1;
                if n.suppress_hits >= NPC_SUPPRESS_SHOTS {
                    n.suppress_hits = 0;
                    self.npc_threatened(id, attacker, tick, false);
                }
            }
        }
        if let Some((npc, t)) = npc_hit {
            if best.is_none_or(|b| t < b.1)
                && prop.as_ref().is_none_or(|h| t < h.fraction)
                && t < world.fraction
            {
                let Some(dmg) = weapons::npc_bullet_damage(shot.ammo).map(|v| damage.unwrap_or(v))
                else {
                    return;
                };
                let hit = eye + d * t;
                if let Some(color) = self.npcs.get(&npc).and_then(|n| blood_color(&n.class)) {
                    self.blood(hit, d, dmg, color);
                }
                let group = self
                    .npcs
                    .get(&npc)
                    .and_then(|n| {
                        let h = n.maxs.z - n.mins.z;
                        let rel = (hit.z - (n.pos.z + n.mins.z)) * 72.0 / h.max(1.0)
                            + npc_pose_hit_shift(
                                &n.sequence,
                                self.tick_count.saturating_sub(n.pose_since),
                            );
                        let facing =
                            gm_sandbox::rotation(Vec3::new(0.0, n.angles.y, 0.0)) * Vec3::X;
                        let to_shooter = -d.truncate().normalize_or_zero();
                        let side_on = facing.truncate().dot(to_shooter).abs() < NPC_SIDE_ON_COS;
                        weapons::hitgroup_at(rel).map(|g| {
                            if g != weapons::HITGROUP_HEAD
                                && (side_on
                                    || (npc_pose_arm_cover(&n.sequence)
                                        && self.tick_count >= n.pose_since + NPC_POSE_BLEND_TICKS))
                            {
                                weapons::HITGROUP_LEFTARM
                            } else {
                                g
                            }
                        })
                    })
                    .unwrap_or(weapons::HITGROUP_CHEST);
                for _ in 0..shot.pellets {
                    self.damage_npc(npc, attacker, dmg, group);
                }
                return;
            }
        }
        let Some(base) = base else {
            return;
        };
        if let Some(h) = prop {
            if best.is_none_or(|b| h.fraction < b.1) {
                if let Some(damage) = weapons::prop_bullet_damage(shot.ammo) {
                    let n = shot.pellets as f32;
                    self.hit_prop(
                        h.ent.unwrap_or(0),
                        attacker,
                        damage * n,
                        weapons::prop_bullet_dmg_type(shot.ammo),
                        h.pos,
                        forward * (weapons::prop_bullet_force(shot.ammo) * n),
                        class,
                    );
                }
                return;
            }
        }
        let Some((target, frac)) = best else {
            if world.fraction < 1.0 {
                self.world_impact(&world, false);
            }
            return;
        };
        if world.fraction < frac {
            self.world_impact(&world, false);
            return;
        }
        let (frac, group, pos) = match &self.hit_model {
            Some(model) => {
                let p = &self.players[&target];
                let Some(h) = model.trace(p.state.origin, p.view_angles.y, eye, end) else {
                    return;
                };
                h
            }
            None => {
                let pos = eye + d * frac;
                let rel_z = pos.z - self.players[&target].state.origin.z;
                let Some(group) = weapons::hitgroup_at(rel_z) else {
                    return;
                };
                (frac, group, pos)
            }
        };
        if world.fraction < frac {
            self.world_impact(&world, false);
            return;
        }
        let damage = base * weapons::hitgroup_scale(group) * shot.pellets as f32;
        let dmg_type = weapons::bullet_dmg_type(shot.ammo);
        self.blood(pos, d, damage, 0);
        self.hits.push(Hit {
            tick: self.tick_count,
            attacker,
            target,
            damage,
            dmg_type,
            hitgroup: Some(group),
            pos,
            ammo: shot.ammo,
            inflictor: "player",
        });
        if !self.players_hurt_players {
            return;
        }
        let push = Vec3::new(forward.x, forward.y, 0.0).normalize_or_zero()
            * (weapons::KNOCKBACK_PER_DAMAGE * damage);
        if let Some(t) = self.players.get_mut(&target) {
            t.state.impulse += push;
            t.last_damage = (attacker, class);
        }
        self.damage_player(target, damage, dmg_type);
    }

    /// Sandbox props as trace bodies (hull planes in the entity frame).
    fn prop_bodies(&self) -> Vec<PropBody> {
        self.sandbox
            .props()
            .iter()
            .filter_map(|p| {
                let hulls = self.hull_planes.get(&p.model)?.clone();
                Some(PropBody {
                    id: p.id,
                    bone: 0,
                    pos: p.pos,
                    angles: p.angles,
                    hulls,
                })
            })
            .collect()
    }

    /// `Entity:TakeDamage` on a prop: the hit is logged, the damage force applied at the hit
    /// point as an impulse (`weapons::prop_bullet_force`), a breakable prop loses the damage and
    /// is removed at zero.
    #[allow(clippy::too_many_arguments)]
    fn hit_prop(
        &mut self,
        prop: u32,
        attacker: u32,
        damage: f32,
        dmg_type: u32,
        pos: Vec3,
        force: Vec3,
        inflictor: &'static str,
    ) {
        // measured `server_vehicle_damage`: a vehicle takes neither bullet damage nor the bullet's
        // push (the wooden chair stays 30/30 and does not move a unit across pistol and .357 hits,
        // the pod 0/1 after 500, the jeep after 5000)
        let vehicle = self.vehicles.contains_key(&prop);
        let broke = !vehicle && self.damage_prop(prop, damage, dmg_type);
        if !broke {
            if let Some(st) = self.prop_state(prop) {
                let inv = st.rotation.inverse();
                let surface = self
                    .sandbox
                    .props()
                    .iter()
                    .find(|p| p.id == prop)
                    .and_then(|p| self.models.get(&p.model))
                    .map(|m| m.surfaceprop.clone())
                    .unwrap_or_else(|| "concrete".to_owned());
                self.effects.push(WorldEffect::PropImpact {
                    ent: prop,
                    lpos: inv * (pos - st.position),
                    lnormal: inv * -force.normalize_or_zero(),
                    surface,
                });
            }
        }
        self.prop_hits.push(PropHit {
            tick: self.tick_count,
            attacker,
            prop,
            damage,
            dmg_type,
            pos,
            force,
            inflictor,
            broke,
        });
        if !broke && !vehicle {
            if let Some(&body) = self.bodies.get(&prop) {
                self.physics.add_impulse_at(body, pos, force);
            }
        }
    }

    /// A crowbar swing (`weapons::MELEE_*`): the first player hull on the aim within reach,
    /// before the world.
    fn resolve_melee(&mut self, attacker: u32, eye: Vec3, forward: Vec3) {
        let end = eye + forward * weapons::MELEE_RANGE;
        let world = self
            .collision
            .trace_ray(eye, end, gm_collision::MASK_PLAYERSOLID);
        let mut best: Option<(u32, f32)> = None;
        for (id, p) in &self.players {
            if *id == attacker || !p.alive {
                continue;
            }
            let (mins, maxs) = p.move_override.hull(&self.mover.cfg, p.state.ducked);
            if let Some(t) =
                ray_box_entry(eye, forward, p.state.origin + mins, p.state.origin + maxs)
            {
                if t <= weapons::MELEE_RANGE && best.is_none_or(|b| t < b.1) {
                    best = Some((*id, t));
                }
            }
        }
        let prop = gm_sandbox::trace_line(self.collision, &self.prop_bodies(), eye, end)
            .filter(|h| h.ent.is_some());
        if let Some(h) = prop {
            if best.is_none_or(|b| h.fraction * weapons::MELEE_RANGE < b.1) {
                self.hit_prop(
                    h.ent.unwrap_or(0),
                    attacker,
                    weapons::MELEE_DAMAGE,
                    weapons::DMG_CLUB,
                    h.pos,
                    forward * weapons::MELEE_PROP_FORCE,
                    "weapon_crowbar",
                );
                return;
            }
        }
        // `Weapon_Crowbar.Melee_HitWorld` / `.Melee_Hit` on top of the swing's `.Single`
        let Some((target, t)) = best else {
            if world.fraction < 1.0 {
                self.melee_world_hit(attacker, &world);
            }
            return;
        };
        if world.fraction * weapons::MELEE_RANGE < t {
            self.melee_world_hit(attacker, &world);
            return;
        }
        self.sounds.push(WorldSound {
            name: "Weapon_Crowbar.Melee_Hit".to_owned(),
            pos: eye + forward * t,
            volume: 1.0,
            ent: attacker,
            ..Default::default()
        });
        let damage = weapons::MELEE_DAMAGE;
        self.hits.push(Hit {
            tick: self.tick_count,
            attacker,
            target,
            damage,
            dmg_type: weapons::DMG_CLUB,
            hitgroup: Some(0),
            pos: eye + forward * (t - 1.0 / 32.0),
            ammo: "",
            inflictor: "weapon_crowbar",
        });
        if !self.players_hurt_players {
            return;
        }
        let fwd = Vec3::new(forward.x, forward.y, 0.0).normalize_or_zero();
        let right = Vec3::new(fwd.y, -fwd.x, 0.0);
        let [pf, pr, pu] = weapons::MELEE_PUSH_POINT;
        let from = eye + fwd * pf + right * pr + Vec3::Z * pu;
        if let Some(t) = self.players.get_mut(&target) {
            let center = t.state.origin + Vec3::new(0.0, 0.0, weapons::PLAYER_CENTER_Z);
            let mut push =
                (center - from).normalize_or_zero() * (weapons::MELEE_PUSH_PER_DAMAGE * damage);
            push.z = push.z.min(weapons::PUSH_MAX_Z);
            t.state.impulse += push;
            t.last_damage = (attacker, "weapon_crowbar");
        }
        self.damage_player(target, damage, weapons::DMG_CLUB);
    }

    fn melee_world_hit(&mut self, attacker: u32, world: &gm_collision::Trace) {
        self.world_impact(world, true);
        self.sounds.push(WorldSound {
            name: "Weapon_Crowbar.Melee_HitWorld".to_owned(),
            pos: world.end,
            volume: 1.0,
            ent: attacker,
            ..Default::default()
        });
    }

    /// Knockback of a hit from `from` (the inflictor's position): see `weapons::PUSH_PER_DAMAGE`.
    fn push_player(&mut self, id: u32, from: Vec3, damage: f32) {
        let Some(t) = self.players.get_mut(&id) else {
            return;
        };
        let center = t.state.origin + Vec3::new(0.0, 0.0, weapons::PLAYER_CENTER_Z);
        let dir = (center - (from - Vec3::new(0.0, 0.0, weapons::PUSH_INFLICTOR_DROP)))
            .normalize_or_zero();
        let mut push = dir * (weapons::PUSH_PER_DAMAGE * damage);
        push.z = push.z.min(weapons::PUSH_MAX_Z);
        t.state.velocity += push;
        if t.state.on_ground {
            t.state.ground_push = true;
        }
    }

    /// Radius damage of an explosion at `at` (the inflictor's position; the blast itself is
    /// 1 u above it): `weapons::explosion` for the law. A player whose eye the blast cannot
    /// see takes nothing.
    fn explode(&mut self, at: Vec3, attacker: u32, base: f32, radius: f32, class: &'static str) {
        let src = at + Vec3::new(0.0, 0.0, 1.0);
        // env_explosion: SOUND_COMBAT at the blast (1024) and SOUND_DANGER around it (400)
        self.npc_hear(src, 1024.0, ai::COND_HEAR_COMBAT, None);
        self.npc_hear(src, 400.0, ai::COND_HEAR_DANGER, None);
        // the `Explosion` effect's sound (`BaseExplosionEffect.Sound`, CHAN_STATIC, 140 dB)
        self.sounds.push(WorldSound {
            name: "BaseExplosionEffect.Sound".to_owned(),
            pos: src,
            volume: 1.0,
            ..Default::default()
        });
        self.effects.push(WorldEffect::Explosion { pos: src });
        let bodies = self.prop_bodies();
        let targets: Vec<(u32, Vec3)> = self
            .sandbox
            .props()
            .iter()
            .filter_map(|p| {
                let b = self.models.get(&p.model)?.bounds;
                Some((p.id, p.pos + Vec3::new(0.0, 0.0, (b.min.z + b.max.z) * 0.5)))
            })
            .collect();
        for (id, center) in targets {
            let to = center - src;
            let len = to.length();
            if len < 1e-3 {
                continue;
            }
            let dir = to / len;
            let dist = match gm_sandbox::trace_line(self.collision, &bodies, src, center) {
                Some(h) if h.ent == Some(id) => ((h.pos - src).length() - 1.0 / 32.0).max(0.0),
                Some(h) if h.ent.is_none() => continue,
                Some(_) => continue,
                None => 0.0,
            };
            if dist >= radius {
                continue;
            }
            let damage = base * (1.0 - dist / radius);
            let force = (damage * weapons::BLAST_FORCE_PER_DAMAGE).min(weapons::BLAST_FORCE_MAX);
            self.hit_prop(
                id,
                attacker,
                damage,
                weapons::DMG_BLAST,
                src,
                dir * force,
                class,
            );
        }
        let ids: Vec<u32> = self.players.keys().copied().collect();
        for id in ids {
            let p = &self.players[&id];
            if !p.alive {
                continue;
            }
            let (mins, maxs) = p.move_override.hull(&self.mover.cfg, p.state.ducked);
            let (lo, hi) = (p.state.origin + mins, p.state.origin + maxs);
            let eye = p.state.origin + Vec3::new(0.0, 0.0, weapons::PLAYER_EYE_Z);
            let to = eye - src;
            let len = to.length();
            if len < 1e-3 {
                continue;
            }
            let dir = to / len;
            // the game's trace to the eye stops 1/32 u before the hull
            let Some(dist) = ray_box_entry(src, dir, lo, hi).map(|d| (d - 1.0 / 32.0).max(0.0))
            else {
                continue;
            };
            if dist >= radius {
                continue;
            }
            let world = self
                .collision
                .trace_ray(src, eye, gm_collision::MASK_PLAYERSOLID);
            if world.fraction * len < dist {
                continue;
            }
            let damage = base * (1.0 - dist / radius);
            self.hits.push(Hit {
                tick: self.tick_count,
                attacker,
                target: id,
                damage,
                dmg_type: weapons::DMG_BLAST,
                // the game runs blasts through ScalePlayerDamage with the generic group
                hitgroup: Some(0),
                pos: src,
                ammo: "",
                inflictor: class,
            });
            if !self.players_hurt_players {
                continue;
            }
            self.push_player(id, at, damage);
            self.hurt(id, damage, weapons::DMG_BLAST, RESPAWN_TICKS - 1);
        }
    }

    /// The first player (other than `owner`, alive) whose hit boxes the segment crosses: what an
    /// ignited rocket collides with and the laser dot lands on (`hit_rpg_direct` / `_dot150`:
    /// the game's 1500 u/s rocket passed 1.5 u under the hull's top, over the head box, without
    /// touching; `_dot300` through the head at 5.7 u under it hit). Before ignition the rocket is
    /// a 4-u box against the hull instead (`projectile_touch`, `ROCKET_HALF`: `_dot50` / `_dot100`
    /// touched 4 u in front of the hull's face, `_dot100` 2.6 u above its top). Without a hit
    /// model the hull stands in.
    fn hitbox_touch(&self, owner: u32, start: Vec3, end: Vec3) -> Option<(u32, Vec3)> {
        let Some(model) = &self.hit_model else {
            return self.projectile_touch(owner, start, end, 0.0, true);
        };
        let mut best: Option<(u32, f32, Vec3)> = None;
        for (id, p) in &self.players {
            if *id == owner || !p.alive {
                continue;
            }
            if let Some((frac, _, pos)) = model.trace(p.state.origin, p.view_angles.y, start, end) {
                if best.is_none_or(|b| frac < b.1) {
                    best = Some((*id, frac, pos));
                }
            }
        }
        best.map(|(id, _, pos)| (id, pos))
    }

    /// The player hull (other than `owner`, alive) a projectile touches: `end` inside a hull
    /// grown by `grow` (rockets and balls are resolved where they end the tick), or, with
    /// `sweep`, the first hull on the way from `start` (bolts stop at the hull).
    fn projectile_touch(
        &self,
        owner: u32,
        start: Vec3,
        end: Vec3,
        grow: f32,
        sweep: bool,
    ) -> Option<(u32, Vec3)> {
        let d = end - start;
        let len = d.length();
        let mut best: Option<(u32, f32)> = None;
        for (id, p) in &self.players {
            if *id == owner || !p.alive {
                continue;
            }
            let (mins, maxs) = p.move_override.hull(&self.mover.cfg, p.state.ducked);
            let lo = p.state.origin + mins - Vec3::splat(grow);
            let hi = p.state.origin + maxs + Vec3::splat(grow);
            let t = if sweep && len > 1e-6 {
                match ray_box_entry(start, d / len, lo, hi) {
                    Some(t) if t <= len => t,
                    _ => continue,
                }
            } else if end.cmpge(lo).all() && end.cmple(hi).all() {
                len
            } else {
                continue;
            };
            if best.is_none_or(|b| t < b.1) {
                best = Some((*id, t));
            }
        }
        // a swept box stops 1/32 u short of what it hits, like the game's traces
        best.map(|(id, t)| {
            let t = if sweep { (t - 1.0 / 32.0).max(0.0) } else { t };
            (
                id,
                if len > 1e-6 {
                    start + d * (t / len)
                } else {
                    end
                },
            )
        })
    }

    /// Existing projectiles fly one tick, then this tick's launches spawn (their first tick is
    /// the launch tick, recorded as such); a rocket's death reloads its owner's RPG. Rockets and
    /// grenades explode where they die (`explode`), a bolt or rocket that reaches a player hits
    /// it, a ball kills whoever it passes through (`weapons`).
    fn tick_projectiles(&mut self, launches: Vec<(u32, weapons::Launch, Vec3, Vec3)>) {
        if launches.iter().any(|l| l.1 == weapons::Launch::Grenade)
            && !self.models.contains_key(projectile::GRENADE_MODEL)
        {
            if let Some(loaded) = self
                .model_loader
                .as_mut()
                .and_then(|f| f(projectile::GRENADE_MODEL))
            {
                self.register_model(projectile::GRENADE_MODEL, loaded);
            }
        }
        let world = self.collision;
        // the RPG's laser dot: where the launcher's owner aims this tick, for the ignited
        // rockets to home on (`CMissile::SeekThink`) while the launcher is held
        let dots: HashMap<u32, Vec3> = self
            .projectiles
            .iter()
            .filter(|pr| pr.kind == weapons::Launch::Rocket)
            .filter_map(|pr| {
                let p = self.players.get(&pr.owner)?;
                if !p.alive || !(true) {
                    return None;
                }
                let (eye, ang) = self.eye(pr.owner)?;
                let f = gm_sandbox::forward(ang.x, ang.y);
                let dot = world
                    .trace_ray(eye, eye + f * 56755.84, gm_collision::MASK_SOLID)
                    .end;
                Some((pr.owner, dot))
            })
            .collect();
        let mut phys = projectile::Physics {
            world: &mut self.physics,
            grenade: self.models.get(projectile::GRENADE_MODEL),
            rng: &mut self.spawn_rng,
        };
        let mut steps = Vec::with_capacity(self.projectiles.len());
        for pr in &mut self.projectiles {
            if let Some(&dot) = dots.get(&pr.owner) {
                pr.home_on(dot);
            }
            let prev = pr.origin;
            steps.push((prev, pr.step(world, Some(&mut phys))));
        }
        // (kind, owner, where it died) for every projectile removed this tick
        let mut died = Vec::new();
        let mut keep = Vec::with_capacity(self.projectiles.len());
        for (i, (prev, ev)) in steps.into_iter().enumerate() {
            let pr = &self.projectiles[i];
            match ev {
                projectile::Event::Removed(at) => {
                    died.push((pr.kind, pr.owner, at));
                    keep.push(false);
                }
                projectile::Event::None => {
                    let (kind, owner, end) = (pr.kind, pr.owner, pr.origin);
                    let touch = match kind {
                        weapons::Launch::Rocket if pr.ignited() => {
                            self.hitbox_touch(owner, prev, end)
                        }
                        weapons::Launch::Rocket => {
                            self.projectile_touch(owner, prev, end, projectile::ROCKET_HALF, true)
                        }
                        weapons::Launch::Bolt => {
                            self.projectile_touch(owner, prev, end, projectile::BOLT_HALF, true)
                        }
                        weapons::Launch::Ball => {
                            self.projectile_touch(owner, prev, end, projectile::BALL_RADIUS, false)
                        }
                        weapons::Launch::Smg1Grenade => self.projectile_touch(
                            owner,
                            prev,
                            end,
                            projectile::AR2_GRENADE_HALF,
                            true,
                        ),
                        weapons::Launch::Grenade => None,
                    };
                    let prop_touch = if kind == weapons::Launch::Grenade
                        || self.sandbox.props().is_empty()
                    {
                        None
                    } else {
                        gm_sandbox::trace_line(world, &self.prop_bodies(), prev, end).filter(|h| {
                            h.ent.is_some()
                                && touch.is_none_or(|(_, at)| {
                                    (h.pos - prev).length() < (at - prev).length()
                                })
                        })
                    };
                    if let Some(h) = prop_touch {
                        let prop = h.ent.unwrap_or(0);
                        let dir = (end - prev).normalize_or_zero();
                        // the swept box stops its half extent short of the hull
                        let back = match kind {
                            weapons::Launch::Bolt => projectile::BOLT_HALF,
                            weapons::Launch::Smg1Grenade => projectile::AR2_GRENADE_HALF,
                            weapons::Launch::Ball => projectile::BALL_RADIUS,
                            _ => 1.0 / 32.0,
                        };
                        let at = h.pos - dir * back;
                        match kind {
                            weapons::Launch::Rocket | weapons::Launch::Smg1Grenade => {
                                died.push((kind, owner, at));
                                keep.push(false);
                            }
                            weapons::Launch::Bolt => {
                                self.projectiles[i].origin = at;
                                self.projectiles[i].velocity = Vec3::ZERO;
                                self.hit_prop(
                                    prop,
                                    owner,
                                    weapons::BOLT_DAMAGE,
                                    weapons::DMG_BULLET | weapons::DMG_NEVERGIB,
                                    h.pos,
                                    dir * weapons::BOLT_PROP_FORCE,
                                    "crossbow_bolt",
                                );
                                keep.push(true);
                            }
                            _ => {
                                self.hit_prop(
                                    prop,
                                    owner,
                                    weapons::BALL_PROP_DAMAGE,
                                    weapons::BALL_DMG_TYPE,
                                    h.pos,
                                    dir * weapons::BALL_PROP_FORCE,
                                    "prop_combine_ball",
                                );
                                keep.push(true);
                            }
                        }
                        continue;
                    }
                    match (kind, touch) {
                        (weapons::Launch::Rocket | weapons::Launch::Smg1Grenade, Some((_, at))) => {
                            died.push((kind, owner, at));
                            keep.push(false);
                        }
                        (weapons::Launch::Bolt, Some((target, at))) => {
                            self.projectiles[i].origin = at;
                            self.hits.push(Hit {
                                tick: self.tick_count,
                                attacker: owner,
                                target,
                                damage: weapons::BOLT_DAMAGE,
                                dmg_type: weapons::DMG_BULLET | weapons::DMG_NEVERGIB,
                                hitgroup: Some(0),
                                pos: at,
                                ammo: "",
                                inflictor: "crossbow_bolt",
                            });
                            if self.players_hurt_players {
                                self.push_player(target, at, weapons::BOLT_DAMAGE);
                                self.hurt(
                                    target,
                                    weapons::BOLT_DAMAGE,
                                    weapons::DMG_BULLET | weapons::DMG_NEVERGIB,
                                    RESPAWN_TICKS - 1,
                                );
                            }
                            keep.push(false);
                        }
                        (weapons::Launch::Ball, Some((target, _))) => {
                            let t = &self.players[&target];
                            let (mins, maxs) =
                                t.move_override.hull(&self.mover.cfg, t.state.ducked);
                            let at = end.clamp(t.state.origin + mins, t.state.origin + maxs);
                            let hp = t.health as f32;
                            self.hits.push(Hit {
                                tick: self.tick_count,
                                attacker: owner,
                                target,
                                damage: hp,
                                dmg_type: weapons::BALL_DMG_TYPE,
                                hitgroup: None,
                                pos: at,
                                ammo: "",
                                inflictor: "prop_combine_ball",
                            });
                            if self.players_hurt_players {
                                self.hurt(target, hp, weapons::BALL_DMG_TYPE, RESPAWN_TICKS - 1);
                            }
                            keep.push(true);
                        }
                        _ => keep.push(true),
                    }
                }
            }
        }
        let mut k = keep.into_iter();
        self.projectiles.retain(|_| k.next().unwrap_or(true));
        let threats: Vec<(u32, Vec3)> = self
            .projectiles
            .iter()
            .filter(|p| {
                weapons::explosion(p.kind).is_some()
                    && (p.kind != weapons::Launch::Grenade
                        || p.age + NPC_GRENADE_WARN_TICKS >= p.fuse)
            })
            .map(|p| (p.owner, p.origin))
            .chain(
                died.iter()
                    .filter(|(k, _, _)| weapons::explosion(*k).is_some())
                    .map(|(_, o, at)| (*o, *at)),
            )
            .collect();
        for (owner, at) in threats {
            let ids: Vec<u32> = self
                .npcs
                .iter()
                .filter(|(_, n)| {
                    n.dead_at.is_none()
                        && npc_weapon_shot_in(&n.weapon, &self.scripted_weapons).is_some()
                        && n.pos.distance(at) <= NPC_GRENADE_DANGER_RADIUS
                })
                .map(|(i, _)| *i)
                .collect();
            for id in ids {
                self.npc_threatened(id, owner, self.tick_count, true);
                if let Some(n) = self.npcs.get_mut(&id) {
                    if n.cover_wanted {
                        n.cover_from_sound = true;
                        n.danger_at = Some(at);
                    }
                }
            }
        }
        for (kind, owner, at) in died {
            if kind == weapons::Launch::Rocket {
                if let Some(p) = self.players.get_mut(&owner) {
                    p.inventory.rocket_died();
                }
            }
            if let Some((base, radius)) = weapons::explosion(kind) {
                self.explode(at, owner, base, radius, kind.class());
            }
        }
        let mut phys = projectile::Physics {
            world: &mut self.physics,
            grenade: self.models.get(projectile::GRENADE_MODEL),
            rng: &mut self.spawn_rng,
        };
        let mut spawned = Vec::new();
        for (owner, kind, eye, angles) in launches {
            if let Some(pr) =
                projectile::spawn(kind, owner, eye, angles.x, angles.y, world, Some(&mut phys))
            {
                spawned.push((eye, pr));
            }
        }
        for (eye, mut pr) in spawned {
            if pr.kind == weapons::Launch::Rocket {
                // the laser dot sits on the hull of a player standing in the aim before the
                // wall (2 u in front of its face at eye height in `hit_rpg_dot100` / `_dot300`)
                if let Some((_, at)) = self.projectile_touch(pr.owner, eye, pr.target, 0.0, true) {
                    pr.target = at;
                }
            }
            let mut pr = pr;
            pr.id = self.next_projectile_id;
            self.next_projectile_id += 1;
            self.projectiles.push(pr);
        }
    }

    pub fn kill_player(&mut self, id: u32) {
        if self
            .players
            .get(&id)
            .is_some_and(|p| p.alive && p.drop_weapon_on_death)
        {
            self.drop_weapon(id, None);
        }
        let tick = self.tick_count;
        let Some(p) = self.players.get_mut(&id) else {
            return;
        };
        if !p.alive {
            return;
        }
        p.alive = false;
        p.health = 0;
        p.deaths += 1;
        p.ragdoll = Some(Ragdoll {
            class: RAGDOLL_CLASS,
            model: p.model.clone(),
            origin: p.state.origin,
            angles: Vec3::ZERO,
            velocity: p.state.velocity,
            tick,
            ducked: p.state.ducked,
        });
        p.death_tick = Some(tick);
        p.active_weapon.clear();
        p.held = None;
        p.driving = None;
        p.state.velocity = Vec3::ZERO;
        self.game_events.push(GameEvent::PlayerDied {
            player: id,
            dmg_type: 0,
            attacker: 0,
            inflictor: "worldspawn".to_string(),
        });
    }

    pub fn register_model(&mut self, name: &str, info: ModelInfo) {
        self.hull_planes
            .insert(name.to_string(), info.hull_planes.clone());
        let mut script = info.script.clone();
        script.friction = info.surface.friction;
        script.elasticity = info.surface.elasticity;
        script.set_phys(&info);
        script.hull_planes = info.hull_planes.clone();
        self.model_scripts.insert(name.to_string(), script);
        self.models.insert(name.to_string(), info);
        self.spawn_death_ragdolls();
    }

    /// `CBasePlayer::CreateRagdollEntity` for every death recorded since the last call: the
    /// previous death's body goes, an `hl2mp_ragdoll` of the player's model stands at the
    /// death origin facing the view yaw and every piece carries the player's velocity; it
    /// is a networked ragdoll like `prop_ragdoll`, so the client skins it from the bodies.
    fn spawn_death_ragdolls(&mut self) {
        let pending: Vec<(u32, Ragdoll, f32, Option<u32>)> = self
            .players
            .iter()
            .filter(|(_, p)| !p.alive)
            .filter_map(|(&id, p)| {
                p.ragdoll
                    .clone()
                    .map(|r| (id, r, p.view_angles.y, p.ragdoll_ent))
            })
            .collect();
        for (id, rag, yaw, previous) in pending {
            if let Some(prev) = previous {
                self.remove_prop(prev);
            }
            if !self.models.contains_key(&rag.model) {
                if let Some(loaded) = self.model_loader.as_mut().and_then(|f| f(&rag.model)) {
                    self.register_model(&rag.model, loaded);
                }
            }
            let ent = self.sandbox.restore_prop(
                id,
                &rag.model,
                rag.origin,
                Vec3::new(0.0, yaw, 0.0),
                false,
            );
            if let Some(pose) = self
                .models
                .get(&rag.model)
                .and_then(|m| m.ragdoll.as_ref())
                .and_then(|rd| death_pose(rd, rag.velocity, rag.ducked, rag.tick))
            {
                self.ragdoll_spawn_pose.insert(ent, pose);
            }
            self.sync_physics();
            if let Some(r) = self.ragdoll_bodies.get(&ent) {
                for &b in &r.bodies.clone() {
                    self.physics.set_velocity(b, rag.velocity, Vec3::ZERO);
                }
            }
            if let Some(p) = self.players.get_mut(&id) {
                p.ragdoll = None;
                p.ragdoll_ent = Some(ent);
            }
        }
    }

    /// The player leaves: whatever the physgun held is released, the entry goes; props,
    /// constraints and their ownership stay (the game keeps a leaver's props).
    pub fn remove_player(&mut self, id: u32) -> bool {
        self.players.remove(&id).is_some()
    }

    pub fn add_player(&mut self, id: u32, origin: Vec3, view_angles: Vec3) {
        self.players.insert(id, Player::new(origin, view_angles));
        if let Some(p) = self.players.get_mut(&id) {
            p.joined_tick = self.tick_count;
        }
        if self.request_hook.is_some() {
            self.give_loadout(id);
        }
    }

    /// Props already on the map (owner 0): registered models at given poses, optionally frozen.
    pub fn add_existing_props(&mut self, props: &[(String, Vec3, Vec3, bool)]) {
        let bodies: Vec<PropBody> = props
            .iter()
            .enumerate()
            .map(|(i, (model, pos, angles, _))| PropBody {
                id: i as u32 + 1,
                bone: 0,
                pos: *pos,
                angles: *angles,
                hulls: self.hull_planes.get(model).cloned().unwrap_or_default(),
            })
            .collect();
        let models: Vec<String> = props.iter().map(|p| p.0.clone()).collect();
        self.sandbox.place_existing(0, &bodies, &models);
        for (i, (model, _, _, frozen)) in props.iter().enumerate() {
            self.sandbox.set_frozen(i as u32 + 1, *frozen);
            let health = self.models.get(model).map_or(0, |m| m.prop_data.health);
            self.sandbox.set_health(i as u32 + 1, health);
        }
        self.sync_physics();
    }

    /// `GetShootPos()` and view angles of a player.
    pub fn eye(&self, player: u32) -> Option<(Vec3, Vec3)> {
        let p = self.players.get(&player)?;
        let eye = p.state.origin
            + Vec3::new(
                0.0,
                0.0,
                p.move_override.eye(&self.mover.cfg, p.state.ducked),
            );
        Some((eye, p.view_angles))
    }

    /// Props as the traces see them, at their current physics poses.
    /// The player's hull origin and height for the +use reach and carry clamps.
    fn player_hull(&self, player: u32) -> (Vec3, f32) {
        self.players.get(&player).map_or((Vec3::ZERO, 0.0), |p| {
            let h = if p.state.ducked {
                gm_physics::pickup::DUCK_HULL_HEIGHT
            } else {
                gm_physics::pickup::HULL_HEIGHT
            };
            (p.state.origin, h)
        })
    }

    /// `FindUseEntity`: the prop under the view line within reach, else the first one a 16 u
    /// box finds in 72 u sweeps tilted down from the view (props at the feet).
    /// `FindUseEntity`: the gamemode may replace (or pick) what +use acts on; an id that is
    /// not a live prop / NPC / vehicle falls back to nothing.
    fn find_use_target(&mut self, player: u32, eye: Vec3, view: Vec3) -> Option<u32> {
        let found = self.find_use_entity(player, eye, view);
        match self.ask(Request::FindUse {
            player,
            default: found.unwrap_or(0),
        }) {
            Verdict::Text(t) => {
                let ent = t.trim().parse::<u32>().ok()?;
                let live = self.sandbox.props().iter().any(|p| p.id == ent)
                    || self.npcs.contains_key(&ent)
                    || self.vehicles.contains_key(&ent);
                (ent != 0 && live).then_some(ent)
            }
            _ => found,
        }
    }

    fn find_use_entity(&self, player: u32, eye: Vec3, view: Vec3) -> Option<u32> {
        use gm_physics::pickup::{
            box_sweep_convex, sweep_dirs, view_vectors, within_use_reach, world_convex, SWEEP_HALF,
            SWEEP_LEN,
        };
        let (forward, up) = view_vectors(view.x, view.y);
        let (origin, hull) = self.player_hull(player);
        let bodies = self.trace_bodies();
        if let Some(h) = gm_sandbox::tool_trace(self.collision, &bodies, eye, forward) {
            if let Some(ent) = h.ent {
                // the game's trace stops at the convex's skin, `REST_GAP` short of the hull
                let hit = h.pos - forward * gm_physics::REST_GAP;
                if within_use_reach(eye, hit, origin, hull) {
                    return Some(ent);
                }
            }
        }
        let convexes: Vec<(u32, Vec<WorldConvex>)> = self
            .sandbox
            .props()
            .iter()
            .filter_map(|p| {
                let b = *self.bodies.get(&p.id)?;
                let info = self.models.get(&p.model)?;
                let st = self.physics.state(b);
                let cs = info
                    .hull_planes
                    .iter()
                    .zip(&info.hulls)
                    .map(|(pl, pts)| world_convex(pl, pts, st.rotation, st.position))
                    .collect();
                Some((p.id, cs))
            })
            .collect();
        for dir in sweep_dirs(forward, up) {
            let wall = self
                .collision
                .trace_ray(eye, eye + dir * SWEEP_LEN, gm_collision::MASK_SOLID)
                .fraction
                * SWEEP_LEN;
            let mut best: Option<(f32, u32)> = None;
            for (ent, cs) in &convexes {
                for (planes, aabb) in cs {
                    if let Some(t) =
                        box_sweep_convex(eye, dir, SWEEP_LEN, SWEEP_HALF, planes, *aabb)
                    {
                        if t <= wall && best.is_none_or(|(bt, _)| t < bt) {
                            best = Some((t, *ent));
                        }
                    }
                }
            }
            if let Some((t, ent)) = best {
                if within_use_reach(eye, eye + dir * t, origin, hull) {
                    return Some(ent);
                }
            }
        }
        None
    }

    /// A used prop becomes the player's carry when it is light and small enough
    /// (`CanPickupObject(35, 128)`), moveable (a frozen one is not: `IsMoveable`), nobody
    /// physguns it and `Request::PlayerPickup` allows.
    fn try_pickup(&mut self, player: u32, ent: u32, yaw: f32) {
        let (mass, size) = (gm_physics::pickup::MAX_MASS, gm_physics::pickup::MAX_SIZE);
        self.pickup_with(player, ent, yaw, mass, size);
    }
    /// The carry with the caller's mass and size limits (the physcannon's are its own).
    fn pickup_with(
        &mut self,
        player: u32,
        ent: u32,
        yaw: f32,
        max_mass: f32,
        max_size: f32,
    ) -> bool {
        let Some(model) = self
            .sandbox
            .props()
            .iter()
            .find(|p| p.id == ent && !p.frozen)
            .map(|p| p.model.clone())
        else {
            return false;
        };
        let Some(info) = self.models.get(&model) else {
            return false;
        };
        let size = info.bounds.max - info.bounds.min;
        if info.mass > max_mass || size.max_element() > max_size {
            return false;
        }
        if self.players.values().any(|p| {
            p.held.is_some_and(|(e, _)| e == ent) || p.carry.is_some_and(|(e, _)| e == ent)
        }) {
            return false;
        }
        let Some(b) = self.bodies.get(&ent).copied() else {
            return false;
        };
        if self.ask(Request::PlayerPickup { player, ent }) == Verdict::Cancel {
            return false;
        }
        let mut body_rot = self.physics.state(b).rotation;
        if let Verdict::Text(t) = self.ask(Request::CarryAngles { player, ent }) {
            if let Some([pitch, yaw_a, roll]) = parse_floats::<3>(&t) {
                body_rot = glam::Quat::from_rotation_z(yaw.to_radians())
                    * gm_physics::quat_from_angles(pitch, yaw_a, roll);
            }
        }
        let carry = gm_physics::pickup::Carry::new(body_rot, yaw);
        if let Some(p) = self.players.get_mut(&player) {
            p.carry = Some((ent, carry));
        }
        self.game_events.push(GameEvent::Pickup { player, ent });
        true
    }

    /// Let the carried prop go where it is, at rest (the game drops it with no velocity).
    /// The physcannon's target: the prop the aim hits within `reach` u of the eye.
    fn cannon_target(&self, eye: Vec3, forward: Vec3, reach: f32) -> Option<u32> {
        let bodies = self.trace_bodies();
        let h = gm_sandbox::tool_trace(self.collision, &bodies, eye, forward)?;
        let ent = h.ent?;
        if (h.pos - eye).length() > reach {
            return None;
        }
        self.sandbox
            .props()
            .iter()
            .any(|p| p.id == ent)
            .then_some(ent)
    }
    /// weapon_physcannon.cpp. Primary: the carried prop, else an unfrozen prop within 250 u, is
    /// launched along the aim at `physcannon_maxforce` 1500 u/s (`minforce` 700 above `maxmass`
    /// 250 kg; the game applies the force through vphysics, we set the speed) with the Launch
    /// sound; nothing in reach is a DryFire. Secondary: a carried prop is dropped (Drop,
    /// CloseClaws); a prop within 250 u up to 250 kg is carried (Pickup, OpenClaws), a heavier
    /// one is TooHeavy; while held, a farther prop (to 4096 u) is pulled to the player
    /// (`pullforce` 4000 per think, approximated as 400 / mass u/s per tick) and carried once
    /// within 250 u. The hold loop sound is not played yet.
    fn physcannon(&mut self, player: u32, intent: weapons::CannonIntent, eye: Vec3, ang: Vec3) {
        let forward = gm_sandbox::forward(ang.x, ang.y);
        let carried = self
            .players
            .get(&player)
            .and_then(|p| p.carry.map(|(e, _)| e));
        let snd = |s: &mut Self, name: &str| {
            s.emit_sound(player, format!("Weapon_PhysCannon.{name}"), 1.0);
        };
        let frozen = |s: &Self, ent: u32| s.sandbox.props().iter().any(|p| p.id == ent && p.frozen);
        match intent {
            weapons::CannonIntent::Punt => {
                let target = match carried {
                    Some(e) => {
                        self.drop_carry(player);
                        Some(e)
                    }
                    None => self
                        .cannon_target(eye, forward, weapons::PHYSCANNON_TRACELENGTH)
                        .filter(|e| !frozen(self, *e)),
                };
                let Some(b) = target.and_then(|e| self.bodies.get(&e).copied()) else {
                    snd(self, "DryFire");
                    return;
                };
                let speed = if self.physics.mass(b) > weapons::PHYSCANNON_MAXMASS {
                    weapons::PHYSCANNON_MINFORCE
                } else {
                    weapons::PHYSCANNON_MAXFORCE
                };
                let st = self.physics.state(b);
                self.physics
                    .set_velocity(b, forward * speed, st.angular_velocity);
                if let Some(e) = target {
                    self.game_events
                        .push(GameEvent::GravGunPunt { player, ent: e });
                }
                snd(self, "Launch");
            }
            weapons::CannonIntent::Grab => {
                if carried.is_some() {
                    self.drop_carry(player);
                    snd(self, "Drop");
                    snd(self, "CloseClaws");
                    return;
                }
                let Some(ent) = self.cannon_target(eye, forward, weapons::PHYSCANNON_TRACELENGTH)
                else {
                    return;
                };
                let Some(b) = self.bodies.get(&ent).copied() else {
                    return;
                };
                if self.physics.mass(b) > weapons::PHYSCANNON_MAXMASS {
                    snd(self, "TooHeavy");
                    return;
                }
                if self.pickup_with(player, ent, ang.y, f32::MAX, f32::MAX) {
                    snd(self, "Pickup");
                    snd(self, "OpenClaws");
                }
            }
            weapons::CannonIntent::Pull => {
                if carried.is_some() {
                    return;
                }
                let Some(ent) = self.cannon_target(eye, forward, weapons::PHYSCANNON_PULLRANGE)
                else {
                    return;
                };
                let Some(b) = self.bodies.get(&ent).copied() else {
                    return;
                };
                let mass = self.physics.mass(b);
                if frozen(self, ent) || mass > weapons::PHYSCANNON_MAXMASS {
                    return;
                }
                let st = self.physics.state(b);
                let d = st.position - eye;
                if d.length() <= weapons::PHYSCANNON_TRACELENGTH {
                    if self.pickup_with(player, ent, ang.y, f32::MAX, f32::MAX) {
                        snd(self, "Pickup");
                        snd(self, "OpenClaws");
                    }
                    return;
                }
                let dv =
                    -d.normalize_or_zero() * (weapons::PHYSCANNON_PULLFORCE * 0.1 / mass.max(1.0));
                self.physics
                    .set_velocity(b, st.velocity + dv, st.angular_velocity);
            }
        }
    }
    fn drop_carry(&mut self, player: u32) {
        let Some((ent, _)) = self.players.get_mut(&player).and_then(|p| p.carry.take()) else {
            return;
        };
        if let Some(b) = self.bodies.get(&ent).copied() {
            self.physics.release(b);
            self.physics.set_velocity(b, Vec3::ZERO, Vec3::ZERO);
        }
        self.game_events.push(GameEvent::Drop { player, ent });
    }

    /// Drive the carried prop to its hold point this tick; the carry ends when the player dies,
    /// the prop is gone or a physgun took it.
    fn carry_tick(&mut self, player: u32, eye: Vec3, view: Vec3) {
        let Some((ent, carry)) = self.players.get(&player).and_then(|p| p.carry) else {
            return;
        };
        let alive = self.players.get(&player).is_some_and(|p| p.alive);
        let physgunned = self
            .players
            .values()
            .any(|p| p.held.is_some_and(|(e, _)| e == ent));
        let model = self
            .sandbox
            .props()
            .iter()
            .find(|p| p.id == ent)
            .map(|p| p.model.clone());
        let body = self.bodies.get(&ent).copied();
        let (Some(b), Some(info), true, false) = (
            body,
            model.and_then(|m| self.models.get(&m)),
            alive,
            physgunned,
        ) else {
            self.drop_carry(player);
            return;
        };
        let (origin, hull) = self.player_hull(player);
        let collision = self.collision;
        let brush = |a: Vec3, b: Vec3| collision.trace_ray(a, b, gm_collision::MASK_SOLID).fraction;
        let st = self.physics.state(b);
        let (tp, tr) = carry.target(eye, view, &info.hulls, st.rotation, origin, hull, &brush);
        self.physics.hold(
            b,
            tp,
            tr,
            &gm_physics::pickup::params(gm_core::tick::DEFAULT_TICK_INTERVAL),
        );
    }

    /// The entity's class name: a vehicle's or a world weapon's class, `prop_ragdoll` for a
    /// jointed prop, an NPC's class, `prop_physics` for every other prop, empty when unknown.
    pub fn entity_class(&self, id: u32) -> String {
        if let Some(v) = self.vehicles.get(&id) {
            return v.class.clone();
        }
        if let Some(w) = self.world_weapons.get(&id) {
            return w.clone();
        }
        if let Some(n) = self.npcs.get(&id) {
            return n.class.clone();
        }
        if self.players.values().any(|p| p.ragdoll_ent == Some(id)) {
            return RAGDOLL_CLASS.to_owned();
        }
        if self.ragdoll_bodies.contains_key(&id) {
            return "prop_ragdoll".to_owned();
        }
        if self.sandbox.props().iter().any(|p| p.id == id) {
            return "prop_physics".to_owned();
        }
        String::new()
    }

    /// Linear velocity of a prop's physics body (the pelvis body of a ragdoll); zero otherwise.
    /// Angular velocity (deg/s, world axes), mass (kg), `(linear, angular)` damping and sleep
    /// state of an entity's physics body for script snapshots; zeros when it has no body.
    /// `PhysObj:IsDragEnabled` of an entity's body (false without a body).
    pub fn entity_drag(&self, id: u32) -> bool {
        self.bodies
            .get(&id)
            .is_some_and(|b| self.physics.drag_enabled(*b))
    }

    pub fn entity_phys(&self, id: u32) -> (Vec3, f32, (f32, f32), bool, Vec3) {
        let body = self.bodies.get(&id).copied().or_else(|| {
            self.ragdoll_bodies
                .get(&id)
                .and_then(|r| r.bodies.first().copied())
        });
        match body {
            Some(b) => {
                let st = self.physics.state(b);
                (
                    st.angular_velocity,
                    self.physics.mass(b),
                    self.physics.damping(b),
                    !st.active,
                    self.physics.inertia(b).unwrap_or(Vec3::ZERO),
                )
            }
            None => (Vec3::ZERO, 0.0, (0.0, 0.0), false, Vec3::ZERO),
        }
    }

    /// World pose of a prop or a player (players: origin and view yaw) for parenting.
    pub fn entity_pose(&self, id: u32) -> Option<(Vec3, Quat)> {
        if let Some(p) = self.sandbox.props().iter().find(|p| p.id == id) {
            return Some((p.pos, gm_sandbox::rotation(p.angles)));
        }
        self.players.get(&id).map(|p| {
            (
                p.state.origin,
                gm_sandbox::rotation(Vec3::new(0.0, p.view_angles.y, 0.0)),
            )
        })
    }

    /// `Entity:SetParent`: a prop follows a prop or a player, keeping its current offset in the
    /// parent's space; its own physics is frozen while parented (the game disables it). `None`
    /// unparents and leaves the prop where it is, still frozen.
    pub fn set_parent(&mut self, child: u32, parent: Option<u32>) -> bool {
        let Some(parent) = parent else {
            return self.parents.remove(&child).is_some();
        };
        if parent == child || !self.sandbox.props().iter().any(|p| p.id == child) {
            return false;
        }
        let (Some(pp), Some(cp)) = (self.entity_pose(parent), self.entity_pose(child)) else {
            return false;
        };
        let (local_pos, local_rot) = parent_local(pp, cp);
        self.parents.insert(
            child,
            ParentLink {
                parent,
                local_pos,
                local_rot,
            },
        );
        self.set_prop_frozen(child, true);
        true
    }

    /// Script `SetColor` / `SetMaterial` / `SetRenderMode` / `SetRenderFX`: each `Some` replaces
    /// that part of the prop's render state, the rest is kept.
    pub fn set_prop_render(
        &mut self,
        id: u32,
        material: Option<&str>,
        color: Option<[u8; 4]>,
        mode: Option<u8>,
        fx: Option<u8>,
    ) -> bool {
        let Some(p) = self.sandbox.props().iter().find(|p| p.id == id) else {
            return false;
        };
        let (m, c, mo, f) = (
            material.map_or_else(|| p.material.clone(), |m| m.to_string()),
            color.unwrap_or(p.color),
            mode.unwrap_or(p.render_mode),
            fx.unwrap_or(p.render_fx),
        );
        self.sandbox.set_render(id, &m, c, mo, f);
        true
    }

    /// Script `Player:Flashlight` / `SetFrags` / `SetDeaths`.
    /// `Player:ViewPunch` and friends: `angle` / `vel` replace the view punch spring's angle /
    /// velocity (`add`: the angle is added instead); the spring in gm-move decays it.
    pub fn view_punch(
        &mut self,
        id: u32,
        angle: Option<Vec3>,
        vel: Option<Vec3>,
        add: bool,
    ) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        if let Some(a) = angle {
            p.state.punch = if add { p.state.punch + a } else { a };
        }
        if let Some(v) = vel {
            p.state.punch_vel = v;
        }
        true
    }

    /// `Player:PickupObject`: carry `ent` as a +use press on it would (same reach-free path:
    /// no distance check, the pickup rules and `PlayerPickup` still apply).
    pub fn pickup_object(&mut self, player: u32, ent: u32) -> bool {
        let Some(p) = self.players.get(&player) else {
            return false;
        };
        if p.carry.is_some() || !p.alive {
            return false;
        }
        let yaw = p.view_angles.y;
        self.try_pickup(player, ent, yaw);
        self.players.get(&player).is_some_and(|p| p.carry.is_some())
    }

    /// `Player:PlayStepSound`: one footstep at the player's feet through the footstep rule
    /// (`PlayerFootstep` asked, surface sound by the ground material; the right foot).
    pub fn play_step_sound(&mut self, player: u32, volume: f32) -> bool {
        let Some(p) = self.players.get(&player) else {
            return false;
        };
        let feet = p.state.origin;
        self.footstep(
            player,
            feet,
            gm_move::Step {
                right: true,
                volume: volume.clamp(0.0, 1.0),
            },
            None,
        );
        true
    }

    /// `Player:ExitLadder`: lets go of the ladder the mover has the player on.
    pub fn exit_ladder(&mut self, id: u32) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        p.state.ladder = 0;
        true
    }

    /// `Player:SetEyeAngles`: the next usercmd the server processes for the player runs with
    /// these view angles (the client's own angles return with the command after).
    /// The network layer's view of a player's connection this tick.
    pub fn set_connection(&mut self, id: u32, info: ConnInfo) -> bool {
        match self.players.get_mut(&id) {
            Some(p) => {
                p.conn = info;
                true
            }
            None => false,
        }
    }

    /// Script `Player:SetWalkSpeed` family: see [`MoveOverride::set`].
    pub fn set_move_param(&mut self, id: u32, which: u8, value: Option<f32>) -> bool {
        match self.players.get_mut(&id) {
            Some(p) => p.move_override.set(which, value),
            None => false,
        }
    }

    /// The server's movement tunables.
    pub fn move_cfg(&self) -> &gm_move::MoveConfig {
        &self.mover.cfg
    }

    /// The movement tunables a player actually moves with (server config plus overrides).
    pub fn move_config_of(&self, id: u32) -> Option<gm_move::MoveConfig> {
        self.players
            .get(&id)
            .map(|p| p.move_override.effective(&self.mover.cfg))
    }

    pub fn set_eye_angles(&mut self, id: u32, angles: Vec3) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        p.eye_override = Some(angles);
        p.view_angles = angles;
        true
    }

    /// `Player:EquipSuit` / `RemoveSuit`.
    pub fn set_suit(&mut self, id: u32, on: bool) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        p.suit = on;
        true
    }

    /// `Player:SetLastHitGroup`: read back by `last_hit_group` until the next hit lands.
    pub fn set_last_hit_group(&mut self, id: u32, group: u8) -> bool {
        let len = self.hits.len();
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        p.hit_group_override = Some((len, group));
        true
    }

    /// `Player:ShouldDropWeapon`.
    pub fn set_drop_weapon_on_death(&mut self, id: u32, on: bool) -> bool {
        let Some(p) = self.players.get_mut(&id) else {
            return false;
        };
        p.drop_weapon_on_death = on;
        true
    }

    /// `Player:SetFOV(fov, time)`; `fov <= 0` returns the player to the client's own setting.
    pub fn set_player_fov(&mut self, id: u32, fov: f32, secs: f32) -> bool {
        match self.players.get_mut(&id) {
            Some(p) => {
                p.fov = (fov > 0.0).then_some((fov.clamp(1.0, 179.0), secs.max(0.0)));
                true
            }
            None => false,
        }
    }

    /// `ENTITY:UpdateTransmitState` result on a prop: 0 always, 1 never, anything else PVS.
    pub fn set_transmit_mode(&mut self, ent: u32, mode: u8) -> bool {
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        if mode <= 1 {
            self.transmit_mode.insert(ent, mode);
        } else {
            self.transmit_mode.remove(&ent);
        }
        true
    }

    /// `Some(true)`: always sent, `Some(false)`: never, `None`: by interest / PVS.
    pub fn transmit_override(&self, ent: u32) -> Option<bool> {
        self.transmit_mode.get(&ent).map(|m| *m == 0)
    }

    /// `Entity:SetTransmitWithParent(on)`: the network interest test of this entity follows its
    /// parent's while it is parented (its own radius / PVS otherwise).
    pub fn set_transmit_with_parent(&mut self, ent: u32, on: bool) -> bool {
        if on {
            self.transmit_with_parent.insert(ent);
        } else {
            self.transmit_with_parent.remove(&ent);
        }
        true
    }

    pub fn transmit_with_parent(&self, ent: u32) -> bool {
        self.transmit_with_parent.contains(&ent)
    }

    /// `Entity:SetPreventTransmit(ply, stop)` on a prop.
    pub fn set_prevent_transmit(&mut self, ent: u32, player: u32, prevent: bool) -> bool {
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        if prevent {
            self.prevent_transmit.insert((ent, player));
        } else {
            self.prevent_transmit.remove(&(ent, player));
        }
        true
    }

    pub fn transmit_prevented(&self, ent: u32, player: u32) -> bool {
        self.prevent_transmit.contains(&(ent, player))
    }

    /// The players `ent` is hidden from.
    pub fn prevented_for(&self, ent: u32) -> Vec<u32> {
        self.prevent_transmit
            .range((ent, 0)..=(ent, u32::MAX))
            .map(|(_, p)| *p)
            .collect()
    }

    /// `ENT:SetTrigger(on)`: whether the scripted entity gets touch callbacks.
    pub fn set_sent_trigger(&mut self, ent: u32, on: bool) -> bool {
        match self.sents.get_mut(&ent) {
            Some(s) => {
                s.trigger = on;
                true
            }
            None => false,
        }
    }

    /// `ENT:UseTriggerBounds(on, padding)`: grow the player-touch boxes by `padding`.
    pub fn set_sent_trigger_bounds(&mut self, ent: u32, on: bool, pad: f32) -> bool {
        match self.sents.get_mut(&ent) {
            Some(s) => {
                s.trigger_pad = on.then_some(pad.max(0.0));
                true
            }
            None => false,
        }
    }

    /// `Entity:SetModelScale(scale)` on a prop; 1 clears the override.
    pub fn set_model_scale(&mut self, ent: u32, scale: f32) -> bool {
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        if (scale - 1.0).abs() < 1e-4 || scale <= 0.0 {
            self.model_scales.remove(&ent);
        } else {
            self.model_scales.insert(ent, scale);
        }
        true
    }

    pub fn model_scale(&self, ent: u32) -> f32 {
        self.model_scales.get(&ent).copied().unwrap_or(1.0)
    }

    pub fn set_player_flashlight(&mut self, id: u32, on: bool) -> bool {
        match self.players.get_mut(&id) {
            Some(p) => {
                p.flashlight = on;
                true
            }
            None => false,
        }
    }

    pub fn set_player_score(&mut self, id: u32, frags: Option<u32>, deaths: Option<u32>) -> bool {
        match self.players.get_mut(&id) {
            Some(p) => {
                if let Some(f) = frags {
                    p.frags = f;
                }
                if let Some(d) = deaths {
                    p.deaths = d;
                }
                true
            }
            None => false,
        }
    }

    /// Script `ManipulateBoneScale` / `ManipulateBoneAngles` on a prop or ragdoll: the same
    /// per-bone tables the inflator and bone poser write (identity when unset).
    pub fn set_bone_manip(
        &mut self,
        ent: u32,
        bone: usize,
        scale: Option<Vec3>,
        angles: Option<Vec3>,
        pos: Option<Vec3>,
    ) -> bool {
        let Some(prop) = self.sandbox.props().iter().find(|p| p.id == ent) else {
            return false;
        };
        let bones = self
            .models
            .get(&prop.model)
            .map_or(0, |m| m.script.bones.len());
        if bone >= bones {
            return false;
        }
        if let Some(sc) = scale {
            let v = self
                .bone_scales
                .entry(ent)
                .or_insert_with(|| vec![Vec3::ONE; bones]);
            v.resize(bones, Vec3::ONE);
            v[bone] = sc;
        }
        if let Some(an) = angles {
            let v = self
                .bone_angles
                .entry(ent)
                .or_insert_with(|| vec![Vec3::ZERO; bones]);
            v.resize(bones, Vec3::ZERO);
            v[bone] = an;
        }
        if let Some(po) = pos {
            let v = self
                .bone_positions
                .entry(ent)
                .or_insert_with(|| vec![Vec3::ZERO; bones]);
            v.resize(bones, Vec3::ZERO);
            v[bone] = po;
        }
        true
    }

    /// `Entity:SetSubMaterial`: override one material slot of a prop's model (`None` / empty
    /// clears it; no index clears them all).
    pub fn set_sub_material(
        &mut self,
        ent: u32,
        index: Option<u8>,
        material: Option<&str>,
    ) -> bool {
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        let Some(index) = index else {
            self.sub_materials.remove(&ent);
            return true;
        };
        let v = self.sub_materials.entry(ent).or_default();
        v.retain(|(i, _)| *i != index);
        if let Some(m) = material.filter(|m| !m.is_empty()) {
            v.push((index, m.to_string()));
            v.sort_by_key(|(i, _)| *i);
        }
        if v.is_empty() {
            self.sub_materials.remove(&ent);
        }
        true
    }

    /// `Entity:GetSubMaterial`: the overridden material slots of `prop`.
    pub fn sub_materials(&self, prop: u32) -> Vec<(u8, String)> {
        self.sub_materials.get(&prop).cloned().unwrap_or_default()
    }

    /// Bone position manipulations of `prop`, non-zero ones only.
    pub fn bone_positions(&self, prop: u32) -> Vec<(usize, Vec3)> {
        self.bone_positions
            .get(&prop)
            .map(|v| {
                v.iter()
                    .enumerate()
                    .filter(|(_, a)| a.abs().max_element() > 1e-6)
                    .map(|(i, a)| (i, *a))
                    .collect()
            })
            .unwrap_or_default()
    }

    /// Script `SetFlexWeight` (`Some(id)`) / `SetFlexScale` (`id` None, `value` is the scale).
    pub fn set_flex(&mut self, ent: u32, id: Option<usize>, value: f32) -> bool {
        let Some(prop) = self.sandbox.props().iter().find(|p| p.id == ent) else {
            return false;
        };
        let n = self
            .models
            .get(&prop.model)
            .map_or(0, |m| m.script.flexes.len());
        let st = self
            .flexes
            .entry(ent)
            .or_insert_with(|| (vec![0.0; n], 1.0));
        st.0.resize(n, 0.0);
        match id {
            Some(i) if i < n => st.0[i] = value,
            Some(_) => return false,
            None => st.1 = value,
        }
        true
    }

    /// Script `SetEyeTarget` (`None` clears it); the eyeposer's own setter does the storing.
    pub fn set_script_eye_target(&mut self, ent: u32, target: Option<Vec3>) -> bool {
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        match target {
            Some(t) => self.set_eye_target(ent, t),
            None => {
                self.eye_targets.remove(&ent);
            }
        }
        true
    }

    /// Script `Player:Say`: queued for the net layer, which treats it exactly like a typed line
    /// (`player.chat` hook, then broadcast).
    pub fn say(&mut self, player: u32, text: &str) -> bool {
        if !self.players.contains_key(&player) || text.trim().is_empty() {
            return false;
        }
        self.pending_chat.push((player, text.to_string()));
        true
    }

    /// Script `NPC:Give` / `SelectWeapon` / `DropWeapon` (empty class): the NPC's weapon table
    /// entry; unknown weapon classes are refused.
    /// Script `Entity:SetBloodColor`: NPCs carry their blood colour (the class table's by
    /// default); props and players have none to change.
    pub fn set_blood(&mut self, id: u32, blood: i8) -> bool {
        match self.npcs.get_mut(&id) {
            Some(n) => {
                n.blood = blood;
                true
            }
            None => false,
        }
    }

    /// `Entity:GetBloodColor` of an NPC (game enum, -1 none).
    pub fn blood_color(&self, id: u32) -> Option<i8> {
        self.npcs.get(&id).map(|n| n.blood)
    }

    /// Whether NPC `id` ignores player `p` at `now` (`IgnoreEnemyUntil`).
    pub fn npc_ignores(&self, id: u32, p: u32, now: u64) -> bool {
        self.npcs
            .get(&id)
            .is_some_and(|n| n.ignore.iter().any(|(pl, t)| *pl == p && *t > now))
    }

    /// Script `NPC:IgnoreEnemyUntil`: the NPC drops `player` as its target and does not pick
    /// it again before tick `until`.
    pub fn npc_ignore_until(&mut self, id: u32, player: u32, until: u64) -> bool {
        let Some(n) = self.npcs.get_mut(&id) else {
            return false;
        };
        n.ignore.retain(|(pl, _)| *pl != player);
        n.ignore.push((player, until));
        if n.target == Some(player) {
            n.target = None;
            n.chase = None;
        }
        true
    }

    /// Whether a sandbox prop is the physics body of an NPC (not a prop of its own).
    pub fn is_npc_body(&self, prop: u32) -> bool {
        self.npcs.values().any(|n| n.body == Some(prop))
    }

    /// The player an NPC currently targets.
    pub fn npc_current_target(&self, id: u32) -> Option<u32> {
        self.npcs.get(&id).and_then(|n| n.target)
    }

    /// Script `NPC:SetMaxLookDistance`: the target search range of one NPC.
    pub fn set_npc_sight(&mut self, id: u32, dist: f32) -> bool {
        match self.npcs.get_mut(&id) {
            Some(n) => {
                n.sight = dist.max(0.0);
                true
            }
            None => false,
        }
    }

    /// `NPC:GetMaxLookDistance`.
    pub fn npc_sight(&self, id: u32) -> Option<f32> {
        self.npcs.get(&id).map(|n| n.sight)
    }

    /// Script `NPC:PickupWeapon`: the NPC takes a world weapon (its class must be one it can
    /// carry) and the world entity is removed, as on a player touch pickup.
    pub fn npc_pickup_weapon(&mut self, id: u32, ent: u32) -> bool {
        let Some(class) = self.world_weapons.get(&ent).cloned() else {
            return false;
        };
        if !self.set_npc_weapon(id, &class) {
            return false;
        }
        self.world_weapons.remove(&ent);
        self.remove_prop(ent);
        true
    }

    pub fn set_npc_weapon(&mut self, id: u32, class: &str) -> bool {
        if !class.is_empty() && npc_weapon_shot_in(class, &self.scripted_weapons).is_none() {
            return false;
        }
        let Some(n) = self.npcs.get_mut(&id) else {
            return false;
        };
        let old = std::mem::replace(&mut n.weapon, class.to_string());
        let (pos, yaw, alive) = (n.pos, n.angles.y, n.dead_at.is_none());
        let crouched = npc_sequence_crouched(&n.sequence);
        // `NPC:DropWeapon` (empty class) drops the carried one as a world weapon, as the death path does
        if class.is_empty() && alive && !old.is_empty() {
            self.drop_npc_weapon(0, &old, pos, yaw, crouched);
        }
        true
    }

    pub fn entity_parent(&self, id: u32) -> u32 {
        self.parents.get(&id).map_or(0, |l| l.parent)
    }

    fn follow_parents(&mut self) {
        let links: Vec<(u32, ParentLink)> = self.parents.iter().map(|(c, l)| (*c, *l)).collect();
        for (child, link) in links {
            let (Some(pp), Some(_)) = (self.entity_pose(link.parent), self.entity_pose(child))
            else {
                self.parents.remove(&child);
                continue;
            };
            let (pos, rot) = parent_world(pp, (link.local_pos, link.local_rot));
            self.teleport_prop(child, pos, gm_sandbox::angles_of(rot));
        }
    }

    pub fn entity_velocity(&self, id: u32) -> Vec3 {
        if let Some(&b) = self.bodies.get(&id) {
            return self.physics.state(b).velocity;
        }
        if let Some(r) = self.ragdoll_bodies.get(&id) {
            if let Some(&b) = r.bodies.first() {
                return self.physics.state(b).velocity;
            }
        }
        Vec3::ZERO
    }

    /// The player an entity is registered to in the sandbox cleanup lists (NPCs, vehicles,
    /// props, ...), 0 when none.
    pub fn entity_owner(&self, id: u32) -> u32 {
        if let Some(p) = self.sandbox.props().iter().find(|p| p.id == id) {
            if p.owner != 0 {
                return p.owner;
            }
        }
        self.sandbox.cleanup_owner(id).unwrap_or(0)
    }

    pub fn trace_bodies(&self) -> Vec<PropBody> {
        let mut out = Vec::new();
        for p in self.sandbox.props() {
            if let (Some(r), Some(rd)) = (
                self.ragdoll_bodies.get(&p.id),
                self.models.get(&p.model).and_then(|m| m.ragdoll.as_ref()),
            ) {
                for (i, (&b, solid)) in r.bodies.iter().zip(&rd.solids).enumerate() {
                    let st = self.physics.state(b);
                    let (pitch, yaw, roll) = gm_physics::angles_from_quat(st.rotation);
                    out.push(PropBody {
                        id: p.id,
                        bone: i as u32,
                        pos: st.position,
                        angles: Vec3::new(pitch, yaw, roll),
                        hulls: solid.planes.clone(),
                    });
                }
                continue;
            }
            let Some(hulls) = self.hull_planes.get(&p.model).cloned() else {
                continue;
            };
            out.push(PropBody {
                id: p.id,
                bone: 0,
                pos: p.pos,
                angles: p.angles,
                hulls,
            });
        }
        // NPCs: the hull box (the game's trace hits their bounding box)
        for (&id, n) in &self.npcs {
            let (mins, maxs) = (n.mins, n.maxs);
            let hull = vec![
                (Vec3::X, maxs.x),
                (Vec3::NEG_X, -mins.x),
                (Vec3::Y, maxs.y),
                (Vec3::NEG_Y, -mins.y),
                (Vec3::Z, maxs.z),
                (Vec3::NEG_Z, -mins.z),
            ];
            out.push(PropBody {
                id,
                bone: 0,
                pos: n.pos,
                angles: Vec3::new(0.0, n.angles.y, 0.0),
                hulls: vec![hull],
            });
        }
        out
    }

    /// The body the physgun acts on: a ragdoll's `bone` physics object, else the prop body.
    fn part_body(&self, ent: u32, bone: u32) -> Option<BodyHandle> {
        match self.ragdoll_bodies.get(&ent) {
            Some(r) => r.bodies.get(bone as usize).copied(),
            None => self.bodies.get(&ent).copied(),
        }
    }

    /// `PhysObj:IsMoveable()` false on a ragdoll part (a prop answers through `Prop::frozen`).
    fn part_frozen(&self, ent: u32, bone: u32) -> bool {
        self.ragdoll_bodies
            .get(&ent)
            .and_then(|r| r.frozen.get(bone as usize).copied())
            .unwrap_or(false)
    }

    /// `gm_spawn <model>` by a player.
    /// The spawn menu's Weapons and Entities tabs (`list.Get("Weapon")` /
    /// `list.Get("SpawnableEntities")`): the HL2 weapons `lua/autorun/game_hl2.lua` makes
    /// spawnable that this server implements, the scripted weapons, and the scripted entities.
    /// Names starting with `#` are localisation keys (`entities.properties`).
    /// `ENT:SetOverlayText`: the world tip of scripted entity `ent` (empty clears it).
    pub fn set_overlay_text(&mut self, ent: u32, text: &str) -> bool {
        let Some(s) = self.sents.get_mut(&ent) else {
            return false;
        };
        if s.overlay != text {
            s.overlay = text.to_string();
            self.overlay_version = self.overlay_version.wrapping_add(1);
        }
        true
    }

    /// The classes of the scripted, HL2 and sandbox entities by id (`ServerMsg::EntityClasses`):
    /// what the clients render specially (`sent_ball`'s sprite).
    pub fn entity_classes(&self) -> Vec<(u32, String)> {
        let mut out: Vec<(u32, String)> = self
            .sents
            .iter()
            .map(|(id, s)| (*id, s.class.clone()))
            .chain(self.hl2_items.iter().map(|(id, c)| (*id, c.clone())))
            .chain(self.sandbox_sents.iter().map(|(id, c)| (*id, c.clone())))
            .collect();
        out.sort_unstable_by_key(|(id, _)| *id);
        out
    }

    /// `sent_ball` `PhysicsCollide`: an impact faster than 60 u/s pops the balloon sound
    /// (volume `speed / 150`) and the ball keeps 90 % of the greater of its old speed and the
    /// approach speed along its new direction - it never settles.
    fn ball_bounce(&mut self, ent: u32, speed: f32) {
        let Some(st) = self.prop_state(ent) else {
            return;
        };
        let Some(body) = self.bodies.get(&ent).copied() else {
            return;
        };
        let last = st.velocity.length().max(speed);
        let dir = st.velocity.normalize_or_zero();
        self.physics
            .set_velocity(body, dir * last * 0.9, st.angular_velocity);
        let volume = (speed / 150.0).clamp(0.0, 1.0);
        // pitch 32 + 128 - size, +-10 at random: small balls squeak, big ones thud
        let size = (self.model_scales.get(&ent).copied().unwrap_or(1.0) * 32.0).clamp(16.0, 48.0);
        let pitch = 32.0 + 128.0 - size + self.next_random() * 20.0 - 10.0;
        self.emit_sound_pitch(ent, "garrysmod/balloon_pop_cute.wav".into(), volume, pitch);
    }

    /// The editor entities' vars by id (`ServerMsg::EntityEdits`), keys sorted.
    pub fn entity_edits(&self) -> Vec<(u32, Vec<(String, String)>)> {
        self.editor_vars
            .iter()
            .map(|(id, vars)| {
                (
                    *id,
                    vars.iter().map(|(k, v)| (k.clone(), v.clone())).collect(),
                )
            })
            .collect()
    }

    /// `editentity`: one row of an editor entity's property sheet changed; the value is
    /// clamped to the schema (numbers to their range, colour channels to 0..255, flags to
    /// 0 / 1) and reaches every client with the next `EntityEdits`.
    pub fn edit_entity(&mut self, player: u32, ent: u32, key: &str, value: &str) -> bool {
        if !self.players.get(&player).is_some_and(|p| p.alive) {
            return false;
        }
        let Some(schema) = self.sandbox_sents.get(&ent).and_then(|c| editor_schema(c)) else {
            return false;
        };
        let Some(setting) = schema
            .iter()
            .find(|s| s.name == key || s.options.iter().any(|(n, _)| n == key))
        else {
            return false;
        };
        let value = match setting.kind {
            ToolSettingKind::Number if setting.name == key => {
                let Ok(v) = value.trim().parse::<f32>() else {
                    return false;
                };
                format!("{}", v.clamp(setting.min, setting.max))
            }
            ToolSettingKind::Bool => if matches!(value.trim(), "1" | "true" | "on") {
                "1"
            } else {
                "0"
            }
            .to_string(),
            ToolSettingKind::Color => {
                let Ok(v) = value.trim().parse::<f32>() else {
                    return false;
                };
                format!("{:.0}", v.clamp(0.0, 255.0))
            }
            _ => return false,
        };
        let Some(vars) = self.editor_vars.get_mut(&ent) else {
            return false;
        };
        vars.insert(key.to_string(), value.clone());
        self.game_events.push(GameEvent::EntityEdited {
            player,
            ent,
            key: key.to_string(),
            value,
        });
        true
    }

    /// Every scripted entity with a non-empty overlay text, by id.
    pub fn overlays(&self) -> Vec<(u32, String)> {
        let mut out: Vec<(u32, String)> = self
            .sents
            .iter()
            .filter(|(_, s)| !s.overlay.is_empty())
            .map(|(id, s)| (*id, s.overlay.clone()))
            .collect();
        // gmod_button `GetOverlayText`: the label without backslashes, 20 chars, in quotes
        for (id, d) in self.sandbox.devices() {
            if let gm_sandbox::Device::Button { description, .. } = d {
                let label: String = description.replace('\\', "").chars().take(20).collect();
                if !label.is_empty() {
                    out.push((*id, format!("\"{label}\"")));
                }
            }
        }
        out.sort_by_key(|(id, _)| *id);
        out
    }

    pub fn content_lists(&self) -> (Vec<ContentEntry>, Vec<ContentEntry>) {
        let mut weapons: Vec<ContentEntry> = HL2_SPAWNABLE_WEAPONS
            .iter()
            .filter(|c| weapons::def(c).is_some())
            .map(|c| ContentEntry {
                class: c.to_string(),
                name: format!("#{c}"),
                category: "Half-Life 2".into(),
            })
            .collect();
        weapons.extend(self.scripted_weapons.iter().map(|w| ContentEntry {
            class: w.class.clone(),
            name: w.print_name.clone(),
            category: "#spawnmenu.category.other".into(),
        }));
        let mut entities: Vec<ContentEntry> = HL2_SPAWNABLE_ENTITIES
            .iter()
            .map(|(c, _, _)| ContentEntry {
                class: c.to_string(),
                name: format!("#{c}"),
                category: "Half-Life 2".into(),
            })
            .collect();
        entities.extend(
            SANDBOX_SPAWNABLE_ENTITIES
                .iter()
                .map(|(c, _, _, cat)| ContentEntry {
                    class: c.to_string(),
                    name: format!("#{c}"),
                    category: cat.to_string(),
                }),
        );
        entities.extend(self.scripted_entities.iter().map(|e| {
            ContentEntry {
                class: e.class.clone(),
                name: e.print_name.clone().unwrap_or_else(|| e.class.clone()),
                category: e
                    .category
                    .clone()
                    .unwrap_or_else(|| "#spawnmenu.category.other".into()),
            }
        }));
        (weapons, entities)
    }

    /// `gm_giveswep`: a live player gets a spawnable weapon (given if not carried) and
    /// switches to it.
    pub fn give_weapon_cmd(&mut self, player: u32, class: &str) -> bool {
        if !self.players.get(&player).is_some_and(|p| p.alive) {
            return false;
        }
        if !self.content_lists().0.iter().any(|w| w.class == class) {
            return false;
        }
        if self.ask(Request::Spawn {
            player,
            kind: "giveswep",
            name: class.to_string(),
        }) == Verdict::Cancel
        {
            return false;
        }
        self.give_weapon(player, class)
    }

    /// `gm_spawnsent` for a scripted entity: 16 units off the surface the player looks at,
    /// counted and cleaned up as `sents` (`sbox_maxsents`), undoable as `SENT`.
    pub fn spawn_sent(&mut self, player: u32, class: &str) -> Option<u32> {
        if !self.players.get(&player).is_some_and(|p| p.alive) {
            return None;
        }
        if let Some((_, model, offset)) = HL2_SPAWNABLE_ENTITIES.iter().find(|e| e.0 == class) {
            return self.spawn_hl2_item(player, class, model, *offset);
        }
        if let Some((_, model, offset, _)) =
            SANDBOX_SPAWNABLE_ENTITIES.iter().find(|e| e.0 == class)
        {
            let id = self.spawn_hl2_item(player, class, model, *offset)?;
            self.sandbox_sents.insert(id, class.to_string());
            if let Some(schema) = editor_schema(class) {
                self.editor_vars.insert(id, editor_defaults(&schema));
            }
            if class == "sent_ball" {
                // sent_ball.lua SpawnFunction: a random 16..48 size and colour
                let size = 16.0 + self.next_random() * 32.0;
                self.set_model_scale(id, size / 32.0);
                let c = [
                    (self.next_random() * 255.0) as u8,
                    (self.next_random() * 255.0) as u8,
                    (self.next_random() * 255.0) as u8,
                    255,
                ];
                self.sandbox.set_render(id, "", c, 0, 0);
            }
            return Some(id);
        }
        let def = self
            .scripted_entities
            .iter()
            .find(|e| e.class == class)?
            .clone();
        if self.ask(Request::Spawn {
            player,
            kind: "sent",
            name: class.to_string(),
        }) == Verdict::Cancel
        {
            return None;
        }
        let hit = self.tool_hit(player)?;
        let pos = hit.pos + hit.normal * 16.0;
        // counted / cleaned up as a sent only (`sbox_maxsents`), never as a prop
        let id = self.script_spawn_entity(player, class, pos, Vec3::ZERO, false, None)?;
        self.game_events.push(GameEvent::Spawned {
            player,
            ent: id,
            kind: "sent",
            name: class.to_string(),
        });
        let name = def.print_name.clone().unwrap_or_else(|| class.to_string());
        self.push_undo(
            player,
            "SENT",
            format!("Scripted Entity ({class})"),
            Some(format!("Undone {name}")),
            vec![id],
        );
        Some(id)
    }

    /// An HL2 entity of the Entities tab (`Spawn_SENT` for an engine class): a prop of the
    /// entity's model `NormalOffset` u along the hit normal from the eye trace, counted and
    /// cleaned up as a sent, undoable as `SENT` with the class's localised name.
    fn spawn_hl2_item(
        &mut self,
        player: u32,
        class: &str,
        model: &str,
        offset: f32,
    ) -> Option<u32> {
        if self.ask(Request::Spawn {
            player,
            kind: "sent",
            name: class.to_string(),
        }) == Verdict::Cancel
        {
            return None;
        }
        let hit = self.tool_hit(player)?;
        let pos = hit.pos + hit.normal * offset;
        if !self.models.contains_key(model) {
            let loaded = self.model_loader.as_mut().and_then(|f| f(model))?;
            self.register_model(model, loaded);
        }
        let id = self
            .sandbox
            .restore_prop(player, model, pos, Vec3::ZERO, false);
        self.sandbox.add_cleanup(player, "sents", id);
        if hl2_item_pickup(class).is_some() {
            self.hl2_items.insert(id, class.to_string());
        }
        if let Some(c) = hl2_charger(class) {
            self.chargers.insert(id, c);
        }
        self.sync_physics();
        self.game_events.push(GameEvent::Spawned {
            player,
            ent: id,
            kind: "sent",
            name: class.to_string(),
        });
        self.push_undo(
            player,
            "SENT",
            format!("Scripted Entity ({class})"),
            Some(format!("Undone #{class}")),
            vec![id],
        );
        Some(id)
    }
    /// `Spawn_Weapon` (`gm_spawnswep`, the Weapons tab's middle click, creator type 3): the
    /// weapon entity lands 32 u along the hit normal from the player's eye trace (pulled back to
    /// halfway when that point is outside the world), no angles, physics on; undo "SWEP" with
    /// `#undo.generic.weapon (<print name>)`, cleanup as a sent without counting (measured:
    /// `server_weapon_spawn`). Unknown classes spawn nothing and leave no undo entry.
    pub fn spawn_weapon(&mut self, player: u32, class: &str) -> Option<u32> {
        if !self.players.get(&player).is_some_and(|p| p.alive) {
            return None;
        }
        if self.ask(Request::Spawn {
            player,
            kind: "weapon",
            name: class.to_string(),
        }) == Verdict::Cancel
        {
            return None;
        }
        let (model, print_name) = match self.scripted_weapons.iter().find(|w| w.class == class) {
            Some(sw) => (sw.world_model.clone(), sw.print_name.clone()),
            None => {
                if !HL2_SPAWNABLE_WEAPONS.contains(&class) {
                    return None;
                }
                (hl2_world_model(class)?.to_string(), format!("#{class}"))
            }
        };
        if model.is_empty() {
            return None;
        }
        let hit = self.tool_hit(player)?;
        let mut pos = hit.pos + hit.normal * 32.0;
        let oob = self
            .collision
            .trace_ray(hit.pos, pos, gm_collision::MASK_SOLID);
        if oob.fraction < 1.0 {
            pos = oob.end + oob.normal * (hit.pos.distance(oob.end) / 2.0);
        }
        if !self.models.contains_key(&model) {
            let loaded = self.model_loader.as_mut().and_then(|f| f(&model))?;
            self.register_model(&model, loaded);
        }
        let id = self.place_world_weapon(player, class, &model, &print_name, pos);
        self.game_events.push(GameEvent::Spawned {
            player,
            ent: id,
            kind: "weapon",
            name: class.to_string(),
        });
        Some(id)
    }

    fn place_world_weapon(
        &mut self,
        player: u32,
        class: &str,
        model: &str,
        print_name: &str,
        pos: Vec3,
    ) -> u32 {
        let id = self
            .sandbox
            .restore_prop(player, model, pos, Vec3::ZERO, false);
        self.sandbox.add_cleanup(player, "sents", id);
        self.sync_physics();
        self.world_weapons.insert(id, class.to_string());
        self.push_undo(
            player,
            "SWEP",
            format!("#undo.generic.weapon ({print_name})"),
            Some(format!("Undone {print_name}")),
            vec![id],
        );
        id
    }

    /// Script `Player:DropWeapon` / `DropNamedWeapon`: strips the weapon (active one when
    /// `class` is `None`) and places it as a world weapon 32 u in front of the player's origin.
    pub fn drop_weapon(&mut self, player: u32, class: Option<&str>) -> Option<u32> {
        let p = self.players.get(&player).filter(|p| p.alive)?;
        let class = class
            .map(str::to_string)
            .unwrap_or_else(|| p.active_weapon.clone());
        if class.is_empty() || !self.strip_weapon(player, Some(&class)) {
            return None;
        }
        let p = self.players.get(&player)?;
        let yaw = p.view_angles.y.to_radians();
        let pos = p.state.origin + Vec3::new(yaw.cos(), yaw.sin(), 0.0) * 32.0 + Vec3::Z * 16.0;
        let (model, print_name) = match self.scripted_weapons.iter().find(|w| w.class == class) {
            Some(sw) => (sw.world_model.clone(), sw.print_name.clone()),
            None => (hl2_world_model(&class)?.to_string(), format!("#{class}")),
        };
        if model.is_empty() {
            return None;
        }
        if !self.models.contains_key(&model) {
            let loaded = self.model_loader.as_mut().and_then(|f| f(&model))?;
            self.register_model(&model, loaded);
        }
        let ent = self.place_world_weapon(player, &class, &model, &print_name, pos);
        self.game_events.push(GameEvent::WeaponDrop {
            player,
            class: class.clone(),
            ent,
        });
        Some(ent)
    }

    /// Script `Player:DropObject`: lets go of whatever the physgun / gravity gun holds.
    pub fn drop_object(&mut self, player: u32) -> bool {
        match self.players.get_mut(&player) {
            Some(p) if p.held.is_some() => {
                p.held = None;
                true
            }
            _ => false,
        }
    }

    pub fn set_no_target(&mut self, player: u32, on: bool) -> bool {
        match self.players.get_mut(&player) {
            Some(p) => {
                p.no_target = on;
                true
            }
            None => false,
        }
    }

    pub fn set_player_colors(
        &mut self,
        player: u32,
        body: Option<Vec3>,
        weapon: Option<Vec3>,
    ) -> bool {
        match self.players.get_mut(&player) {
            Some(p) => {
                if let Some(c) = body {
                    p.player_color = c;
                }
                if let Some(c) = weapon {
                    p.weapon_color = c;
                }
                true
            }
            None => false,
        }
    }

    /// Script `Entity:ForcePlayerDrop`: every player holding the prop lets go of it.
    pub fn force_player_drop(&mut self, ent: u32) -> bool {
        let mut any = false;
        for p in self.players.values_mut() {
            if p.held.as_ref().is_some_and(|(h, _)| *h == ent) {
                p.held = None;
                any = true;
            }
        }
        any
    }

    /// `Player:LastHitGroup`: hit group of the last recorded hit on the player (0 = generic).
    pub fn last_hit_group(&self, player: u32) -> u8 {
        if let Some((len, g)) = self.players.get(&player).and_then(|p| p.hit_group_override) {
            if len == self.hits.len() {
                return g;
            }
        }
        self.hits
            .iter()
            .rev()
            .find(|h| h.target == player)
            .and_then(|h| h.hitgroup)
            .unwrap_or(0)
    }

    pub fn set_locked(&mut self, player: u32, locked: bool) -> bool {
        match self.players.get_mut(&player) {
            Some(p) => {
                p.locked = locked;
                true
            }
            None => false,
        }
    }

    /// The surface a prop's body uses: the script override, else the model's PHY surface.
    pub fn entity_surface(&self, id: u32) -> (f32, f32) {
        if let Some(s) = self.surface_overrides.get(&id) {
            return *s;
        }
        self.sandbox
            .props()
            .iter()
            .find(|p| p.id == id)
            .and_then(|p| self.model_scripts.get(&p.model))
            .map(|m| (m.friction, m.elasticity))
            .unwrap_or((0.8, 0.25))
    }

    /// Script `Entity:SetFriction / SetElasticity`: the body gets the new surface right away.
    pub fn set_entity_surface(
        &mut self,
        id: u32,
        friction: Option<f32>,
        elasticity: Option<f32>,
    ) -> bool {
        let Some(body) = self.body_of(id) else {
            return false;
        };
        let (f, e) = self.entity_surface(id);
        let next = (
            friction.unwrap_or(f).max(0.0),
            elasticity.unwrap_or(e).max(0.0),
        );
        self.surface_overrides.insert(id, next);
        self.physics.set_surface(
            body,
            gm_physics::Surface {
                friction: next.0,
                elasticity: next.1,
            },
        );
        true
    }

    pub fn set_max_armor(&mut self, player: u32, max: i32) -> bool {
        match self.players.get_mut(&player) {
            Some(p) => {
                p.max_armor = max.max(0);
                p.armor = p.armor.min(p.max_armor);
                true
            }
            None => false,
        }
    }

    /// `Spawn_Vehicle` (`gm_spawnvehicle <key>`, creator type 2): the list entry's model as a
    /// physics prop at `HitPos + HitNormal * Offset`, facing the player (yaw + 180); counted and
    /// cleaned up as `vehicles` (`sbox_maxvehicles` 4), undo "Vehicle".
    pub fn spawn_vehicle(&mut self, player: u32, key: &str) -> Option<u32> {
        if !self.players.get(&player).is_some_and(|p| p.alive) {
            return None;
        }
        if self.ask(Request::Spawn {
            player,
            kind: "vehicle",
            name: key.to_string(),
        }) == Verdict::Cancel
        {
            return None;
        }
        let def = *vehicle_def(key)?;
        let mut events = Vec::new();
        if !self.check_limit(player, "vehicles", &mut events) {
            self.events.extend(events);
            return None;
        }
        let hit = self.tool_hit(player)?;
        let yaw = self
            .players
            .get(&player)
            .map(|p| p.view_angles.y)
            .unwrap_or(0.0);
        if !self.models.contains_key(def.model) {
            let loaded = self.model_loader.as_mut().and_then(|f| f(def.model))?;
            self.register_model(def.model, loaded);
        }
        let pos = hit.pos + hit.normal * def.offset;
        let id = self.sandbox.restore_prop(
            player,
            def.model,
            pos,
            Vec3::new(0.0, yaw + 180.0, 0.0),
            false,
        );
        self.sandbox.add_count(player, "vehicles", id);
        self.sandbox.add_cleanup(player, "vehicles", id);
        self.sync_physics();
        let health = def.health.unwrap_or_else(|| {
            self.models
                .get(def.model)
                .map(|m| m.prop_data.health)
                .unwrap_or(0)
        });
        self.vehicles.insert(
            id,
            Vehicle {
                controls: VehicleControls::default(),
                tuning: VehicleTuning::default(),
                key: def.key.to_string(),
                class: def.class.to_string(),
                model: def.model.to_string(),
                health,
                // measured: pods / chairs read GetMaxHealth 1 with 0 health, the cars 0
                max_health: if def.class == "prop_vehicle_prisoner_pod" && health == 0 {
                    1
                } else {
                    health
                },
                driver: None,
                wheels: Vec::new(),
                add_gravity: 0.0,
                mass: 0.0,
            },
        );
        self.setup_car(id, key);
        let name = vehicle_name(&def);
        self.push_undo(
            player,
            "Vehicle",
            format!("#undo.generic.vehicle ({name})"),
            Some(format!("Undone {name}")),
            vec![id],
        );
        self.game_events.push(GameEvent::Spawned {
            player,
            ent: id,
            kind: "vehicle",
            name: key.to_string(),
        });
        self.events.extend(events);
        Some(id)
    }

    /// Pose of a vehicle's attachment in the world (model space through the prop's transform).
    fn vehicle_attachment(&self, veh: u32, name: &str) -> Option<(Vec3, Vec3)> {
        let prop = self.sandbox.props().iter().find(|p| p.id == veh)?;
        let att = self
            .models
            .get(&prop.model)?
            .attachments
            .iter()
            .find(|a| a.name == name)?;
        let rot = gm_sandbox::rotation(prop.angles);
        Some((prop.pos + rot * att.pos, rot * att.forward))
    }

    /// `Player:EnterVehicle`: the body moves to the seat (`vehicle_feet_passenger0`, else the
    /// vehicle's origin), takes the vehicle's angles and stops moving on its own (MOVETYPE_NOCLIP
    /// in the game); a vehicle seats one player.
    pub fn enter_vehicle(&mut self, player: u32, veh: u32) -> bool {
        let Some(v) = self.vehicles.get(&veh) else {
            return false;
        };
        if v.driver.is_some()
            || self
                .players
                .get(&player)
                .is_none_or(|p| !p.alive || p.seat.is_some())
        {
            return false;
        }
        let Some(prop) = self.sandbox.props().iter().find(|p| p.id == veh).cloned() else {
            return false;
        };
        let seat = self
            .vehicle_attachment(veh, "vehicle_feet_passenger0")
            .map(|a| a.0)
            .unwrap_or(prop.pos);
        self.drop_carry(player);
        if let Some(p) = self.players.get_mut(&player) {
            p.seat = Some(veh);
            p.state.origin = seat;
            p.state.game_moved = true;
            p.state.velocity = Vec3::ZERO;
            p.view_angles = prop.angles;
        }
        if let Some(v) = self.vehicles.get_mut(&veh) {
            v.driver = Some(player);
            v.controls.engine_on = true;
        }
        self.game_events.push(GameEvent::EnterVehicle {
            player,
            vehicle: veh,
        });
        true
    }

    /// `Player:ExitVehicle` (measured): a pod / chair puts the player 100 u to the vehicle's
    /// left and 12 u up facing that way (yaw + 90), a jeep 90 u behind and 11.5 u up facing
    /// away from it; the body then falls to the floor.
    /// +use on a vehicle: the addon runtime may refuse (`CanPlayerEnterVehicle`); scripted
    /// `Player:EnterVehicle` goes through [`Self::enter_vehicle`] unasked, like the game.
    pub fn use_enter_vehicle(&mut self, player: u32, veh: u32) -> bool {
        if self.ask(Request::EnterVehicle {
            player,
            vehicle: veh,
        }) == Verdict::Cancel
        {
            return false;
        }
        self.enter_vehicle(player, veh)
    }

    /// +use while seated: the addon runtime may refuse (`CanExitVehicle`).
    pub fn use_exit_vehicle(&mut self, player: u32) -> bool {
        let Some(veh) = self.players.get(&player).and_then(|p| p.seat) else {
            return false;
        };
        if self.ask(Request::ExitVehicle {
            player,
            vehicle: veh,
        }) == Verdict::Cancel
        {
            return false;
        }
        self.exit_vehicle(player)
    }

    /// `Vehicle:SetThrottle` / `SetSteering` / `SetHandbrake`: driver inputs of a vehicle, kept
    /// until changed (`None` leaves one as it is). False for an unknown vehicle.
    pub fn set_vehicle_controls(
        &mut self,
        veh: u32,
        throttle: Option<f32>,
        steer: Option<f32>,
        handbrake: Option<bool>,
    ) -> bool {
        let Some(v) = self.vehicles.get_mut(&veh) else {
            return false;
        };
        if let Some(t) = throttle {
            v.controls.throttle = t.clamp(-1.0, 1.0);
        }
        if let Some(st) = steer {
            v.controls.steer = st.clamp(-1.0, 1.0);
        }
        if let Some(h) = handbrake {
            v.controls.handbrake = h;
        }
        true
    }

    /// `Vehicle:SetBoost`: the turbo, 0..1, kept until changed.
    pub fn set_vehicle_boost(&mut self, veh: u32, boost: f32) -> bool {
        let Some(v) = self.vehicles.get_mut(&veh) else {
            return false;
        };
        v.controls.boost = boost.clamp(0.0, 1.0);
        true
    }

    /// Script tuning of a vehicle; `Some` fields are applied, non-finite values ignored.
    #[allow(clippy::too_many_arguments)]
    pub fn set_vehicle_tuning(
        &mut self,
        veh: u32,
        max_throttle: Option<f32>,
        max_rev_throttle: Option<f32>,
        deg_slow: Option<f32>,
        deg_fast: Option<f32>,
        tyre_mu: Option<f32>,
        max_fwd: Option<f32>,
        max_rev: Option<f32>,
        rest: Option<f32>,
    ) -> bool {
        let Some(v) = self.vehicles.get_mut(&veh) else {
            return false;
        };
        let t = &mut v.tuning;
        let ok = |x: f32| x.is_finite() && x >= 0.0;
        if let Some(x) = max_throttle.filter(|x| ok(*x)) {
            t.max_throttle = x.min(1.0);
        }
        if let Some(x) = max_rev_throttle.filter(|x| ok(*x)) {
            t.max_rev_throttle = x.min(1.0);
        }
        if let Some(x) = deg_slow.filter(|x| ok(*x)) {
            t.deg_slow = Some(x);
        }
        if let Some(x) = deg_fast.filter(|x| ok(*x)) {
            t.deg_fast = Some(x);
        }
        if let Some(x) = tyre_mu.filter(|x| ok(*x)) {
            t.tyre_mu = Some(x);
        }
        if let Some(x) = max_fwd.filter(|x| ok(*x)) {
            t.max_fwd = Some(x);
        }
        if let Some(x) = max_rev.filter(|x| ok(*x)) {
            t.max_rev = Some(x);
        }
        if let Some(x) = rest.filter(|x| ok(*x)) {
            t.rest = Some(x);
        }
        true
    }

    /// Suspension constants of one raycast wheel (`SetVehicleParams` axles); `Some` fields applied.
    pub fn set_vehicle_wheel(
        &mut self,
        veh: u32,
        idx: usize,
        spring: Option<f32>,
        damping: Option<f32>,
        damping_compression: Option<f32>,
    ) -> bool {
        let Some(w) = self
            .vehicles
            .get_mut(&veh)
            .and_then(|v| v.wheels.get_mut(idx))
        else {
            return false;
        };
        let ok = |x: f32| x.is_finite() && x >= 0.0;
        if let Some(x) = spring.filter(|x| ok(*x)) {
            w.spring = x;
        }
        if let Some(x) = damping.filter(|x| ok(*x)) {
            w.damping = x;
        }
        if let Some(x) = damping_compression.filter(|x| ok(*x)) {
            w.damping_compression = x;
        }
        true
    }

    /// Whether an entity has a physics body right now (none for `SOLID_NONE` script shapes).
    /// The NPC model's heaviest sequence for an activity name (ACT_RUN / ACT_IDLE ...).
    fn npc_activity_sequence(&self, id: u32, act: &str) -> Option<String> {
        let n = self.npcs.get(&id)?;
        let act = npc_class_activity(&n.class, act);
        let m = self.models.get(&n.model)?;
        let mut best: Option<(i32, usize)> = None;
        for (i, (a, w)) in m.script.sequence_activity.iter().enumerate() {
            if a == act && !best.is_some_and(|(bw, _)| *w <= bw) {
                best = Some((*w, i));
            }
        }
        m.script.sequences.get(best?.1).cloned()
    }

    /// The game's SelectWeightedSequence: one of the model's sequences tagged `act`, drawn by
    /// weight (hashed on the NPC and the tick) - and the current one kept while it already
    /// carries the activity, so a running pick is not re-rolled every think.
    fn npc_activity_sequence_weighted(&self, id: u32, act: &str, now: u64) -> Option<String> {
        let n = self.npcs.get(&id)?;
        let act = npc_class_activity(&n.class, act);
        let m = self.models.get(&n.model)?;
        let cands: Vec<(usize, u32)> = m
            .script
            .sequence_activity
            .iter()
            .enumerate()
            .filter(|(_, (a, _))| a == act)
            .map(|(i, (_, w))| {
                let seq = m.script.sequences.get(i).map_or("", String::as_str);
                (
                    i,
                    npc_sequence_weight(&n.class, seq).unwrap_or((*w).max(1) as u32),
                )
            })
            .filter(|(_, w)| *w > 0)
            .collect();
        if cands
            .iter()
            .any(|(i, _)| m.script.sequences.get(*i) == Some(&n.sequence))
        {
            return Some(n.sequence.clone());
        }
        let total: u32 = cands.iter().map(|(_, w)| *w).sum();
        if total == 0 {
            return None;
        }
        let mut h = u64::from(id).wrapping_mul(0x9E37_79B9_7F4A_7C15)
            ^ now.wrapping_mul(0xD1B5_4A32_D192_ED03);
        h ^= h >> 31;
        h = h.wrapping_mul(0xBF58_476D_1CE4_E5B9);
        let mut roll = (h >> 20) as u32 % total;
        for (i, w) in &cands {
            if roll < *w {
                return m.script.sequences.get(*i).cloned();
            }
            roll -= w;
        }
        None
    }

    /// `npc_translated_sequence` with the weighted draw.
    fn npc_translated_sequence_weighted(&self, id: u32, act: &str, now: u64) -> Option<String> {
        let n = self.npcs.get(&id)?;
        npc_weapon_activity(&n.weapon, act)
            .and_then(|t| self.npc_activity_sequence_weighted(id, t, now))
            .or_else(|| self.npc_activity_sequence_weighted(id, act, now))
    }

    /// `act` through the NPC's weapon table (`npc_weapon_activity`) when the model carries the
    /// translated activity, else the base one.
    fn npc_translated_sequence(&self, id: u32, act: &str) -> Option<String> {
        let n = self.npcs.get(&id)?;
        npc_weapon_activity(&n.weapon, act)
            .and_then(|t| self.npc_activity_sequence(id, t))
            .or_else(|| self.npc_activity_sequence(id, act))
    }

    /// The firing body's (shoot, between bursts) sequences: the weapon-translated
    /// ACT_RANGE_ATTACK1 (LOW until the body moved in combat) and ACT_IDLE_ANGRY of the model
    /// (server_npc_grenade_soldier_wall: shootSMG1c at first contact, shootSMG1s /
    /// CombatIdle1_SMG1 after the run), the class table when the model lacks them.
    fn npc_shoot_sequences(&mut self, id: u32) -> Option<(String, String)> {
        let n = self.npcs.get(&id)?;
        let (shoot, between) = npc_combat_sequences(&n.class)?;
        let model = n.model.clone();
        let low = !n.combat_moved;
        if self.ensure_model(&model) {
            let attack = if low {
                self.npc_translated_sequence(id, "ACT_RANGE_ATTACK1_LOW")
            } else {
                None
            }
            .or_else(|| self.npc_translated_sequence(id, "ACT_RANGE_ATTACK1"));
            // crouched, the soldier idles in ACT_CROUCHIDLE between volleys (CrouchIdle)
            let between = if low {
                self.npc_activity_sequence(id, "ACT_CROUCHIDLE")
            } else {
                None
            }
            .or_else(|| self.npc_translated_sequence(id, "ACT_IDLE_ANGRY"));
            if let (Some(a), Some(b)) = (attack, between) {
                return Some((a, b));
            }
        }
        Some((shoot.to_string(), between.to_string()))
    }

    /// `(duration, looping)` of `seq` on `model`, from the sequence's first animation.
    fn seq_duration(&self, model: &str, seq: &str) -> Option<(f32, bool)> {
        let m = self.models.get(model)?;
        let i = m.script.sequences.iter().position(|q| q == seq)?;
        let (fps, frames, flags) = *m.script.sequence_anim.get(i)?;
        (fps > 0.0).then(|| ((frames - 1).max(1) as f32 / fps, flags & 1 != 0))
    }

    /// Model of an animatable entity: an NPC or a sandbox prop.
    fn anim_model(&self, ent: u32) -> Option<String> {
        if let Some(n) = self.npcs.get(&ent) {
            return Some(n.model.clone());
        }
        self.sandbox
            .props()
            .iter()
            .find(|p| p.id == ent)
            .map(|p| p.model.clone())
    }

    /// One animator step of `dt` seconds: the cycle moves by `rate * dt / duration`, loops wrap,
    /// one-shots clamp at 1 (either marks finished); the gesture layer the same, an autokill
    /// layer goes away at its end.
    fn advance_anim(&self, model: &str, a: &mut EntAnim, dt: f32) -> Vec<FiredAnimEvent> {
        let mut fired = Vec::new();
        if let Some((dur, looping)) = self.seq_duration(model, &a.sequence) {
            let from = a.cycle;
            a.cycle += a.rate * dt / dur;
            let wrapped = a.cycle >= 1.0;
            if wrapped {
                a.finished = true;
                a.cycle = if looping {
                    a.cycle.rem_euclid(1.0)
                } else {
                    1.0
                };
            }
            if a.rate > 0.0 {
                let to = if wrapped { 1.0 } else { a.cycle };
                fired = self.anim_events_between(model, &a.sequence, dur, from, to, wrapped);
                if wrapped && looping && a.cycle > 0.0 {
                    fired.extend(self.anim_events_between(
                        model,
                        &a.sequence,
                        dur,
                        -1.0,
                        a.cycle,
                        false,
                    ));
                }
            }
        }
        if let Some(g) = a.gesture.as_mut() {
            if let Some((dur, _)) = self.seq_duration(model, &g.sequence) {
                g.cycle += g.rate * dt / dur;
                if g.cycle >= 1.0 {
                    g.finished = true;
                    g.cycle = if g.looping {
                        g.cycle.rem_euclid(1.0)
                    } else {
                        1.0
                    };
                }
            }
            if g.finished && g.autokill {
                a.gesture = None;
            }
        }
        fired
    }

    /// The events of `seq` with a cycle in `(from, to]` (`to` inclusive only at the end of a
    /// pass, `at_end`), as the game's `DispatchAnimEvents` scans them each frame.
    fn anim_events_between(
        &self,
        model: &str,
        seq: &str,
        dur: f32,
        from: f32,
        to: f32,
        at_end: bool,
    ) -> Vec<FiredAnimEvent> {
        let Some(m) = self.models.get(model) else {
            return Vec::new();
        };
        let Some(i) = m.script.sequences.iter().position(|q| q == seq) else {
            return Vec::new();
        };
        m.script
            .sequence_events
            .get(i)
            .map(|evs| {
                evs.iter()
                    .filter(|e| e.0 > from && (e.0 < to || (at_end && e.0 <= to)))
                    .map(|e| FiredAnimEvent {
                        event: e.1,
                        kind: e.2,
                        time: e.0 * dur,
                        cycle: e.0,
                        options: e.3.clone(),
                        name: e.4.clone(),
                    })
                    .collect()
            })
            .unwrap_or_default()
    }

    /// The NPC footstep of an animation event, as the HL2 NPC classes' `HandleAnimEvent`:
    /// `NPC_EVENT_LEFTFOOT` / `RIGHTFOOT` (6006 / 6007, the options string naming the sound
    /// prefix, `NPC_Citizen`) voice `<prefix>.FootstepLeft/Right`; soldiers and metrocops always
    /// their `RunFootstep*`, the zombies' named `AE_ZOMBIE_STEP_*` their own `*.Footstep*` scripts.
    fn npc_anim_event_footstep(class: &str, e: &FiredAnimEvent) -> Option<String> {
        let (left, zombie) = match (e.event, e.name.as_str()) {
            (6006, _) => (true, false),
            (6007, _) => (false, false),
            (_, "AE_NPC_LEFTFOOT") => (true, false),
            (_, "AE_NPC_RIGHTFOOT") => (false, false),
            (_, "AE_ZOMBIE_STEP_LEFT") => (true, true),
            (_, "AE_ZOMBIE_STEP_RIGHT") => (false, true),
            _ => return None,
        };
        let side = if left { "Left" } else { "Right" };
        let name = match class {
            "npc_combine_s" => format!("NPC_CombineS.RunFootstep{side}"),
            "npc_metropolice" => format!("NPC_MetroPolice.RunFootstep{side}"),
            "npc_poisonzombie" => format!("NPC_PoisonZombie.Footstep{side}"),
            "npc_fastzombie" | "npc_fastzombie_torso" => format!("NPC_FastZombie.Footstep{side}"),
            _ if zombie => format!("Zombie.Footstep{side}"),
            _ if !e.options.is_empty() => format!("{}.Footstep{side}", e.options),
            _ => return None,
        };
        Some(name)
    }

    fn push_anim_events(&mut self, ent: u32, player: bool, fired: Vec<FiredAnimEvent>) {
        for e in fired {
            if !player {
                let class = self.npcs.get(&ent).map(|n| n.class.clone());
                if let Some(snd) = class.and_then(|c| Self::npc_anim_event_footstep(&c, &e)) {
                    self.emit_sound(ent, snd, 1.0);
                }
            }
            self.game_events.push(GameEvent::AnimEvent {
                ent,
                player,
                event: e.event,
                kind: e.kind,
                time: e.time,
                cycle: e.cycle,
                options: e.options,
                name: e.name,
            });
        }
    }

    /// `NPC:MarkTookDamageFromEnemy`: the NPC remembers being hurt by its enemy now (feeds the
    /// cover / suppression logic the same way a real hit does). False for a non-NPC.
    pub fn npc_mark_damaged(&mut self, ent: u32) -> bool {
        let tick = self.tick_count;
        match self.npcs.get_mut(&ent) {
            Some(n) => {
                n.last_enemy_damage = tick;
                true
            }
            None => false,
        }
    }

    /// `Entity:FrameAdvance(dt)`: steps the entity's animator by `dt` now (an NPC's base
    /// sequence stays what its AI plays). False for an entity without a model.
    pub fn frame_advance(&mut self, ent: u32, dt: f32) -> bool {
        let Some(model) = self.anim_model(ent) else {
            return false;
        };
        let mut a = self.anims.remove(&ent).unwrap_or_default();
        if a.sequence.is_empty() {
            if let Some(n) = self.npcs.get(&ent) {
                a.sequence = n.sequence.clone();
            }
        }
        let fired = self.advance_anim(&model, &mut a, dt);
        self.anims.insert(ent, a);
        self.push_anim_events(ent, false, fired);
        true
    }

    /// Players' gesture layers advance like the entities' (the base sequence is the
    /// client's); a finished autokill layer goes away, as does a gone player's.
    fn tick_player_anims(&mut self) {
        let dt = gm_core::tick::DEFAULT_TICK_INTERVAL;
        let ids: Vec<u32> = self.player_anims.keys().copied().collect();
        for id in ids {
            let Some(model) = self.players.get(&id).map(|p| p.model.clone()) else {
                self.player_anims.remove(&id);
                continue;
            };
            let mut a = self.player_anims.remove(&id).unwrap_or_default();
            let fired = self.advance_anim(&model, &mut a, dt);
            if a.gesture.is_some() {
                self.player_anims.insert(id, a);
            }
            self.push_anim_events(id, true, fired);
        }
    }

    /// `CLuaLocomotion` state of a scripted NextBot entity, created on first use.
    pub fn nextbot_ensure(&mut self, ent: u32) -> bool {
        if !self.sents.contains_key(&ent) {
            return false;
        }
        if !self.nextbots.contains_key(&ent) {
            self.sandbox.set_frozen(ent, true);
            self.sync_physics();
            self.nextbots.insert(ent, NextBot::default());
        }
        true
    }

    pub fn nextbot(&self, ent: u32) -> Option<&NextBot> {
        self.nextbots.get(&ent)
    }

    /// A `CLuaLocomotion` op from a script; false for a non-NextBot.
    pub fn nextbot_op(&mut self, ent: u32, op: NextBotOp) -> bool {
        if !self.nextbot_ensure(ent) {
            return false;
        }
        let Some(b) = self.nextbots.get_mut(&ent) else {
            return false;
        };
        match op {
            NextBotOp::Approach { pos } => b.goal = Some(pos),
            NextBotOp::Face { pos } => b.face = Some(pos),
            NextBotOp::DesiredSpeed(v) => b.desired_speed = v.max(0.0),
            NextBotOp::Accel(v) => b.accel = v.max(0.0),
            NextBotOp::Decel(v) => b.decel = v.max(0.0),
            NextBotOp::StepHeight(v) => b.step_height = v.max(0.0),
            NextBotOp::JumpHeight(v) => b.jump_height = v.max(0.0),
            NextBotOp::MaxYawRate(v) => b.max_yaw_rate = v.max(0.0),
            NextBotOp::Gravity(v) => b.gravity = v,
            NextBotOp::Jump => {
                if b.on_ground {
                    b.velocity.z = (2.0 * b.gravity.max(1.0) * b.jump_height).sqrt();
                    b.on_ground = false;
                }
            }
            NextBotOp::JumpAcrossGap { pos } => {
                if b.on_ground {
                    b.velocity.z = (2.0 * b.gravity.max(1.0) * b.jump_height).sqrt();
                    b.on_ground = false;
                    b.goal = Some(pos);
                }
            }
            NextBotOp::ClearStuck => b.stuck = 0,
            NextBotOp::SetVelocity(v) => b.velocity = v,
        }
        true
    }

    /// One hull step of a mover: lifted by the step height, swept against the world, slid along
    /// a blocking wall, then dropped onto the floor. `(floor position, on ground, blocked)`.
    fn hull_step(
        &self,
        pos: Vec3,
        mins: Vec3,
        maxs: Vec3,
        want: Vec3,
        step: f32,
    ) -> (Vec3, bool, bool) {
        let lift = Vec3::new(0.0, 0.0, step);
        let mut tr = self.collision.trace_box(
            pos + lift,
            want + lift,
            mins,
            maxs,
            gm_collision::MASK_PLAYERSOLID,
        );
        let mut blocked = false;
        if tr.fraction < 0.999 && !tr.start_solid {
            blocked = true;
            let rest = want + lift - tr.end;
            let slide = rest - tr.normal * rest.dot(tr.normal);
            if slide.length_squared() > 1e-6 {
                let ts = self.collision.trace_box(
                    tr.end,
                    tr.end + slide,
                    mins,
                    maxs,
                    gm_collision::MASK_PLAYERSOLID,
                );
                if !ts.start_solid {
                    tr.end = ts.end;
                }
            }
        }
        let reached = if tr.start_solid { pos + lift } else { tr.end };
        match self.npc_floor(reached, mins, maxs) {
            Some(floor) if floor.z >= want.z - step => (floor, true, blocked),
            _ => (reached - lift, false, blocked),
        }
    }

    /// Scripted NextBots move: the xy velocity ramps toward the approach goal at the desired
    /// speed (accel / decel), gravity pulls an airborne bot, the hull steps over the world like
    /// an NPC's, the body turns toward the face target (else the goal) at the yaw rate, a bot
    /// that barely moves while trying counts as stuck. Gone entities drop their state.
    fn tick_nextbots(&mut self) {
        let dt = gm_core::tick::DEFAULT_TICK_INTERVAL;
        let ids: Vec<u32> = self.nextbots.keys().copied().collect();
        for id in ids {
            let Some(prop) = self.sandbox.props().iter().find(|p| p.id == id).cloned() else {
                self.nextbots.remove(&id);
                continue;
            };
            let mut b = self.nextbots.remove(&id).unwrap_or_default();
            let (mins, maxs) = self
                .collision_bounds(id)
                .filter(|(mn, mx)| mx.x > mn.x && mx.z > mn.z)
                .unwrap_or((Vec3::new(-16.0, -16.0, 0.0), Vec3::new(16.0, 16.0, 72.0)));
            let pos = prop.pos;
            let goal = b.goal.take();
            let want_xy = match goal {
                Some(g) if b.desired_speed > 0.0 => {
                    let d = (g - pos).truncate();
                    if d.length() > 1.0 {
                        d.normalize() * b.desired_speed
                    } else {
                        glam::Vec2::ZERO
                    }
                }
                _ => glam::Vec2::ZERO,
            };
            let cur = b.velocity.truncate();
            let diff = want_xy - cur;
            let rate = if want_xy.length() > cur.length() {
                b.accel
            } else {
                b.decel
            };
            let next_xy = if diff.length() <= rate * dt {
                want_xy
            } else {
                cur + diff.normalize() * rate * dt
            };
            b.velocity.x = next_xy.x;
            b.velocity.y = next_xy.y;
            if !b.on_ground {
                b.velocity.z -= b.gravity * dt;
            } else {
                b.velocity.z = 0.0;
            }
            let want = pos + b.velocity * dt;
            let (floor, on_ground, blocked) = self.hull_step(pos, mins, maxs, want, b.step_height);
            let new_pos = if on_ground {
                floor
            } else {
                Vec3::new(floor.x, floor.y, want.z.max(floor.z))
            };
            if on_ground && b.velocity.z <= 0.0 {
                b.velocity.z = 0.0;
            }
            b.on_ground = on_ground || (b.velocity.z <= 0.0 && (new_pos.z - floor.z).abs() < 0.5);
            let intended = want_xy.length() * dt;
            let moved = (new_pos - pos).truncate().length();
            b.stuck = if intended > 1.0 && moved < intended * 0.1 {
                b.stuck.saturating_add(1)
            } else {
                0
            };
            let target = b.face.or(goal);
            let mut yaw = prop.angles.y;
            if let Some(t) = target {
                let d = (t - new_pos).truncate();
                if d.length_squared() > 1e-6 {
                    let want_yaw = d.y.atan2(d.x).to_degrees();
                    let delta = wrap_deg(want_yaw - yaw);
                    let max = b.max_yaw_rate * dt;
                    yaw += delta.clamp(-max, max);
                }
            }
            b.face = None;
            let _ = blocked;
            self.teleport_prop(id, new_pos, Vec3::new(prop.angles.x, yaw, prop.angles.z));
            self.nextbots.insert(id, b);
        }
    }

    /// Loads and registers `model` through the host loader if the server does not have it.
    fn ensure_model(&mut self, model: &str) -> bool {
        if self.models.contains_key(model) {
            return true;
        }
        let Some(loaded) = self.model_loader.as_mut().and_then(|f| f(model)) else {
            return false;
        };
        self.register_model(model, loaded);
        true
    }

    /// A player's gesture layer, if one plays.
    pub fn player_anim(&self, player: u32) -> Option<&EntAnim> {
        self.player_anims.get(&player)
    }

    /// `Player:AnimSetGestureSequence` with a fresh layer: `name` must be a sequence of the
    /// player's model.
    pub fn player_add_gesture(&mut self, player: u32, name: &str, autokill: bool) -> bool {
        let Some(model) = self.players.get(&player).map(|p| p.model.clone()) else {
            return false;
        };
        if !self.ensure_model(&model) || self.seq_duration(&model, name).is_none() {
            return false;
        }
        let a = self.player_anims.entry(player).or_default();
        a.gesture = Some(GestureLayer {
            sequence: name.to_string(),
            cycle: 0.0,
            rate: 1.0,
            weight: 1.0,
            looping: false,
            autokill,
            priority: 0,
            finished: false,
        });
        true
    }

    /// `Player:AnimRestartGesture(slot, act, autokill)`: the gesture is a sequence of the
    /// player's model tagged with `act`, picked by weight (deterministic on the tick).
    pub fn player_add_gesture_by_activity(
        &mut self,
        player: u32,
        act: &str,
        autokill: bool,
    ) -> bool {
        let Some(model) = self.players.get(&player).map(|p| p.model.clone()) else {
            return false;
        };
        if !self.ensure_model(&model) {
            return false;
        }
        let Some(m) = self.models.get(&model) else {
            return false;
        };
        let candidates: Vec<(String, i32)> = m
            .script
            .sequences
            .iter()
            .zip(m.script.sequence_activity.iter())
            .filter(|(_, (a, _))| a.eq_ignore_ascii_case(act))
            .map(|(s, (_, w))| (s.clone(), (*w).max(1)))
            .collect();
        if candidates.is_empty() {
            return false;
        }
        let total: i32 = candidates.iter().map(|c| c.1).sum();
        let mut pick = (self.tick_count.wrapping_mul(2_654_435_761) % total.max(1) as u64) as i32;
        let mut name = candidates[0].0.clone();
        for (s, w) in &candidates {
            if pick < *w {
                name = s.clone();
                break;
            }
            pick -= w;
        }
        self.player_add_gesture(player, &name, autokill)
    }

    /// `Player:AnimSetGestureSequence` / `AnimSetGestureWeight` on the playing layer (a
    /// sequence the model lacks is refused; no layer, no change).
    pub fn player_set_gesture(
        &mut self,
        player: u32,
        sequence: Option<&str>,
        weight: Option<f32>,
    ) -> bool {
        let Some(model) = self.players.get(&player).map(|p| p.model.clone()) else {
            return false;
        };
        if let Some(seq) = sequence {
            if self
                .player_anims
                .get(&player)
                .and_then(|a| a.gesture.as_ref())
                .is_none()
            {
                return self.player_add_gesture(player, seq, true);
            }
            if self.seq_duration(&model, seq).is_none() {
                return false;
            }
        }
        let Some(g) = self
            .player_anims
            .get_mut(&player)
            .and_then(|a| a.gesture.as_mut())
        else {
            return false;
        };
        if let Some(seq) = sequence {
            g.sequence = seq.to_string();
            g.cycle = 0.0;
            g.finished = false;
        }
        if let Some(w) = weight {
            g.weight = w.clamp(0.0, 1.0);
        }
        true
    }

    /// `Player:AnimResetGestureSlot`: the layer goes away.
    pub fn player_remove_gesture(&mut self, player: u32) -> bool {
        self.player_anims.remove(&player).is_some()
    }

    /// Advances every animator one tick: an NPC's sequence follows what its AI plays (a change
    /// restarts the cycle), the cycle moves by `rate * dt / duration`, loops wrap, one-shots
    /// clamp at 1, either marks the sequence finished; the gesture layer the same, an autokill
    /// layer goes away at its end. Animators of gone entities are dropped.
    fn tick_anims(&mut self) {
        let dt = gm_core::tick::DEFAULT_TICK_INTERVAL;
        let mut live: Vec<(u32, String, Option<String>)> = self
            .npcs
            .iter()
            .map(|(id, n)| (*id, n.model.clone(), Some(n.sequence.clone())))
            .collect();
        for p in self.sandbox.props() {
            if self.anims.contains_key(&p.id) {
                live.push((p.id, p.model.clone(), None));
            }
        }
        let ids: BTreeSet<u32> = live.iter().map(|l| l.0).collect();
        self.anims.retain(|id, _| ids.contains(id));
        let all: BTreeSet<u32> = self
            .npcs
            .keys()
            .copied()
            .chain(self.sandbox.props().iter().map(|p| p.id))
            .collect();
        self.poses.retain(|id, _| all.contains(id));
        self.bounds_override.retain(|id, _| all.contains(id));
        for (id, model, base) in live {
            let mut a = self.anims.remove(&id).unwrap_or_default();
            if let Some(base) = base {
                if a.sequence != base {
                    a.sequence = base;
                    a.cycle = 0.0;
                    a.finished = false;
                }
            }
            let fired = self.advance_anim(&model, &mut a, dt);
            self.anims.insert(id, a);
            self.push_anim_events(id, false, fired);
        }
    }

    /// The animator of an entity (`Entity:GetCycle` and friends); NPCs have one after their
    /// first tick, props only once a script set a sequence.
    pub fn anim(&self, ent: u32) -> Option<&EntAnim> {
        self.anims.get(&ent)
    }

    /// `Entity:SetSequence`: the model must have the sequence; an NPC's AI sequence changes too
    /// (its rest sequence is forgotten), the cycle restarts.
    pub fn set_sequence(&mut self, ent: u32, name: &str) -> bool {
        let Some(model) = self.anim_model(ent) else {
            return false;
        };
        if self.seq_duration(&model, name).is_none() {
            return false;
        }
        if let Some(n) = self.npcs.get_mut(&ent) {
            n.sequence = name.to_string();
            n.rest_sequence = None;
        }
        let a = self.anims.entry(ent).or_default();
        a.sequence = name.to_string();
        a.cycle = 0.0;
        a.finished = false;
        true
    }

    /// `Entity:SetCycle`: the cycle clamped to `[0, 1]`, the finished flag cleared.
    pub fn set_cycle(&mut self, ent: u32, cycle: f32) -> bool {
        let Some(a) = self.anim_entry(ent) else {
            return false;
        };
        a.cycle = cycle.clamp(0.0, 1.0);
        a.finished = false;
        true
    }

    /// `Entity:SetPlaybackRate`.
    pub fn set_playback_rate(&mut self, ent: u32, rate: f32) -> bool {
        let Some(a) = self.anim_entry(ent) else {
            return false;
        };
        a.rate = rate;
        true
    }

    /// `Entity:ResetSequenceInfo`: cycle 0, finished cleared.
    pub fn reset_sequence_info(&mut self, ent: u32) -> bool {
        let Some(a) = self.anim_entry(ent) else {
            return false;
        };
        a.cycle = 0.0;
        a.finished = false;
        true
    }

    /// The animator of a live NPC or prop, created on demand (an NPC's from its AI sequence).
    fn anim_entry(&mut self, ent: u32) -> Option<&mut EntAnim> {
        let base = self.npcs.get(&ent).map(|n| n.sequence.clone());
        if base.is_none() && !self.sandbox.props().iter().any(|p| p.id == ent) {
            return None;
        }
        Some(self.anims.entry(ent).or_insert_with(|| EntAnim {
            sequence: base.unwrap_or_default(),
            ..EntAnim::default()
        }))
    }

    /// `Entity:AddGesture*`: one gesture layer per entity (a second call replaces it); the
    /// model must have the sequence. Weight 1, rate 1, not looping.
    pub fn add_gesture(&mut self, ent: u32, name: &str, autokill: bool) -> bool {
        let Some(model) = self.anim_model(ent) else {
            return false;
        };
        if self.seq_duration(&model, name).is_none() {
            return false;
        }
        let Some(a) = self.anim_entry(ent) else {
            return false;
        };
        a.gesture = Some(GestureLayer {
            sequence: name.to_string(),
            cycle: 0.0,
            rate: 1.0,
            weight: 1.0,
            looping: false,
            autokill,
            priority: 0,
            finished: false,
        });
        true
    }

    /// `Entity:SetLayer*` on the gesture layer; a sequence the model lacks is refused.
    pub fn set_gesture(&mut self, ent: u32, patch: &GesturePatch) -> bool {
        let Some(model) = self.anim_model(ent) else {
            return false;
        };
        if let Some(seq) = &patch.sequence {
            if self.seq_duration(&model, seq).is_none() {
                return false;
            }
        }
        let Some(g) = self.anims.get_mut(&ent).and_then(|a| a.gesture.as_mut()) else {
            return false;
        };
        if let Some(seq) = &patch.sequence {
            g.sequence = seq.clone();
            g.cycle = 0.0;
            g.finished = false;
        }
        if let Some(c) = patch.cycle {
            g.cycle = c.clamp(0.0, 1.0);
            g.finished = false;
        }
        if let Some(r) = patch.rate {
            g.rate = r;
        }
        if let Some(w) = patch.weight {
            g.weight = w.clamp(0.0, 1.0);
        }
        if let Some(l) = patch.looping {
            g.looping = l;
        }
        if let Some(k) = patch.autokill {
            g.autokill = k;
        }
        if let Some(p) = patch.priority {
            g.priority = p;
        }
        true
    }

    /// Pose parameter values an entity has set (`Entity:GetPoseParameter`).
    pub fn pose_parameters(&self, ent: u32) -> Option<&BTreeMap<String, f32>> {
        self.poses.get(&ent)
    }

    /// `Entity:SetPoseParameter`: the model must have the parameter (name case-insensitive);
    /// the value is wrapped into the range of a looping parameter, clamped otherwise.
    pub fn set_pose_parameter(&mut self, ent: u32, name: &str, value: f32) -> bool {
        let Some(model) = self.anim_model(ent) else {
            return false;
        };
        let Some((pname, start, end, wrap)) = self.models.get(&model).and_then(|m| {
            m.script
                .pose_params
                .iter()
                .find(|p| p.0.eq_ignore_ascii_case(name))
                .cloned()
        }) else {
            return false;
        };
        let v = if wrap > 0.0 && end > start {
            start + (value - start).rem_euclid(end - start)
        } else {
            value.clamp(start.min(end), end.max(start))
        };
        self.poses.entry(ent).or_default().insert(pname, v);
        true
    }

    /// `Entity:ClearPoseParameters`: every parameter back to its default.
    pub fn clear_pose_parameters(&mut self, ent: u32) -> bool {
        if self.anim_model(ent).is_none() {
            return false;
        }
        self.poses.remove(&ent);
        true
    }

    /// `Entity:GetCollisionBounds`: an NPC's hull, a prop's model collision bounds (the MDL hull
    /// box widened to its PHY points) or the override a script set.
    pub fn collision_bounds(&self, ent: u32) -> Option<(Vec3, Vec3)> {
        if let Some(b) = self.bounds_override.get(&ent) {
            return Some(*b);
        }
        if let Some(n) = self.npcs.get(&ent) {
            return Some((n.mins, n.maxs));
        }
        let p = self.sandbox.props().iter().find(|p| p.id == ent)?;
        let b = &self.models.get(&p.model)?.bounds;
        Some((b.min, b.max))
    }

    /// `Entity:SetCollisionBounds`: an NPC's hull (its hit tests use it), a prop's readback.
    pub fn set_collision_bounds(&mut self, ent: u32, mins: Vec3, maxs: Vec3) -> bool {
        let (mins, maxs) = (mins.min(maxs), mins.max(maxs));
        if let Some(n) = self.npcs.get_mut(&ent) {
            n.mins = mins;
            n.maxs = maxs;
            return true;
        }
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        self.bounds_override.insert(ent, (mins, maxs));
        true
    }

    /// `Entity:RemoveGesture` / `RemoveAllGestures` / `RemoveLayer`.
    pub fn remove_gesture(&mut self, ent: u32) -> bool {
        match self.anims.get_mut(&ent) {
            Some(a) if a.gesture.is_some() => {
                a.gesture = None;
                true
            }
            _ => false,
        }
    }

    pub fn has_body(&self, ent: u32) -> bool {
        self.bodies.contains_key(&ent)
    }

    /// `ENT:PhysicsInit*` / `PhysicsDestroy` on a live scripted entity: the body is dropped and
    /// rebuilt with the shape on the next tick. False for an unknown entity.
    pub fn set_script_shape(&mut self, ent: u32, shape: PhysShape) -> bool {
        if !self.sandbox.props().iter().any(|p| p.id == ent) {
            return false;
        }
        self.model_scales.remove(&ent);
        self.prevent_transmit.retain(|(e, _)| *e != ent);
        self.transmit_mode.remove(&ent);
        if let Some(body) = self.bodies.remove(&ent) {
            self.physics.remove_body(body);
        }
        if shape == PhysShape::Static {
            self.sandbox.set_frozen(ent, true);
        }
        self.script_shapes.insert(ent, shape);
        self.sync_physics();
        true
    }

    /// `Vehicle:StartEngine` / `EnableEngine`: the engine switch; off, the car parks.
    pub fn set_vehicle_engine(&mut self, veh: u32, on: bool) -> bool {
        let Some(v) = self.vehicles.get_mut(&veh) else {
            return false;
        };
        v.controls.engine_on = on;
        true
    }

    pub fn exit_vehicle(&mut self, player: u32) -> bool {
        let Some(veh) = self.players.get(&player).and_then(|p| p.seat) else {
            return false;
        };
        let (pos, yaw) = match self.sandbox.props().iter().find(|p| p.id == veh) {
            Some(prop) => {
                let (pos, dir) = self.vehicle_exit_point(prop.id, prop.pos, prop.angles);
                (pos, dir.y.atan2(dir.x).to_degrees())
            }
            None => (
                self.players[&player].state.origin,
                self.players[&player].view_angles.y,
            ),
        };
        if let Some(v) = self.vehicles.get_mut(&veh) {
            v.controls.engine_on = false;
            v.controls.throttle = 0.0;
            v.controls.steer = 0.0;
            v.controls.handbrake = false;
            v.controls.boost = 0.0;
        }
        if let Some(p) = self.players.get_mut(&player) {
            p.seat = None;
            p.state.origin = pos;
            p.state.game_moved = true;
            p.state.velocity = Vec3::ZERO;
            p.view_angles = Vec3::new(0.0, yaw.rem_euclid(360.0), 0.0);
        }
        if let Some(v) = self.vehicles.get_mut(&veh) {
            v.driver = None;
        }
        self.game_events.push(GameEvent::ExitVehicle {
            player,
            vehicle: veh,
        });
        true
    }

    /// Measured `server_vehicle_exit_*` (chair, jeep): the engine tries four points around the
    /// vehicle in order, each a player-hull sweep from the origin (+`VEHICLE_EXIT_Z`) that must
    /// reach its end; the vehicle's own sides are a quarter turn from its angles (like its
    /// attachments): behind 90 u, ahead 90 u, left 100 u, right 170 u; all blocked -> straight
    /// above (90.9 u on the chair, then the player falls).
    fn vehicle_exit_point(&self, veh: u32, origin: Vec3, angles: Vec3) -> (Vec3, Vec3) {
        let rot = gm_sandbox::rotation(angles);
        let fwd = rot * Vec3::X;
        let left = rot * Vec3::Y;
        let start = origin + Vec3::new(0.0, 0.0, VEHICLE_EXIT_Z);
        let bodies: Vec<PropBody> = self
            .trace_bodies()
            .into_iter()
            .filter(|b| b.id != veh)
            .collect();
        for (dir, dist) in [(-fwd, 90.0), (fwd, 90.0), (left, 100.0), (-left, 170.0)] {
            let end = start + dir * dist;
            if self.exit_hull_clear(start, end, &bodies) {
                return (end, dir);
            }
        }
        (origin + Vec3::new(0.0, 0.0, VEHICLE_EXIT_TOP), fwd)
    }

    /// A car's body takes the script's mass and its four `wheel_*` attachments become raycast
    /// wheels (the axle with the larger model y is the front).
    fn setup_car(&mut self, veh: u32, key: &str) {
        let Some(script) = vehicle_script(key) else {
            return;
        };
        let Some(prop) = self.sandbox.props().iter().find(|p| p.id == veh).cloned() else {
            return;
        };
        let hubs: Vec<Vec3> = ["wheel_fl", "wheel_fr", "wheel_rl", "wheel_rr"]
            .iter()
            .filter_map(|n| {
                self.models
                    .get(&prop.model)?
                    .attachments
                    .iter()
                    .find(|a| &a.name == n)
                    .map(|a| a.pos)
            })
            .collect();
        if hubs.len() != 4 {
            return;
        }
        let mid = hubs.iter().map(|h| h.y).sum::<f32>() / 4.0;
        let wheels = hubs
            .iter()
            .map(|&hub| {
                let (radius, spring, damping, damping_compression) = if hub.y > mid {
                    script.front
                } else {
                    script.rear
                };
                Wheel {
                    hub: Vec3::new(hub.x, hub.y, radius + 1.0),
                    radius,
                    spring,
                    damping,
                    damping_compression,
                }
            })
            .collect();
        if let Some(&body) = self.bodies.get(&veh) {
            // the game's car body shows no air drag: full throttle gains and coasting lose speed
            // at constant rates from standstill to 35 mph (`server_vehicle_drive`)
            self.physics.disable_drag(body);
            self.physics.set_mass(body, script.mass);
        }
        // measured `server_vehicle_settle`: a car whose hull clears the floor sits 1 u under
        // the hit point in its spawn tick (the wheel bodies take the body down with them),
        // the airboat's hull is on the floor and stays at it
        let hull_min = self.models.get(&prop.model).map_or(0.0, |m| {
            m.hulls.iter().flatten().fold(f32::MAX, |a, v| a.min(v.z))
        });
        if hull_min > 1.0 {
            self.teleport_prop(veh, prop.pos - Vec3::new(0.0, 0.0, 1.0), prop.angles);
        }
        if let Some(v) = self.vehicles.get_mut(&veh) {
            v.wheels = wheels;
            v.add_gravity = script.add_gravity;
            v.mass = script.mass;
        }
    }

    /// Cars before the physics step: each wheel casts from its hub down the body's up axis and
    /// pushes the body up by its spring (`springConstant` per kg of body over the unloaded
    /// rest, `springDamping` on the hub's vertical speed); the script's `addgravity` pulls the
    /// body down on top of gravity. The wheels see the world only for now.
    fn tick_vehicles(&mut self) {
        let dt = gm_core::tick::DEFAULT_TICK_INTERVAL;
        let cars: Vec<CarRow> = self
            .vehicles
            .iter()
            .filter(|(_, v)| !v.wheels.is_empty())
            .filter_map(|(id, v)| {
                let script = vehicle_script(&v.key)?;
                Some((
                    *id,
                    v.wheels.clone(),
                    v.add_gravity,
                    v.mass,
                    v.tuning.rest.unwrap_or(script.rest),
                    v.controls.clone(),
                    v.spec(),
                    v.tuning.clone(),
                ))
            })
            .collect();
        for (id, wheels, add_gravity, mass, rest, mut c, spec, tune) in cars {
            let Some(&body) = self.bodies.get(&id) else {
                continue;
            };
            if self.physics.is_frozen(body) {
                continue;
            }
            let st = self.physics.state(body);
            let com = self.physics.center_of_mass(body);
            // the state's angular velocity is in degrees per second
            let omega = st.angular_velocity * (std::f32::consts::PI / 180.0);
            let up = st.rotation * Vec3::Z;
            // the front axle is the pair of hubs further along +Y of the model
            let fwd = st.rotation * Vec3::Y;
            let g_total = (1.0 + add_gravity) * 600.0;
            if add_gravity > 0.0 {
                self.physics
                    .add_impulse(body, Vec3::new(0.0, 0.0, -add_gravity * 600.0 * mass * dt));
            }
            let driving = c.engine_on && spec.is_some();
            let spec = spec.unwrap_or(JEEP_DRIVE);
            let speed = st.velocity.dot(fwd);
            let cone = VehicleControls::steer_cone(speed, &spec);
            let steer = c.steer.clamp(-1.0, 1.0);
            let angle = if driving {
                cone * steer.abs().powf(spec.steer_exp) * steer.signum()
            } else {
                0.0
            };
            // the kinematic wheelbase of the measured turn is longer than the hubs' span: the
            // front wheels steer by the angle that gives the measured yaw rate over the real span
            let span = {
                let ys: Vec<f32> = wheels.iter().map(|w| w.hub.y).collect();
                let max = ys.iter().cloned().fold(f32::MIN, f32::max);
                let min = ys.iter().cloned().fold(f32::MAX, f32::min);
                (max - min).max(1.0)
            };
            let wheel_angle = (angle.to_radians().tan() * span / spec.turn_len).atan();
            let mid_y = wheels.iter().map(|w| w.hub.y).sum::<f32>() / wheels.len() as f32;
            let share = mass / wheels.len() as f32;
            let mut contacts = 0u32;
            let mut traces = Vec::with_capacity(wheels.len());
            for w in &wheels {
                let hub = st.position + st.rotation * w.hub;
                let len = w.radius + VEHICLE_WHEEL_TRAVEL;
                let tr = self
                    .collision
                    .trace_ray(hub, hub - up * len, gm_collision::MASK_SOLID);
                traces.push(WheelContact {
                    hub,
                    point: hub - up * (len * tr.fraction.min(1.0)),
                    touching: tr.fraction < 1.0,
                });
                if tr.fraction >= 1.0 {
                    continue;
                }
                contacts += 1;
                let ext = tr.fraction * len - w.radius;
                let natural = rest + g_total / (4.0 * w.spring);
                let v_hub = st.velocity + omega.cross(hub - com);
                let v_up = v_hub.dot(up);
                // the script's heavier `springDampingCompression` is not applied: one-sided
                // damping on a rigid body (no wheel bodies) ratchets the car upward
                let damping = w.damping;
                let force = mass * (w.spring * (natural - ext) - damping * v_up);
                if force <= 0.0 {
                    continue;
                }
                self.physics.add_impulse_at(body, hub, up * (force * dt));
                let v_h = v_hub - up * v_up;
                let cap = VEHICLE_TYRE_FRICTION * force * dt;
                if driving {
                    // a rolling tyre holds only across its heading: the front wheels' heading
                    // carries the steering angle, and the hold acts at the hub brought to the
                    // centre-of-mass height so that it turns the car without rolling it
                    let heading = if w.hub.y > mid_y {
                        let (sn, cs) = wheel_angle.sin_cos();
                        // steering right (positive) turns the heading clockwise seen from above
                        fwd * cs - up.cross(fwd) * sn
                    } else {
                        fwd
                    };
                    let lateral = v_h - heading * v_h.dot(heading);
                    let want = lateral.length() * share;
                    if want > 1e-3 {
                        let at = com + (hub - com) - up * (hub - com).dot(up);
                        // the airboat's sliding tyres hold with a share of the cone; the speed
                        // the game's boat loses through a hard turn is not reproduced
                        // (kinetic friction on the whole slip was tried: it brakes the
                        // straight run, since the hold's own jitter counts as sliding)
                        let cap = cap * spec.tyre_mu;
                        self.physics
                            .add_impulse_at(body, at, -lateral.normalize() * want.min(cap));
                    }
                } else {
                    // parked: the tyre holds the contact still, bounded by the friction cone of
                    // the spring's load
                    let want = v_h.length() * share;
                    if want > 1e-3 {
                        self.physics
                            .add_impulse_at(body, com, -v_h.normalize() * want.min(cap));
                    }
                }
            }
            if driving && contacts > 0 {
                let throttle = c.throttle.clamp(
                    -tune.max_rev_throttle.clamp(0.0, 1.0),
                    tune.max_throttle.clamp(0.0, 1.0),
                );
                let stop = -speed.signum() * (speed.abs() / dt);
                let accel = if c.handbrake {
                    stop.abs().min(spec.brake) * stop.signum()
                } else if throttle > 0.05 && c.boost > 0.0 && spec.boost_accel > 0.0 {
                    if speed < spec.boost_max {
                        spec.boost_accel * throttle
                    } else {
                        spec.boost_creep * throttle
                    }
                } else if throttle > 0.05 {
                    if speed < spec.max_fwd {
                        spec.accel * throttle - spec.drag_fwd * speed
                    } else if speed > spec.max_fwd + 30.0 {
                        // coming off the turbo: back toward the plateau (the game's settles at
                        // 677 u/s in its higher gear, ours at the plateau)
                        -spec.over_decay * (speed - spec.max_fwd)
                    } else {
                        spec.creep_fwd * throttle
                    }
                } else if throttle < -0.05 {
                    if speed > -spec.max_rev {
                        spec.accel_rev * throttle - spec.drag_rev * speed
                    } else {
                        spec.creep_rev * throttle
                    }
                } else {
                    stop.abs().min(spec.coast) * stop.signum()
                };
                if accel.abs() > 1e-3 {
                    self.physics
                        .add_impulse_at(body, com, fwd * (accel * dt * mass));
                }
            }
            c.steer_angle = angle;
            c.speed = speed;
            c.wheels_in_contact = contacts;
            c.contacts = traces;
            if driving {
                let rpm = c.rpm(&spec);
                if !spec.gears.is_empty()
                    && rpm > spec.shift_up_rpm
                    && (c.gear as usize) + 1 < spec.gears.len()
                {
                    c.gear += 1;
                } else if rpm < spec.shift_down_rpm && c.gear > 0 {
                    c.gear -= 1;
                }
            } else {
                c.gear = 0;
            }
            if let Some(v) = self.vehicles.get_mut(&id) {
                v.controls = c;
            }
        }
    }

    /// A player hull swept `start` -> `end` against the world and the solid bodies.
    fn exit_hull_clear(&self, start: Vec3, end: Vec3, bodies: &[PropBody]) -> bool {
        let (mins, maxs) = (Vec3::new(-16.0, -16.0, 0.0), Vec3::new(16.0, 16.0, 72.0));
        let tr = self
            .collision
            .trace_box(start, end, mins, maxs, gm_collision::MASK_PLAYERSOLID);
        if tr.start_solid || tr.fraction < 1.0 {
            return false;
        }
        let ext = (maxs - mins) * 0.5;
        let center = (mins + maxs) * 0.5;
        let steps = ((end - start).length() / 4.0).ceil().max(1.0) as usize;
        for i in 0..=steps {
            let c = start.lerp(end, i as f32 / steps as f32) + center;
            for b in bodies {
                let inv = gm_sandbox::rotation(b.angles).inverse();
                let lc = inv * (c - b.pos);
                let (lx, ly, lz) = (inv * Vec3::X, inv * Vec3::Y, inv * Vec3::Z);
                let inside = b.hulls.iter().any(|h| {
                    h.iter().all(|&(n, d)| {
                        let r = n.dot(lx).abs() * ext.x
                            + n.dot(ly).abs() * ext.y
                            + n.dot(lz).abs() * ext.z;
                        n.dot(lc) - d - r <= 0.0
                    })
                });
                if inside {
                    return false;
                }
            }
        }
        true
    }

    /// Seated players ride their vehicle's seat point; a vehicle that went drops its driver.
    fn ride_vehicles(&mut self) {
        let seated: Vec<(u32, u32)> = self
            .players
            .iter()
            .filter_map(|(id, p)| p.seat.map(|v| (*id, v)))
            .collect();
        for (player, veh) in seated {
            if !self.vehicles.contains_key(&veh)
                || !self.sandbox.props().iter().any(|p| p.id == veh)
            {
                if let Some(p) = self.players.get_mut(&player) {
                    p.seat = None;
                }
                continue;
            }
            let seat = self
                .vehicle_attachment(veh, "vehicle_feet_passenger0")
                .map(|a| a.0)
                .or_else(|| {
                    self.sandbox
                        .props()
                        .iter()
                        .find(|p| p.id == veh)
                        .map(|p| p.pos)
                });
            if let (Some(seat), Some(p)) = (seat, self.players.get_mut(&player)) {
                p.state.origin = seat;
                p.state.game_moved = true;
                p.state.velocity = Vec3::ZERO;
            }
        }
        self.vehicles
            .retain(|id, _| self.sandbox.props().iter().any(|p| p.id == *id));
    }

